// ------------------------------------------------------------
// 1С:Зарплата и управление персоналом 3.1 – автоматическое выполнение
// задания «Приём на работу»
// ------------------------------------------------------------
// Важно: скрипт предназначен для выполнения в режиме «Только чтение‑запись»
// (не меняет бизнес‑логику конфигурации). Запускайте его из обработчика
// «Общий модуль → Тестовое выполнение» или из внешней обработки.
// ------------------------------------------------------------

&НаКлиенте
Процедура ВыполнитьЗадание() Экспорт
    // 1. Подготовительные данные ------------------------------------------------
    // Тестовые сотрудники (ФИО, табельный номер, подразделение, должность, ставка)
    ТестовыеСотрудники = Новый Массив();
    ТестовыеСотрудники.Добавить(Новый Структура(
        "ФИО,ТабельныйНомер,Подразделение,Должность,Ставка",
        "Иванов Иван Иванович",      1001, "Отдел разработки", "Программист", 1.0));
    ТестовыеСотрудники.Добавить(Новый Структура(
        "ФИО,ТабельныйНомер,Подразделение,Должность,Ставка",
        "Петров Петр Петрович",      1002, "Бухгалтерия",       "Бухгалтер",    1.2));
    ТестовыеСотрудники.Добавить(Новый Структура(
        "ФИО,ТабельныйНомер,Подразделение,Должность,Ставка",
        "Сидорова Анна Сергеевна",   1003, "Отдел продаж",      "Менеджер",    1.0));

    // 2. Создание недостающих элементов справочников ---------------------------
    // Справочник "Подразделения"
    Для Каждого Сотрудник Из ТестовыеСотрудники Цикл
        Если Не СуществуетЭлемент(Справочники.Подразделения, Сотрудник.Подразделение) Тогда
            НовыйПодраздел = Справочники.Подразделения.СоздатьЭлемент();
            НовыйПодраздел.Наименование = Сотрудник.Подразделение;
            НовыйПодраздел.Записать();
        КонецЕсли;
    КонецЦикла;

    // Справочник "Должности"
    Для Каждого Сотрудник Из ТестовыеСотрудники Цикл
        Если Не СуществуетЭлемент(Справочники.Должности, Сотрудник.Должность) Тогда
            НоваяДолжность = Справочники.Должности.СоздатьЭлемент();
            НоваяДолжность.Наименование = Сотрудник.Должность;
            НоваяДолжность.Записать();
        КонецЕсли;
    КонецЦикла;

    // Справочник "Ставки"
    Для Каждого Сотрудник Из ТестовыеСотрудники Цикл
        // В справочнике «Ставки» ключом является числовое значение ставки
        Если Не СуществуетЭлемент(Справочники.Ставки, Сотрудник.Ставка) Тогда
            НоваяСтавка = Справочники.Ставки.СоздатьЭлемент();
            НоваяСтавка.Код = Сотрудник.Ставка; // код = значение ставки
            НоваяСтавка.Наименование = Строка(Сотрудник.Ставка);
            НоваяСтавка.Записать();
        КонецЕсли;
    КонецЦикла;

    // 3. Создание записей справочника «Сотрудники» ----------------------------
    Для Каждого Сотрудник Из ТестовыеСотрудники Цикл
        Если Не СуществуетЭлемент(Справочники.Сотрудники, Сотрудник.ТабельныйНомер) Тогда
            НовыйСотрудник = Справочники.Сотрудники.СоздатьЭлемент();
            НовыйСотрудник.ФИО = Сотрудник.ФИО;
            НовыйСотрудник.ТабельныйНомер = Сотрудник.ТабельныйНомер;
            // Ссылка на уже существующие элементы справочников
            НовыйСотрудник.Подразделение = Справочники.Подразделения.НайтиПоНаименованию(Сотрудник.Подразделение);
            НовыйСотрудник.Должность    = Справочники.Должности.НайтиПоНаименованию(Сотрудник.Должность);
            НовыйСотрудник.Ставка       = Справочники.Ставки.НайтиПоКоду(Сотрудник.Ставка);
            НовыйСотрудник.Записать();
        КонецЕсли;
    КонецЦикла;

    // 4. Оформление и проведение документов «Приём» ---------------------------
    Для Каждого Сотрудник Из ТестовыеСотрудники Цикл
        ПриёмДок = Документы.Прием.СоздатьДокумент();
        ПриёмДок.Дата = ТекущаяДата();
        ПриёмДок.Основание = "Тестовое приёмное основание";
        ПриёмДок.Подразделение = Справочники.Подразделения.НайтиПоНаименованию(Сотрудник.Подразделение);
        ПриёмДок.Должность    = Справочники.Должности.НайтиПоНаименованию(Сотрудник.Должность);
        ПриёмДок.Ставка       = Справочники.Ставки.НайтиПоКоду(Сотрудник.Ставка);
        ПриёмДок.Сотрудник    = Справочники.Сотрудники.НайтиПоТабельномуНомеру(Сотрудник.ТабельныйНомер);
        ПриёмДок.Записать();
        // Проведение
        ПриёмДок.Провести();
    КонецЦикла;

    // 5. Проверка регистра «Начисления» (опционально, только просмотр) -----------
    // Открываем регистр в режиме просмотра и выводим количество записей
    РегНачисления = РегистрыНакопления.Начисления;
    Выборка = РегНачисления.Выбрать();
    КолЗаписей = 0;
    Пока Выборка.Следующий() Цикл
        КолЗаписей = КолЗаписей + 1;
    КонецЦикла;
    Сообщить("В регистре «Начисления» найдено записей: " + КолЗаписей);

    // 6. Формирование отчёта «Список сотрудников» ----------------------------
    ПараметрыОтчета = Новый Структура();
    // Фильтр «Все», сортировка по табельному номеру
    ПараметрыОтчета.Вставить("Сортировка", "ТабельныйНомер");
    Отчет = Отчеты.СписокСотрудников.СоздатьОтчет();
    Отчет.УстановитьПараметры(ПараметрыОтчета);
    // Получаем табличный документ
    ТабДок = Отчет.ПолучитьТабличныйДокумент();
    // Сохраняем в Excel
    ПутьКФайлу = "C:\Temp\СписокСотрудников.xlsx";
    ТабДок.Экспортировать(ПутьКФайлу, "Excel");
    Сообщить("Отчёт сохранён в: " + ПутьКФайлу);

    // 7. Итоговый текстовый отчёт --------------------------------------------
    ТекстОтчета = "Выполнено задание по приёму трёх тестовых сотрудников.\n" +
                 "Созданы справочники: Подразделения (Отдел разработки, Бухгалтерия, Отдел продаж), " +
                 "Должности (Программист, Бухгалтер, Менеджер), Ставки (1.0, 1.2).\n" +
                 "В справочнике Сотрудники добавлены записи с табельными номерами 1001‑1003.\n" +
                 "Оформлены и проведены документы Приём для каждого сотрудника.\n" +
                 "Сформирован отчёт «Список сотрудников», экспортирован в Excel (C:\Temp\СписокСотрудников.xlsx).";
    Сообщить(ТекстОтчета);
КонецПроцедуры

// ------------------------------------------------------------
// Вспомогательная функция – проверка наличия элемента в справочнике
// ------------------------------------------------------------
Функция СуществуетЭлемент(Справочник, Ключ) Экспорт
    // Для справочников, где ключ – Наименование (строка)
    Если ТипЗнч(Ключ) = Тип("Строка") Тогда
        Элемент = Справочник.НайтиПоНаименованию(Ключ);
    ИначеЕсли ТипЗнч(Ключ) = Тип("Число") Тогда
        // Для справочников, где ключ – Код (число)
        Элемент = Справочник.НайтиПоКоду(Ключ);
    ИначеЕсли ТипЗнч(Ключ) = Тип("Дата") Тогда
        Элемент = Справочник.НайтиПоДате(Ключ);
    Иначе
        Элемент = Неопределено;
    КонецЕсли;
    Возврат Не Пусто(Элемент);
КонецФункции

// ------------------------------------------------------------
// Примечание: путь "C:\Temp" должен существовать на клиентском компьютере.
// При необходимости измените переменную ПутьКФайлу.
// ------------------------------------------------------------

assignment.description:
Цель задания – закрепить навыки работы с базовыми справочниками и типовыми документами конфигурации «1С:Зарплата и управление персоналом 3.1», а также умение переключаться между режимами «Только просмотр» и «Чтение‑запись». Студенту необходимо в рамках собственного проекта выполнить следующие шаги:
1. **Настройка справочников** – проверить наличие записей в справочниках Сотрудники, Должности, Подразделения, Ставки, Надбавки; при отсутствии создать новые элементы, заполнив все обязательные реквизиты (ФИО, табельный номер, дата приёма, должность, подразделение, ставка и т.д.).
2. **Оформление документов «Приём»** – для каждого нового сотрудника открыть форму документа «Приём», переключить её в режим «Чтение‑запись», заполнить реквизиты (Дата, Сотрудник, Должность, Подразделение, Ставка, Надбавка при необходимости) и провести документ.
3. **Генерация отчёта** – запустить встроенный отчёт «Список сотрудников», задать сортировку по табельному номеру, экспортировать результат в файл Excel (например, C:\Temp\СписокСотрудников.xlsx).
4. **Подготовка итогового отчёта** – собрать всё в один Markdown‑документ, включив:
   - краткое введение и цель;
   - описание выполненных действий по каждому пункту;
   - скриншоты форм справочников и документа «Приём» (PNG/JPG);
   - фрагмент кода (скрипт из примера или собственный 1C‑код) в блоке ```1C```;
   - ссылку на экспортированный файл Excel;
   - выводы о полученных результатах.
Обязательные разделы отчёта: **Введение**, **Настройка справочников**, **Оформление документов**, **Отчёт «Список сотрудников»**, **Выводы**. Итоговый файл загружается единственным документом.

