//===================================================================
//  Процедура: ЭкспортНачисленийВExcel
//  Описание: Открывает регистр накопления "Начисления",
//            отбирает записи за текущий месяц и сохраняет их в файл Excel.
//===================================================================
&НаКлиенте
Процедура ЭкспортНачисленийВExcel()
    Попытка
        // 1. Получаем ссылку на регистр накопления "Начисления"
        Регистратор = РегистрыНакопления.Начисления;

        // 2. Формируем запрос к регистру.
        //    Выбираем необходимые реквизиты: Дата, Сотрудник, Ставка, СуммаНачисления и др.
        ТекстЗапроса = "ВЫБРАТЬ" +
                       "   Начисления.Дата КАК Дата," +
                       "   Начисления.Сотрудник КАК Сотрудник," +
                       "   Начисления.Ставка КАК Ставка," +
                       "   Начисления.СуммаНачисления КАК Сумма" +
                       " ИЗ" +
                       "   РегистрНакопления.Начисления КАК Начисления" +
                       " ГДЕ" +
                       "   Начисления.Дата МЕЖДУ &НачалоМесяца И &КонецМесяца";

        // 3. Вычисляем границы текущего месяца.
        ТекущийГод = ТекущийГод();
        ТекущийМесяц = ТекущийМесяц();
        ДатаНачала = НачалоМесяца(ТекущийГод, ТекущийМесяц);
        ДатаОкончания = КонецМесяца(ТекущийГод, ТекущийМесяц);

        // 4. Создаём объект запроса и передаём параметры.
        Запрос = Новый Запрос;
        Запрос.Текст = ТекстЗапроса;
        Запрос.УстановитьПараметр("НачалоМесяца", ДатаНачала);
        Запрос.УстановитьПараметр("КонецМесяца", ДатаОкончания);

        // 5. Выполняем запрос и получаем результат во временную таблицу.
        Результат = Запрос.Выполнить();
        ВременнаяТаблица = Результат.Выгрузить(); // тип: ТаблицаЗначений

        // 6. Если записей нет – информируем пользователя и завершаем.
        Если ВременнаяТаблица.Количество() = 0 Тогда
            Сообщить("За текущий месяц в регистре \"Начисления\" нет записей.");
            Возврат;
        КонецЕсли;

        // 7. Создаём объект Excel.Application (COM‑объект).
        Excel = Новый COMОбъект("Excel.Application");
        Excel.Visible = Ложь; // скрыть окно Excel
        Книга = Excel.Workbooks.Add();
        Лист = Книга.Worksheets(1);

        // 8. Заполняем заголовки столбцов.
        Заголовки = ВременнаяТаблица.Колонки;
        Для i = 1 По Заголовки.Количество() Цикл
            Лист.Cells(1, i).Value = Заголовки[i].Имя;
        КонецЦикла;

        // 9. Записываем данные из временной таблицы в лист Excel.
        Для i = 0 По ВременнаяТаблица.Количество() - 1 Цикл
            Строка = ВременнаяТаблица[i];
            Для j = 1 По Заголовки.Количество() Цикл
                Лист.Cells(i + 2, j).Value = Строка[Заголовки[j].Имя];
            КонецЦикла;
        КонецЦикла;

        // 10. Формируем имя файла (в папке "Документы" пользователя).
        ПутьКФайлу = ПолучитьИмяФайлаДляСохранения("Начисления_" + Формат(ДатаНачала, "ГГГГММ") + ".xlsx");

        // 11. Сохраняем книгу и закрываем Excel.
        Книга.SaveAs(ПутьКФайлу);
        Книга.Close();
        Excel.Quit();

        // 12. Освобождаем COM‑объекты.
        ОсвободитьCOMОбъект(Excel);

        // 13. Информируем пользователя об успешном завершении.
        Сообщить("Экспорт регистра \"Начисления\" за " + Формат(ДатаНачала, "dd.MM.yyyy") + " - " + Формат(ДатаОкончания, "dd.MM.yyyy") + " выполнен. Файл сохранён: " + ПутьКФайлу);

    Исключение
        // Обработка любой ошибки, возникшей в процессе экспорта.
        Сообщить("Ошибка при экспорте регистра Начисления в Excel: " + ОписаниеОшибки());
        // При необходимости можно добавить логирование ошибки в файл.
    КонецПопытки;
КонецПроцедуры

//===================================================================
// Вспомогательная функция: получение пути для сохранения файла.
//===================================================================
Функция ПолучитьИмяФайлаДляСохранения(ИмяФайла)
    // Папка "Документы" текущего пользователя.
    ПапкаДокументов = ПолучитьПутьКПапке(КаталогДокументов);
    Возврат ПапкаДокументов + "\\" + ИмяФайла;
КонецФункции

//===================================================================
// Вспомогательная процедура: корректное освобождение COM‑объекта.
//===================================================================
Процедура ОсвободитьCOMОбъект(Объект)
    Если Не ЗначениеЗаполнено(Объект) Тогда
        Возврат;
    КонецЕсли;
    // Для 1С:Предприятие 8.3 используется метод Release.
    Попытка
        Объект.Release();
    Исключение
        // Игнорируем ошибки освобождения.
    КонецПопытки;
КонецПроцедуры

assignment.description:
В рамках вашего собственного проекта (например, разработки модуля интеграции с 1С или создания вспомогательного сервиса) подготовьте тестовую информационную базу 1С:Зарплата и управление персоналом 3.1 и задокументируйте выполненные действия.

**Что необходимо сделать**:
1. Установить типовую конфигурацию «ЗУП 3.1» в режиме «Тест», создать новую файловую ИБ и зафиксировать параметры (имя, путь, логин/пароль). Сохраните скриншоты ключевых диалогов.
2. Создать две роли – **HR_Viewer** и **Finance_Viewer** – с правом только просмотра справочников. Экспортировать роли в файлы *.erf* и приложить ссылки на их импорт в тестовую базу.
3. Выполнить полное резервное копирование тестовой ИБ, затем восстановить её в новую базу. Зафиксировать порядок действий, указать использованные команды/меню и приложить скриншоты подтверждающие целостность данных.
4. На основе выполненных шагов составить чек‑лист готовности рабочего места (пунктов минимум 5, включая проверку антивируса, актуальности резервных копий, доступности конфигурации, корректности ролей и возможности входа в тестовую базу).

**Итоговый файл** – отчёт в формате Markdown (или PDF/Docx), содержащий:
- Текстовое описание каждого этапа;
- Скриншоты (встроенные изображения) или ссылки на них;
- Код PlantUML/mermaid диаграммы процесса резервного копирования и восстановления;
- Таблицу с параметрами ролей и их экспортными файлами;
- Чек‑лист готовности.
Все ссылки должны указывать на файлы в вашем репозитории проекта.

