// ------------------------------------------------------------
// Пример настройки параметров расчёта в конфигурации
// «1С:Зарплата и управление персоналом 3.1»
// ------------------------------------------------------------
// Данный скрипт можно выполнить в обработке «Выполнение кода»
// (или в любой внешней обработке/отчёте, где доступен объект
//  Справочники). Он демонстрирует:
//   1. Установку ставок налогов и страховых взносов;
//   2. Настройку правил округления;
//   3. Сохранение изменений в справочнике «Параметры расчёта».
// ------------------------------------------------------------

Процедура НастроитьПараметрыРасчёта()
    // Получаем ссылку на справочник "Параметры расчёта"
    Параметры = Справочники.ПараметрыРасчёта;

    // Открываем (или создаём) запись с кодом "Основные" –
    // в типовой конфигурации обычно существует одна запись.
    // Если запись уже существует, она будет получена, иначе – создана.
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ ПараметрыРасчёта" +
        " ГДЕ ПараметрыРасчёта.Код = &Код";
    Запрос.УстановитьПараметр("Код", "Основные");
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    Если Выборка.Следующий() Тогда
        ТекущийПараметр = Выборка.ПараметрыРасчёта;
    Иначе
        ТекущийПараметр = Параметры.СоздатьЭлемент();
        ТекущийПараметр.Код = "Основные";
        ТекущийПараметр.Наименование = "Параметры расчёта (основные)";
    КонецЕсли;

    // --------------------------------------------------------
    // 1. Установка ставок налогов и страховых взносов
    // --------------------------------------------------------
    // Ставка НДФЛ (в %). По умолчанию 13%.
    ТекущийПараметр.СтавкаНДФЛ = 13;

    // Ставка страховых взносов в Фонд ОПС (в %).
    // Пример: 22% (включает 2,9% в ФСС, 5,1% в ФОМС, 14% в ПФР).
    ТекущийПараметр.СтавкаСтраховыхВзносов = 22;

    // Ставка страховых взносов в Фонд ОТ (в %).
    // По умолчанию 0,2%.
    ТекущийПараметр.СтавкаСтраховыхВзносовОТ = 0,2;

    // Ставка страховых взносов в Фонд ПВ (в %).
    // По умолчанию 0,2%.
    ТекущийПараметр.СтавкаСтраховыхВзносовПВ = 0,2;

    // --------------------------------------------------------
    // 2. Настройка правил округления
    // --------------------------------------------------------
    // Тип округления: "Округление в большую сторону", "Округление в меньшую сторону",
    // "Округление к ближайшему".
    ТекущийПараметр.ТипОкругления = Перечисления.ТипОкругления.ОкруглениеКБлижайшему;

    // Шаг округления (в рублях). Например, 0,01 – округление до копеек.
    ТекущийПараметр.ШагОкругления = 0,01;

    // Признак округления в большую сторону при расчёте налогов.
    // Если Истина – налог округляется в большую сторону, иначе – к ближайшему.
    ТекущийПараметр.ОкруглятьНалогВБольшуюСторону = Ложь;

    // --------------------------------------------------------
    // 3. Сохранение изменений
    // --------------------------------------------------------
    Попытка
        ТекущийПараметр.Записать();
        Сообщить("Параметры расчёта успешно сохранены.");
    Исключение
        Сообщить("Ошибка при сохранении параметров: " + ОписаниеОшибки());
    КонецПопытки;
КонецПроцедуры

// ------------------------------------------------------------
// Вызов процедуры (можно привязать к кнопке формы или выполнить
// вручную в обработке).
// ------------------------------------------------------------
НастроитьПараметрыРасчёта();

// Пример получения сумм начислений за текущий месяц
// из регистра "Начисления" (РегистрыНакопления.Начисления)

Процедура ПолучитьСуммыНачисленийЗаТекущийМесяц()
    // ------------------------------------------------------------
    // 1. Формируем объект запроса
    // ------------------------------------------------------------
    Запрос = Новый Запрос;

    // ------------------------------------------------------------
    // 2. Текст запроса (SELECT). В запросе используем параметр ДатаНачала
    //    и ДатаОкончания, чтобы ограничить выборку текущим месяцем.
    //    Считаем сумму начислений (Сумма) по каждому сотруднику.
    // ------------------------------------------------------------
    ТекстЗапроса = 
        "ВЫБРАТЬ
" +
        "    Начисления.Сотрудник КАК Сотрудник,
" +
        "    СУММА(Начисления.Сумма) КАК СуммаНачисления
" +
        "ИЗ
" +
        "    РегистрыНакопления.Начисления КАК Начисления
" +
        "ГДЕ
" +
        "    Начисления.Период МЕЖДУ &ДатаНачала И &ДатаОкончания
" +
        "СГРУППИРОВАТЬ ПО
" +
        "    Начисления.Сотрудник";

    Запрос.Текст = ТекстЗапроса;

    // ------------------------------------------------------------
    // 3. Устанавливаем параметры даты – первый и последний день текущего месяца.
    // ------------------------------------------------------------
    ТекущаяДата = ТекущаяДата(); // Текущая дата и время
    ДатаНачала = НачалоМесяца(ТекущаяДата);
    ДатаОкончания = КонецМесяца(ТекущаяДата);

    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    // ------------------------------------------------------------
    // 4. Выполняем запрос и получаем результат в виде набора записей.
    // ------------------------------------------------------------
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    // ------------------------------------------------------------
    // 5. Выводим полученные суммы в консоль (Message).
    //    Если записей нет – выводим соответствующее сообщение.
    // ------------------------------------------------------------
    Если Выборка.Следующий() Тогда
        Пока Выборка.Следующий() Цикл
            // Сотрудник – это ссылка на справочник "Сотрудники"
            // СуммаНачисления – тип Число (денежные единицы)
            ТекстСообщения = "Сотрудник: " + Выборка.Сотрудник.Наименование +
                             ", Сумма начислений: " + Формат(Выборка.СуммаНачисления, "ЧГ=2");
            Message(ТекстСообщения);
        КонецЦикла;
    Иначе
        Message("За текущий месяц начислений не найдено.");
    КонецЕсли;
КонецПроцедуры;

// ------------------------------------------------------------
// Вызов процедуры (например, из обработчика кнопки формы)
// ------------------------------------------------------------
ПолучитьСуммыНачисленийЗаТекущийМесяц();

assignment.description:
**Цель задания** – закрепить навыки быстрой навигации в конфигураторе 1С:ЗУП 3.1 и оформить полученные сведения в виде отчёта, применив теорию к своему проекту.

**Контекст** – у вас уже есть собственная конфигурация 1С, разрабатываемая в рамках проектной деятельности. В этом задании вы работаете именно с ней.

**Что нужно сделать**:
1. Откройте Конфигуратор и определите, какие из трёх ключевых подсистем (Кадровый учёт, Расчёт заработной платы, Бенефиты и социальные выплаты) присутствуют в вашей конфигурации.
2. Для каждой найденной подсистемы перечислите минимум **по три типовых объекта** (справочник, документ, регистр, обработка/отчёт). Укажите название и короткое назначение (1‑2 предложения).
3. Сделайте скриншоты окна Конфигуратора, где виден список объектов подсистемы, и вставьте их в отчёт.
4. Сформируйте **UML‑диаграмму компонентов** (PlantUML‑код или изображение), показывающую связи «подсистема → объект». Диаграмма должна быть синтаксически корректна.
5. Добавьте раздел **«Навигация в Конфигураторе»**, где пошагово опишите, как искать и открывать каждый объект (поиск, фильтрация, двойной клик).
6. При необходимости укажите ссылки (URL или относительный путь) на соответствующие обработки/фрагменты кода в репозитории проекта.

**Итоговый файл** – один документ (Markdown, PDF или DOCX) объёмом ≤ 5 МБ, максимум 12 страниц, содержащий:
- Введение (краткое описание проекта);
- Таблицу «Подсистема – объекты»;
- Скриншоты с подписями;
- UML‑диаграмму компонентов;
- Описание навигации;
- При необходимости ссылки на код.

content_blocks.code:
// ------------------------------------------------------------
// Пошаговый сценарий создания и заполнения справочников
// в конфигурации «1С:Зарплата и управление персоналом 3.1»
// ------------------------------------------------------------

/*
  Шаг 1. Открытие справочника «Сотрудники» и создание новой записи
  -----------------------------------------------------------
  1. В главном меню выберите **Справочники → Персонал → Сотрудники**.
  2. Нажмите кнопку **Создать** (или клавишу F6).
  3. Заполните обязательные реквизиты:
     • **Фамилия**, **Имя**, **Отчество** – ФИО сотрудника.
     • **Табельный номер** – уникальный код (по умолчанию генерируется автоматически).
     • **Дата рождения** – дата рождения.
     • **Подразделение** – выберите из списка (по умолчанию «Не назначено»).
  4. При необходимости задайте дополнительные реквизиты (должность, ставка и т.д.).
  5. Нажмите **Записать и закрыть** (Ctrl+Enter).
*/

/*
  Шаг 2. Открытие справочника «Должности» и создание новой должности
  -----------------------------------------------------------
  1. **Справочники → Персонал → Должности**.
  2. **Создать**.
  3. Заполните реквизиты:
     • **Код** – уникальный идентификатор (например, "HR_MANAGER").
     • **Наименование** – «Менеджер по персоналу».
     • **Подразделение** – укажите подразделение, к которому относится должность.
  4. Сохраните запись.
*/

/*
  Шаг 3. Открытие справочника «Подразделения» и создание нового подразделения
  -----------------------------------------------------------
  1. **Справочники → Персонал → Подразделения**.
  2. **Создать**.
  3. Заполните реквизиты:
     • **Код** – например, "HR".
     • **Наименование** – «Отдел кадров».
     • **Родитель** – если подразделение вложено в другое, укажите родителя.
  4. Сохраните запись.
*/

/*
  Шаг 4. Открытие справочника «Ставки» и создание новой ставки
  -----------------------------------------------------------
  1. **Справочники → Персонал → Ставки**.
  2. **Создать**.
  3. Заполните реквизиты:
     • **Код** – «STAVKA_1» (уникальный).
     • **Наименование** – «Оклад 1».
     • **Ставка** – числовое значение (например, 50000).
     • **Дата начала действия** – текущая дата.
     • **Дата окончания действия** – оставьте пустой, если ставка действует постоянно.
  4. Сохраните запись.
*/

/*
  Шаг 5. Открытие справочника «Надбавки» и создание надбавки (по желанию)
  -----------------------------------------------------------
  1. **Справочники → Персонал → Надбавки**.
  2. **Создать**.
  3. Заполните реквизиты:
     • **Код**, **Наименование**, **Сумма** (или **Процент**).
  4. Сохраните запись.
*/

// ------------------------------------------------------------
// Пример кода: создание новой записи в справочнике «Ставки»
// ------------------------------------------------------------

/*
  Данный фрагмент можно разместить в обработке, модуле формы
  или в обычном внешнем обработчике (например, в кнопке «Создать ставку»).
*/

&AtClient
Процедура СоздатьНовуюСтавку()
    // 1. Создаём объект справочника Ставки
    НоваяСтавка = Справочники.Ставки.СоздатьЭлемент();

    // 2. Заполняем обязательные реквизиты
    НоваяСтавка.Код = "STAVKA_1";               // Уникальный код ставки
    НоваяСтавка.Наименование = "Оклад 1";       // Человекочитаемое название
    НоваяСтавка.Ставка = 50000;                  // Размер оклада (руб.)
    НоваяСтавка.ДатаНачала = ТекущаяДата();      // Дата начала действия
    // Дата окончания оставляем пустой – ставка будет действовать пока её не изменят

    // 3. Сохраняем запись в базе данных
    НоваяСтавка.Записать();

    // 4. Выводим сообщение пользователю
    Сообщить("Создана ставка: " + НоваяСтавка.Наименование + " (" + Формат(НоваяСтавка.Ставка, "ЧГ=0") + ")");
КонецПроцедуры

/*
  Пояснение к каждой строке:
  • `Справочники.Ставки.СоздатьЭлемент()` – создаёт объект‑запись справочника «Ставки» в памяти.
  • `Код`, `Наименование`, `Ставка`, `ДатаНачала` – реквизиты, которые мы заполняем.
  • `Записать()` – сохраняет запись в базе (выполняет INSERT/UPDATE).
  • `Сообщить()` – выводит информационное окно пользователю.
*/

// ------------------------------------------------------------
// Пример кода: привязка созданной ставки к должности
// ------------------------------------------------------------

&AtClient
Процедура ПривязатьСтавкуКДолжности()
    // 1. Находим нужную должность (по коду). Предположим, что она уже существует.
    Должность = Справочники.Должности.НайтиПоКоду("HR_MANAGER");
    Если Должность = НеОпределено Тогда
        Предупреждение("Должность с кодом HR_MANAGER не найдена.");
        Возврат;
    КонецЕсли;

    // 2. Находим ставку, которую только что создали (по коду).
    Ставка = Справочники.Ставки.НайтиПоКоду("STAVKA_1");
    Если Ставка = НеОпределено Тогда
        Предупреждение("Ставка с кодом STAVKA_1 не найдена.");
        Возврат;
    КонецЕсли;

    // 3. Привязываем ставку к должности.
    // В конфигурации «Зарплата и управление персоналом» у должности есть реквизит "Ставка".
    Должность.Ставка = Ставка;   // Устанавливаем ссылку на объект справочника Ставки

    // 4. Сохраняем изменения в должности.
    Должность.Записать();

    // 5. Информируем пользователя.
    Сообщить("Ставка " + Ставка.Наименование + " привязана к должности " + Должность.Наименование);
КонецПроцедуры

/*
  Что делает код:
  1. `НайтиПоКоду` ищет запись в справочнике по полю «Код». Если запись не найдена – возвращается `НеОпределено`.
  2. После получения объектов `Должность` и `Ставка` мы просто присваиваем реквизиту `Ставка` ссылки на объект `Ставка`.
  3. `Записать()` фиксирует изменение в базе.
*/

// ------------------------------------------------------------
// Итоги
// ------------------------------------------------------------
// 1. Открыв нужный справочник, пользователь заполняет обязательные реквизиты и сохраняет запись.
// 2. Для автоматизации можно использовать приведённые выше процедуры – они позволяют создавать ставки и привязывать их к должностям без ручного ввода.
// 3. Все комментарии написаны простым языком, чтобы даже новичок понял смысл каждой операции.

/*===================================================================
   Урок 2. Справочники персонала и организационной структуры
   Тема: Формирование «Карточки сотрудника» в виде PDF‑отчёта
===================================================================*/

/*===================================================================
  1. Создание нового отчёта в конфигураторе
===================================================================*/
// 1.1 Откройте конфигуратор 1С и подключитесь к базе «Зарплата и управление персоналом 3.1».
// 1.2 В дереве конфигурации выберите раздел «Отчёты» → «Отчёты» → «Новый».
// 1.3 В появившемся мастере укажите:
//      • Имя объекта:            ОтчетКарточкаСотрудника
//      • Наименование:          "Карточка сотрудника"
//      • Тип:                    Обычный (не табличный)
// 4. Нажмите «Готово».  Конфигуратор создаст объект отчёта и откроет его свойства.

/*===================================================================
  2. Добавление реквизитов сотрудника в макет отчёта
===================================================================*/
// 2.1 Откройте объект «ОтчетКарточкаСотрудника» → вкладка «Макет» → «Новый макет».
// 2.2 Выберите тип макета «XML» (рекомендовано – более гибкое позиционирование).
// 2.3 Сохраните макет под именем «КарточкаСотрудника.xml».
// 2.4 Вставьте в макет следующий XML‑шаблон (см. ниже). В нём объявлены
//     поля‑заполнители, которые будут заполняться данными из справочника
//     «Сотрудники».

/*===================================================================
  3. Обработчик, который получает текущую запись справочника «Сотрудники»
     и передаёт её в отчёт
===================================================================*/
// 3.1 В конфигураторе создайте новый объект «Объект» → «Обработки» → «Новый».
// 3.2 Назовите обработку «ПечатьКарточкиСотрудника». В ней будет код,
//     вызывающий отчёт и передающий в него параметры.

// ---------- Файл: ПечатьКарточкиСотрудника/Модуль/ОсновнойМодуль/МодульОбработки.bsl ----------
&НаКлиенте
Процедура ПечатьКарточкиСотрудника(Команда)
    // Получаем текущий выбранный элемент справочника "Сотрудники"
    // (в типичном случае обработка вызывается из формы списка или карточки).
    Если Не ЗначениеЗаполнено(ЭтаФорма) Тогда
        Предупреждение("Объект формы не определён");
        Возврат;
    КонецЕсли;

    // Ссылка на текущий элемент справочника "Сотрудники"
    Сотрудник = ЭтаФорма.Элемент;
    Если Сотрудник = Неопределено Тогда
        Предупреждение("Не выбран сотрудник");
        Возврат;
    КонецЕсли;

    // Формируем параметры отчёта
    ПараметрыОтчёта = Новый Структура;
    ПараметрыОтчёта.Вставить("СсылкаНаСотрудника", Сотрудник.Ссылка);

    // Создаём объект отчёта
    Отчет = Отчеты.ОтчетКарточкаСотрудника.Создать();
    // Передаём параметры
    Отчет.Параметры = ПараметрыОтчёта;

    // Указываем путь и имя PDF‑файла (можно запросить у пользователя)
    ПутьКФайлу = "C:\Отчёты\Карточка_" + Сотрудник.ФИО + ".pdf";

    // Печатаем в PDF
    Попытка
        // Параметр "PDF" – тип экспорта, "ИмяФайла" – куда сохранять
        Отчет.ЭкспортироватьВФайл(ПутьКФайлу, "PDF");
        Сообщить("Карточка сотрудника сохранена в " + ПутьКФайлу);
    Исключение
        Сообщить("Ошибка при экспорте в PDF: " + ОписаниеОшибки());
    КонецПопытки;
КонецПроцедуры

/*===================================================================
  4. Настройка экспорта в PDF (указание пути, имени файла)
===================================================================*/
// В примере выше путь задаётся жёстко, но в реальном решении лучше
// использовать диалог выбора папки/имени:
//   Диалог = Новый ДиалогВыбораФайла();
//   Диалог.Заголовок = "Сохранить карточку сотрудника";
//   Диалог.Фильтр = "PDF‑файлы (*.pdf)|*.pdf";
//   Если Диалог.Выбрать() Тогда
//       ПутьКФайлу = Диалог.ПолноеИмяФайла;
//   КонецЕсли;

/*===================================================================
  5. Пример XML‑шаблона макета отчёта
===================================================================*/
// Файл: ОтчетКарточкаСотрудника/Макеты/КарточкаСотрудника.xml

<?xml version="1.0" encoding="utf-8"?>
<Report xmlns="http://www.1c.ru/Report/2008" Name="КарточкаСотрудника" >
    <!-- Описание параметров, которые будут переданы из обработчика -->
    <Parameters>
        <Parameter Name="СсылкаНаСотрудника" Type="Reference" RefObject="Справочник.Сотрудники" />
    </Parameters>

    <!-- Тело отчёта -->
    <Body>
        <!-- Таблица‑контейнер, в которой будем выводить данные -->
        <Table Name="ТаблицаСотрудника" Width="190mm" Border="1" >
            <Columns>
                <Column Width="30mm" />
                <Column Width="160mm" />
            </Columns>
            <!-- Строка – ФИО -->
            <Row Height="10mm" >
                <Cell>
                    <Text>ФИО:</Text>
                </Cell>
                <Cell>
                    <Text Expression="СсылкаНаСотрудника.ФИО" />
                </Cell>
            </Row>
            <!-- Строка – Должность -->
            <Row Height="10mm" >
                <Cell>
                    <Text>Должность:</Text>
                </Cell>
                <Cell>
                    <Text Expression="СсылкаНаСотрудника.Должность" />
                </Cell>
            </Row>
            <!-- Строка – Подразделение -->
            <Row Height="10mm" >
                <Cell>
                    <Text>Подразделение:</Text>
                </Cell>
                <Cell>
                    <Text Expression="СсылкаНаСотрудника.Подразделение" />
                </Cell>
            </Row>
            <!-- Строка – Ставка -->
            <Row Height="10mm" >
                <Cell>
                    <Text>Ставка:</Text>
                </Cell>
                <Cell>
                    <Text Expression="СсылкаНаСотрудника.Ставка" />
                </Cell>
            </Row>
            <!-- Строка – Надбавки (можно вывести список) -->
            <Row Height="10mm" >
                <Cell>
                    <Text>Надбавки:</Text>
                </Cell>
                <Cell>
                    <!-- Выводим перечисление всех надбавок, связанных с сотрудником -->
                    <Text Expression="StringJoin(СсылкаНаСотрудника.Надбавки, ", ")" />
                </Cell>
            </Row>
        </Table>
    </Body>

    <!-- Параметры экспорта в PDF (можно задать в свойствах отчёта) -->
    <ExportSettings>
        <ExportFormat Name="PDF" />
    </ExportSettings>
</Report>

/*===================================================================
  6. Итоги и рекомендации
===================================================================*/
// • При изменении структуры справочника (добавление новых реквизитов) –
//   не забудьте добавить соответствующие поля в макет XML.
// • Для более гибкого формирования имени файла используйте свойства
//   сотрудника (например, ФИО без пробелов) и текущую дату.
// • Если требуется печать сразу нескольких карточек, реализуйте цикл
//   перебора списка сотрудников и вызывайте Отчет.ЭкспортироватьВФайл
//   в каждой итерации.
// • При работе в режиме «Веб‑клиент» вместо прямого указания пути к
//   диску используйте объект "ВременныйФайл" и предлагайте пользователю
//   скачать файл через браузер.

/*===================================================================
  Готово! Теперь у вас есть полностью рабочий механизм создания PDF‑
  карточки сотрудника из справочника «Сотрудники». При необходимости
  расширяйте макет, добавляйте графику (логотип компании) и подписи.
===================================================================*/

// Шаг 1 – Открыть форму «Настройки → Параметры расчёта» и создать набор «2024‑Год»

// 1.1 Открыть главное меню
Меню.Выбрать("Настройки", "Параметры расчёта");

// 1.2 В открывшейся форме нажать кнопку «Создать»
ФормаПараметрыРасчёта.НажатьКнопку("Создать");

// 1.3 Ввести название набора
ФормаПараметрыРасчёта.Поле("Наименование").УстановитьЗначение("2024‑Год");

// 1.4 Сохранить набор (кнопка «ОК»)
ФормаПараметрыРасчёта.НажатьКнопку("ОК");


// Шаг 2 – Добавить запись «НДФЛ» в раздел «Налоги»

// 2.1 Перейти на вкладку «Налоги»
ФормаПараметрыРасчёта.Вкладка("Налоги").Выбрать();

// 2.2 Нажать кнопку «Добавить»
ФормаПараметрыРасчёта.НажатьКнопку("Добавить");

// 2.3 Заполнить реквизиты записи
ФормаНалог.Поле("Наименование").УстановитьЗначение("НДФЛ");
ФормаНалог.Поле("Ставка").УстановитьЗначение(13); // %
ФормаНалог.Поле("База расчёта").УстановитьЗначение("База_до_налога");

// 2.4 Сохранить запись (кнопка «ОК»)
ФормаНалог.НажатьКнопку("ОК");


// Шаг 3 – Добавить запись «Взнос в ФСС» в раздел «Страховые взносы»

// 3.1 Перейти на вкладку «Страховые взносы»
ФормаПараметрыРасчёта.Вкладка("Страховые взносы").Выбрать();

// 3.2 Нажать кнопку «Добавить»
ФормаПараметрыРасчёта.НажатьКнопку("Добавить");

// 3.3 Заполнить реквизиты записи
ФормаВзнос.Поле("Наименование").УстановитьЗначение("Взнос в ФСС");
ФормаВзнос.Поле("Ставка").УстановитьЗначение(2.9); // %
ФормаВзнос.Поле("База расчёта").УстановитьЗначение("База_взносов");

// 3.4 Сохранить запись (кнопка «ОК»)
ФормаВзнос.НажатьКнопку("ОК");


// Шаг 4 – Создать правило округления «Округление в пользу работника»

// 4.1 Перейти на вкладку «Округление»
ФормаПараметрыРасчёта.Вкладка("Округление").Выбрать();

// 4.2 Нажать кнопку «Создать правило»
ФормаПараметрыРасчёта.НажатьКнопку("Создать правило");

// 4.3 Заполнить реквизиты правила
ФормаОкругление.Поле("Наименование").УстановитьЗначение("Округление в пользу работника");
ФормаОкругление.Поле("Тип округления").УстановитьЗначение("ОКРУГЛ(…,0,\"вверх\")");

// 4.4 Сохранить правило (кнопка «ОК»)
ФормаОкругление.НажатьКнопку("ОК");


// Шаг 5 – Сохранить набор параметров и сделать его активным для текущего периода

// 5.1 Нажать кнопку «Сохранить» в основной форме (если изменения ещё не сохранены)
ФормаПараметрыРасчёта.НажатьКнопку("Сохранить");

// 5.2 Открыть форму «Периоды расчёта»
Меню.Выбрать("Настройки", "Периоды расчёта");

// 5.3 Выбрать текущий период и установить набор параметров «2024‑Год»
ФормаПериоды.ТекущийПериод().Поле("Набор параметров").УстановитьЗначение("2024‑Год");

// 5.4 Подтвердить выбор (кнопка «ОК»)
ФормаПериоды.НажатьКнопку("ОК");

// ------------------------------------------------------------
// Комментарий для генератора скриншотов:
// 1) Окно «Настройки → Параметры расчёта» – список наборов, кнопки «Создать», «ОК», «Отмена».
// 2) Форма создания/редактирования записи налога – поля «Наименование», «Ставка», «База расчёта», кнопки «ОК», «Отмена».
// 3) Форма создания/редактирования страхового взноса – аналогичные элементы.
// 4) Форма создания правила округления – поле «Наименование», выпадающий список «Тип округления», кнопки «ОК», «Отмена».
// 5) Окно «Настройки → Периоды расчёта» – список периодов, колонка «Набор параметров», кнопка «ОК», «Отмена».
// Эти окна следует изобразить на скриншотах, чтобы студент видел, где нажимать.

//===================================================================
//  Модуль «ИмпортПараметровИзExcel»
//  Предназначен для загрузки параметров расчёта (ставки налогов,
//  страховых взносов, правила округления, календарные планы) из
//  Excel‑файла в справочник «Параметры расчёта» конфигурации
//  «1С:Зарплата и управление персоналом 3.1».
//===================================================================

&НаКлиенте
Процедура ИмпортироватьПараметрыИзExcel(Команда)
    // 1. Открываем диалог выбора файла Excel
    ВыборФайла = Новый ДиалогВыбораФайла();
    ВыборФайла.Заголовок = "Выберите файл Excel с параметрами расчёта";
    ВыборФайла.Фильтр = "Файлы Excel (*.xlsx;*.xls)|*.xlsx;*.xls|Все файлы (*.*)|*.*";
    Если НЕ ВыборФайла.Выбрать() Тогда
        Возврат; // пользователь отменил выбор
    КонецЕсли;

    // 2. Читаем данные из листа "Параметры" (первая строка – заголовки)
    ТаблицаExcel = Новый ТаблицаЗначений();
    Попытка
        ТаблицаExcel = ПолучитьТаблицуИзExcel(ВыборФайла.ПолныйПуть, "Параметры");
    Исключение
        Сообщить("Не удалось открыть файл Excel: " + ОписаниеОшибки());
        Возврат;
    КонецПопытки;

    // 3. Проверяем наличие обязательных колонок
    ОбязКолонки = Новый Массив();
    ОбязКолонки.Добавить("Код");          // Уникальный код параметра
    ОбязКолонки.Добавить("Наименование"); // Наименование
    ОбязКолонки.Добавить("Тип");          // Налог, Взнос, Округление, План
    ОбязКолонки.Добавить("Значение");      // Числовое значение или ссылка

    Для Каждого Колонка Из ОбязКолонки Цикл
        Если НЕ ТаблицаExcel.Колонки.Содержит(Колонка) Тогда
            Сообщить("В файле отсутствует обязательный столбец: " + Колонка);
            Возврат;
        КонецЕсли;
    КонецЦикла;

    // 4. Обходим строки и создаём/обновляем элементы справочника
    Для Каждого Строка Из ТаблицаExcel Цикл
        // Пропускаем пустые строки (может быть итоговая строка)
        Если ПустаяСтрока(Строка) Тогда
            Продолжить;
        КонецЕсли;

        Код = Строка.Код;
        Наименование = Строка.Наименование;
        Тип = Строка.Тип;
        Значение = Строка.Значение;

        // Поиск существующего элемента по коду
        Элемент = Справочники.ПараметрыРасчета.НайтиПоКоду(Код);
        Если Элемент = Неопределено Тогда
            // Создаём новый элемент
            Элемент = Справочники.ПараметрыРасчета.СоздатьЭлемент();
            Элемент.Код = Код;
        КонецЕсли;

        // Заполняем реквизиты
        Элемент.Наименование = Наименование;
        Элемент.Тип = Тип; // Предполагается перечисление "ТипПараметра"
        // Приводим значение к нужному типу в зависимости от типа параметра
        Если Тип = "Налог" ИЛИ Тип = "Взнос" Тогда
            Элемент.Значение = Число(Значение);
        ИначеЕсли Тип = "Округление" Тогда
            // Округление хранится как строка, например "0.01" или "0.1"
            Элемент.Значение = Строка(Значение);
        ИначеЕсли Тип = "План" Тогда
            // Ссылка на календарный план (справочник "КалендарныеПланы")
            План = Справочники.КалендарныеПланы.НайтиПоНаименованию(Строка(Значение));
            Если План = Неопределено Тогда
                Сообщить("Не найден календарный план: " + Строка(Значение));
                Продолжить;
            КонецЕсли;
            Элемент.Значение = План.Ссылка;
        КонецЕсли;

        // Сохраняем элемент
        Элемент.Записать();
    КонецЦикла;

    Сообщить("Импорт параметров завершён успешно.");
КонецПроцедуры

//===================================================================
// Вспомогательная функция – чтение листа Excel в ТаблицуЗначений
//===================================================================
Функция ПолучитьТаблицуИзExcel(ПутьКФайлу, ИмяЛиста) Экспорт
    // Для работы с Excel используется COM‑объект "Excel.Application".
    // В 1С:Предприятие 8.3+ рекомендуется использовать объектную модель
    // только в клиент‑приложении, поэтому функция объявлена как Экспорт.
    Попытка
        Excel = Новый COMОбъект("Excel.Application");
        Excel.Visible = Ложь;
        Книга = Excel.Workbooks.Open(ПутьКФайлу);
        Лист = Книга.Worksheets(ИмяЛиста);
        // Находим диапазон, содержащий данные (предполагаем, что первая строка – заголовки)
        ПоследняяСтрока = Лист.Cells(Лист.Rows.Count, 1).End(-4162).Row; // xlUp
        ПоследнийСтолбец = Лист.Cells(1, Лист.Columns.Count).End(-4159).Column; // xlToLeft
        Диапазон = Лист.Range(Лист.Cells(1,1), Лист.Cells(ПоследняяСтрока, ПоследнийСтолбец));
        Данные = Диапазон.Value2; // двумерный массив Variant
        // Формируем ТаблицуЗначений
        Таблица = Новый ТаблицаЗначений();
        // Первая строка – имена колонок
        Для i = 1 По ПоследнийСтолбец Цикл
            Таблица.Колонки.Добавить(Данные[1,i]);
        КонецЦикла;
        // Остальные строки – данные
        Для r = 2 По ПоследняяСтрока Цикл
            НоваяСтрока = Таблица.Добавить();
            Для c = 1 По ПоследнийСтолбец Цкл
                НоваяСтрока[Таблица.Колонки[c-1].Имя] = Данные[r,c];
            КонецЦикла;
        КонецЦикла;
        // Закрываем Excel без сохранения
        Книга.Close(Ложь);
        Excel.Quit();
        Возврат Таблица;
    Исключение
        // Гарантируем освобождение COM‑объекта
        Если Не Пустой(Excel) Тогда
            Excel.Quit();
        КонецЕсли;
        Сообщить("Ошибка при чтении Excel: " + ОписаниеОшибки());
        Возврат Неопределено;
    КонецПопытки;
КонецФункции

//===================================================================
// Примечание к использованию
//===================================================================
/*
  1. Сохраните модуль в конфигурации в разделе "Общие модули" под именем
     "ИмпортПараметровИзExcel".
  2. Добавьте кнопку на форму "Параметры расчёта" (или в любой удобный
     пользовательский интерфейс) и привяжите её к процедуре
     "ИмпортироватьПараметрыИзExcel".
  3. Формат Excel‑файла:
     ┌─────────────┬───────────────┬───────┬─────────────┐
     │   Код       │ Наименование  │ Тип   │  Значение   │
     ├─────────────┼───────────────┼───────┼─────────────┤
     │ TAX_INCOME  │ Налог на доход│ Налог │ 13          │
     │ INS_PENSION │ Взнос в ПФР   │ Взнос │ 22          │
     │ ROUND_01    │ Округление 0.01│ Округление│0.01   │
     │ CAL_PLAN_2024│ План 2024    │ План  │ "2024"     │
     └─────────────┴───────────────┴───────┴─────────────┘
     * Столбец «Тип» – значение из перечисления "ТипПараметра".
     * Для типа «План» в колонке «Значение» указывается наименование
       календарного плана, который уже существует в справочнике
       "КалендарныеПланы".
  4. После импорта откройте справочник "Параметры расчёта" и убедитесь,
     что все записи созданы/обновлены.
  5. При необходимости запустите регламентный процесс «Перерасчёт
     начислений», чтобы увидеть влияние новых параметров на расчёт
     зарплаты.
*/

assignment.description:
**Цель задания** – применить знания о налоговых ставках, страховых взносах, правилах округления и импорте параметров из Excel к вашему текущему проекту в конфигурации «1С:Зарплата и управление персоналом 3.1». **Контекст** – вы разрабатываете собственный проект (приложение/сервис/библиотеку), в котором используется модуль расчёта зарплаты. **Что нужно сделать**:
1. **Анализ текущих параметров** – откройте справочники «Налоговые ставки», «Страховые взносы», «Параметры расчёта» и зафиксируйте используемые значения (код, наименование, ставка, даты). Сформируйте таблицу в отчёте.
2. **Подготовка Excel‑файла** – создайте файл `Parameters_2024.xlsx` по шаблону (строки: Код, Наименование, Тип, Значение). Внесите в него новые ставки (например, НДФЛ 15 %, ПФР 22 %, округление 0,01 ₽) и/или измените календарный план.
3. **Импорт в 1С** – запустите процедуру «ИмпортироватьПараметрыИзExcel» (или аналогичный механизм). Зафиксируйте скриншот/лог успешного импорта.
4. **Сравнительный расчёт** – выполните скрипт сравнения расчётов до и после импорта для выбранного расчётного периода (например, один месяц). Сохраните полученную таблицу различий (чистая зарплата, удержания, взносы).
5. **Документирование результатов** – в отчёте опишите:
   - какие параметры изменены и почему;
   - как импорт прошёл (лог, скриншоты);
   - влияние изменений на расчёт (таблица сравнения, %‑изменения);
   - выводы о корректности настроек и рекомендациях для дальнейшего администрирования.
**Обязательные элементы отчёта**:
- Введение с кратким описанием вашего проекта и цели отчёта;
- Таблица «Исходные параметры»;
- Пример заполненного Excel‑файла (скриншот или вложение);
- Лог/скриншот импорта;
- Таблица сравнения расчётов (до/после);
- Аналитический раздел с выводами;
- Список использованных источников (нормативные документы).
Все элементы должны быть оформлены в одном файле Markdown (или PDF/Docx).

