// ────────────────────────────────────────────────────────────────────────
// Пошаговый практический сценарий «Настройка параметров расчёта в 1С:ЗУП 3.1»
// ────────────────────────────────────────────────────────────────────────
// 1. Описание последовательных действий в пользовательском интерфейсе
// ---------------------------------------------------------------------
// 1.1 Открыть «Справочники» → «Зарплата и управление персоналом» → «Параметры расчёта».
// 1.2 В открывшемся списке нажать кнопку «Создать» (или «Изменить», если запись уже существует).
// 1.3 Заполнить обязательные реквизиты:
//      • Код               – уникальный код параметра (например, "НДФЛ_2024").
//      • Наименование       – «Налог на доходы физических лиц 2024».
//      • Дата начала действия – 01.01.2024.
//      • Дата окончания действия – 31.12.2024 (можно оставить пустым, если действие бессрочно).
//      • Ставка               – 13% (0.13).
// 1.4 При необходимости задать дополнительные реквизиты:
//      • Ставка страховых взносов, правила округления, код фонда и т.д.
// 1.5 Нажать «Записать и закрыть». При вводе неверных данных система покажет сообщение об ошибке – это будет рассмотрено ниже.
// ---------------------------------------------------------------------
// 2. Обработчик "ПередЗаписью" в справочнике «Параметры расчёта»
// ---------------------------------------------------------------------
// Цель: автоматически проверять корректность даты начала действия – она не должна быть
//       больше текущей даты (иначе параметр будет «в будущем» и расчёт его не увидит).
// ---------------------------------------------------------------------
Процедура ПередЗаписью(Отказ, СтандартнаяОбработка)
{
    // Текущая дата без времени
    ТекущаяДата = ТекущаяДата();

    // Проверяем, что ДатаНачалаДействия заполнена
    Если НЕ ЗначениеЗаполнено(ДатаНачалаДействия) Тогда
        Предупреждение("Не заполнена дата начала действия.");
        Отказ = Истина;
        Возврат;
    КонецЕсли;

    // Если дата начала позже текущей даты – выводим предупреждение и запрещаем запись
    Если ДатаНачалаДействия > ТекущаяДата Тогда
        Предупреждение("Дата начала действия не может быть позже текущей даты " + Формат(ТекущаяДата, "ДФ=dd.MM.yyyy"));
        Отказ = Истина;
    КонецЕсли;

    // Дополнительные проверки (пример – код фонда обязателен)
    Если НЕ ЗначениеЗаполнено(КодФонда) Тогда
        Предупреждение("Не заполнен код фонда. Параметр будет недоступен при расчёте.");
        // Не делаем Отказ, а лишь информируем – пользователь может решить записать.
    КонецЕсли;
}
// ---------------------------------------------------------------------
// 3. Скрипт импорта ставок налога из внешнего Excel‑файла
// ---------------------------------------------------------------------
// Предполагается, что в Excel‑файле ("C:\Temp\СтавкиНалогов.xlsx") находится лист "Налоги"
// со следующей структурой:
//   A – Код налога (строка)
//   B – Наименование (строка)
//   C – Дата начала действия (дата)
//   D – Дата окончания действия (дата, может быть пустой)
//   E – Ставка (число, например 0.13)
// ---------------------------------------------------------------------
Процедура ИмпортСтавокНалогаИзExcel()
{
    // Путь к файлу – в реальном проекте лучше брать из параметров пользователя
    ПутьКФайлу = "C:\\Temp\\СтавкиНалогов.xlsx";

    // Открываем соединение с Excel через COM‑объект
    Excel = Новый COMОбъект("Excel.Application");
    Excel.Visible = Ложь; // скрыть окно Excel
    Книга = Excel.Workbooks.Open(ПутьКФайлу);
    Лист = Книга.Worksheets("Налоги");

    // Определяем последнюю заполненную строку в колонке A
    ПоследняяСтрока = Лист.Cells(Лист.Rows.Count, 1).End(-4162).Row; // -4162 = xlUp

    Для i = 2 По ПоследняяСтрока Цикл // пропускаем заголовок
    {
        КодНалога      = Стр(Лист.Cells(i, 1).Value);
        Наименование   = Стр(Лист.Cells(i, 2).Value);
        ДатаНачала     = Дата(Лист.Cells(i, 3).Value);
        ДатаОкончания  = Не Пусто(Лист.Cells(i, 4).Value) ? Дата(Лист.Cells(i, 4).Value) : Неопределено;
        Ставка         = Число(Лист.Cells(i, 5).Value);

        // Ищем существующую запись в справочнике "Ставки налога"
        СтавкаНалога = Справочники.СтавкиНалога.НайтиПоКоду(КодНалога);
        Если СтавкаНалога = Неопределено Тогда
            СтавкаНалога = Справочники.СтавкиНалога.СоздатьЭлемент();
            СтавкаНалога.Код = КодНалога;
        КонецЕсли;

        // Заполняем реквизиты
        СтавкаНалога.Наименование          = Наименование;
        СтавкаНалога.ДатаНачалаДействия   = ДатаНачала;
        СтавкаНалога.ДатаОкончанияДействия= ДатаОкончания;
        СтавкаНалога.Ставка               = Ставка;

        // Сохраняем запись
        СтавкаНалога.Записать();
    }

    // Закрываем Excel без сохранения
    Книга.Close(Ложь);
    Excel.Quit();
    ОсвободитьОбъект(Excel);

    Сообщить("Импорт ставок налога завершён. Обработано строк: " + (ПоследняяСтрока-1));
}
// ---------------------------------------------------------------------
// 4. Как проверить, что параметры применились в расчёте
// ---------------------------------------------------------------------
// 4.1 Открыть «Отчёты» → «Зарплата и управление персоналом» → «Регистры сведений» → «Расчёт начислений».
// 4.2 В открывшемся окне выбрать кнопку «Настроить» → «Фильтр».
// 4.3 Установить фильтр по полю «Дата» (например, текущий расчётный период) и нажать «ОК».
// 4.4 В табличной части результата найти интересующие записи (по сотруднику, типу начисления).
// 4.5 Проверить значения полей:
//      • Ставка – должна совпадать с тем, что задано в справочнике «Параметры расчёта»
//      • Сумма – рассчитана автоматически согласно формуле расчёта и выбранному правилу округления.
// 4.6 При необходимости открыть форму «Документ.РасчётЗарплаты», выбрать нужный расчётный период и нажать «Провести», после чего снова проверить регистр.
// ---------------------------------------------------------------------
// 5. Список типовых ошибок и рекомендации по их исправлению
// ---------------------------------------------------------------------
/*
  1. Ошибка: Не заполнен код фонда (реквизит «КодФонда») в параметре расчёта.
     Последствия: При расчёте начислений система не может сформировать отчисления в фонд, запись будет пропущена.
     Рекомендация: В справочнике «Параметры расчёта» обязательно указывайте код фонда. При импорте из Excel добавьте проверку наличия этого поля.

  2. Ошибка: Дата начала действия позже текущей даты.
     Последствия: Параметр считается «в будущем» и не участвует в текущих расчётах.
     Рекомендация: Использовать обработчик ПередЗаписью (см. пункт 2) – система будет блокировать запись.

  3. Ошибка: Дата окончания действия меньше даты начала.
     Последствия: Параметр считается недействительным, расчёт может использовать старую ставку.
     Рекомендация: Добавить проверку в обработчик ПередЗаписью:
                Если ДатаОкончания <> Неопределено И ДатаОкончания < ДатаНачала Тогда
                    Предупреждение("Дата окончания не может быть меньше даты начала.");
                    Отказ = Истина;
                КонецЕсли;

  4. Ошибка: Неправильный формат ставки (например, запятая вместо точки).
     Последствия: При расчёте ставка будет интерпретирована как строка и вызовет ошибку выполнения.
     Рекомендация: При вводе вручную использовать формат «0,13» (в русской локали) или «0.13» в коде. При импорте из Excel явно преобразовывать значение к типу Число.

  5. Ошибка: Отсутствует правило округления (реквизит «ПравилоОкругления»).
     Последствия: Система использует глобальное правило, которое может не соответствовать требованиям организации.
     Рекомендация: В справочнике «Параметры расчёта» укажите нужное правило (например, «Округление до копеек»).

  6. Ошибка: Дублирование кода параметра (один и тот же код уже существует).
     Последствия: При попытке записи будет ошибка уникальности.
     Рекомендация: При импорте проверять наличие записи по коду (см. пример в пункте 3) и обновлять её, а не создавать новую.
*/
// ---------------------------------------------------------------------
// Конец практического сценария
// ---------------------------------------------------------------------

content_blocks.md_content:
В современном бизнесе — чем быстрее и точнее — все расчёты с персоналом, тем выше доверие сотрудников и эффективность компании. Оформление кадровых форм «Приём на работу», «Перевод» и «Увольнение» — это не просто бюрократия: каждый из этих документов формирует базу, из которой 1С : Зарплата и управление персоналом генерирует начисления, удержания и налоговые отчёты. Если сведения о дате начала работы, должности, ставке или дате увольнения будут неполными или ошибочными, расчёт заработной платы сразу «съест» время и деньги, а возможные проверки налоговых органов превратятся в головную боль. Все эти формы напрямую связаны со справочником «Сотрудники», где хранятся личные данные, графики и история перемещений; любой их несоответствия сразу отражаются в регистрах расчётов. Табель учёта рабочего времени дополняет эту картину, фиксируя фактические часы, сверхурочные и ночные смены, позволяя получать точные выплаты и контролировать соблюдение трудового законодательства.

**К концу урока вы сможете:**
- уверенно заполнять формы приёма, перевода и увольнения в соответствии с внутренними регламентами; 
- связывать кадровые документы со справочником «Сотрудники» и проверять их корректность; 
- формировать и проверять табель учёта рабочего времени, учитывая все виды дополнительных часов; 
- понимать, как эти данные влияют на расчёт заработной платы и налоговые обязательства компании.

content_blocks.code:
// ------------------------------------------------------------
// Пример автоматического создания и проведения документа
// "Табель учета рабочего времени" через скрипт 1С:Предприятие 8.3.
// ------------------------------------------------------------

&НаКлиенте // код будет выполнен на клиенте (в обработке)
Процедура ВыполнитьСозданиеТабеля()
    // 1. Получаем ссылку на справочник "Сотрудники"
    СправочникСотрудники = Справочники.Сотрудники;

    // 2. Ищем сотрудника по ФИО. Если не найден – создаём нового.
    ФИОСотрудника = "Иванов Иван Иванович";
    Сотрудник = СправочникСотрудники.НайтиПоНаименованию(ФИОСотрудника);
    Если Сотрудник = Неопределено Тогда
        Сотрудник = Справочники.Сотрудники.СоздатьЭлемент();
        Сотрудник.Наименование = ФИОСотрудника;
        // При необходимости заполняем другие реквизиты справочника
        Сотрудник.Записать();
    КонецЕсли;

    // 3. Создаём новый документ "Табель учета рабочего времени"
    Табель = Документы.ТабельУчетаРабочегоВремени.СоздатьДокумент();

    // 4. Заполняем реквизиты документа (заголовок)
    Табель.Дата = ТекущаяДата(); // дата документа – текущий день

    // 5. Заполняем табличную часть "ТабельныйДокумент"
    //    (в каждой строке указываем сотрудника, дату и количество часов)
    НоваяСтрока = Табель.ТабельныйДокумент.Добавить();
    НоваяСтрока.Сотрудник = Сотрудник;               // ссылка на справочник Сотрудники
    НоваяСтрока.Дата = ТекущаяДата();                // дата строки
    НоваяСтрока.ЧасыОбычные = 160;                   // обычные часы за месяц
    НоваяСтрока.ЧасыНочные = 20;                     // ночные часы
    НоваяСтрока.ЧасыСверхурочные = 10;               // сверхурочные часы

    // 6. Открываем форму документа – пользователь может увидеть заполненные данные
    ФормаТабеля = Табель.ПолучитьФорму();
    ФормаТабеля.Открыть(); // открытие в режиме просмотра/редактирования

    // 7. Сохраняем документ в базе данных
    Табель.Записать();

    // 8. Проводим документ – запускаются расчёты начислений и запись в регистры
    Табель.Провести();

    // 9. Информируем пользователя о результате
    Сообщить("Табель учета рабочего времени успешно создан и проведён.");
КонецПроцедуры

// ------------------------------------------------------------
// Чтобы запустить пример, достаточно вызвать процедуру
// ВыполнитьСозданиеТабеля() из любой обработки или формы.
// ------------------------------------------------------------

