/*===================================================================
   Блок 4 – Выполнение расчёта заработной платы и проверка результатов
   -------------------------------------------------------------------
   1) Запуск расчёта за выбранный месяц;
   2) Формирование табличного документа с полями:
        ФИО, Должность, Оклад, Начислено, Удержано, Итого к выплате;
   3) Проверка данных в регистрах «Расчётные данные», «Начисления», «Удержания».
   ===================================================================*/

//===================================================================
// 1. Текст запроса (язык запросов 1С)
//===================================================================
ЗапросТекст =
"ВЫБРАТЬ
    Сотрудники.ФИО               КАК ФИО,
    Должности.Наименование       КАК Должность,
    Ставки.Размер                КАК Оклад,
    СУММА(Начисления.Сумма)      КАК Начислено,
    СУММА(Удержания.Сумма)       КАК Удержано,
    (СУММА(Начисления.Сумма) - СУММА(Удержания.Сумма)) КАК ИтогоКВыплате
ИЗ
    Справочник.Сотрудники КАК Сотрудники
        // Должность сотрудника
        ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Должности КАК Должности
            ПО Сотрудники.Должность = Должности.Ссылка
        // Ставка (оклад) по должности на начало расчётного периода
        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СтавкиКДолжностям КАК Ставки
            ПО Должности.Ссылка = Ставки.Должность
            И Ставки.Период = &ДатаНачала
        // Начисления за выбранный период
        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.Начисления КАК Начисления
            ПО Сотрудники.Ссылка = Начисления.Сотрудник
            И Начисления.Период МЕЖДУ &ДатаНачала И &ДатаОкончания
        // Удержания за выбранный период
        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.Удержания КАК Удержания
            ПО Сотрудники.Ссылка = Удержания.Сотрудник
            И Удержания.Период МЕЖДУ &ДатаНачала И &ДатаОкончания
ГДЕ
    Сотрудники.ЭтоГруппа = ЛОЖЬ
СГРУППИРОВАТЬ ПО
    Сотрудники.ФИО,
    Должности.Наименование,
    Ставки.Размер";

//===================================================================
// 2. Обработчик (процедура), которую можно разместить в любой обработке
//    (например, в обработке «Расчёт и отчёт по зарплате»)
//===================================================================
&AtClient
Процедура ВыполнитьРасчётИОтчёт()
    // ---------------------------------------------------------------
    // 2.1 Параметры расчёта – их удобно вынести в форму ввода.
    // ---------------------------------------------------------------
    // Дата начала расчётного периода (пользователь меняет нужный месяц)
    ДатаНачала   = Новый Дата(2023, 5, 1); // <-- изменить на требуемый месяц
    // Дата окончания – автоматически берём конец того же месяца
    ДатаОкончания = КонецМесяца(ДатаНачала);

    // При необходимости можно ограничить список сотрудников, задав массив Сотрудник
    // СписокСотрудников = Новый Массив; // заполнить ссылками на нужных сотрудников

    // ---------------------------------------------------------------
    // 2.2 Запуск штатного расчёта заработной платы
    // ---------------------------------------------------------------
    // В конфигурации «1С:Зарплата и управление персоналом» расчёт делается
    // через регистратор «РегистраторРасчетаЗарплаты».
    Регистратор = РегистраторРасчетаЗарплаты.Создать();
    Регистратор.ДатаНачала   = ДатаНачала;
    Регистратор.ДатаОкончания = ДатаОкончания;
    // Если нужен отбор по сотрудникам – раскомментировать строку ниже
    // Регистратор.Сотрудники = СписокСотрудников;
    Регистратор.Записать(); // <-- здесь происходит расчёт

    // ---------------------------------------------------------------
    // 2.3 Формирование запроса к регистрам
    // ---------------------------------------------------------------
    Запрос = Новый Запрос;
    Запрос.Текст = ЗапросТекст;
    Запрос.УстановитьПараметр("ДатаНачала",   ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    // Если используется отбор по сотрудникам, добавляем параметр СписокСотрудников
    // Запрос.УстановитьПараметр("СписокСотрудников", СписокСотрудников);

    Результат = Запрос.Выполнить();
    Выборка  = Результат.Выбрать();

    // ---------------------------------------------------------------
    // 2.4 Заполнение табличного документа
    // ---------------------------------------------------------------
    ТабДок = Новый ТабличныйДокумент;
    // Шапка таблицы
    ТабДок.Колонки.Добавить("ФИО",               30);
    ТабДок.Колонки.Добавить("Должность",         20);
    ТабДок.Колонки.Добавить("Оклад",             12);
    ТабДок.Колонки.Добавить("Начислено",         12);
    ТабДок.Колонки.Добавить("Удержано",          12);
    ТабДок.Колонки.Добавить("Итого к выплате",   12);

    // Заполняем строки
    Пока Выборка.Следующий() Цикл
        НомерСтроки = ТабДок.Строки.Количество() + 1;
        ТабДок.Ячейка(НомерСтроки, 1).Значение = Выборка.ФИО;
        ТабДок.Ячейка(НомерСтроки, 2).Значение = Выборка.Должность;
        ТабДок.Ячейка(НомерСтроки, 3).Значение = Выборка.Оклад;
        ТабДок.Ячейка(НомерСтроки, 4).Значение = Выборка.Начислено;
        ТабДок.Ячейка(НомерСтроки, 5).Значение = Выборка.Удержано;
        ТабДок.Ячейка(НомерСтроки, 6).Значение = Выборка.ИтогоКВыплате;
    КонецЦикла;

    // Форматируем числовые колонки как денежные (2 знака после запятой)
    Для i = 3 По 6 Цикл
        ТабДок.Колонки[i].Тип    = ТипКолонкиЧисло;
        ТабДок.Колонки[i].Формат = "ЧГ=2"; // 2 знака после запятой, разделитель – пробел
    КонецЦикла;

    // ---------------------------------------------------------------
    // 2.5 Сохранение в Excel
    // ---------------------------------------------------------------
    ПутьКФайлу = "C:\Temp\Отчёт_Зарплата_" + Формат(ДатаНачала, "ГГГГММ") + ".xlsx";
    ТабДок.Экспорт(ПутьКФайлу);
    Сообщить("Отчёт сформирован и сохранён: " + ПутьКФайлу);

    // ---------------------------------------------------------------
    // 2.6 (Опционально) Проверка содержимого регистров
    // ---------------------------------------------------------------
    // Пример простого вывода количества записей в каждом регистре за период
    Сообщить("--- Проверка регистров за " + Формат(ДатаНачала, "ММ.yyyy") + " ---");
    // Расчётные данные
    ЗапросПроверка = Новый Запрос;
    ЗапросПроверка.Текст =
    "ВЫБРАТЬ
        COUNT(*) КАК Количество
    ИЗ
        РегистрСведений.РасчетныеДанные
    ГДЕ
        Период МЕЖДУ &ДатаНачала И &ДатаОкончания";
    ЗапросПроверка.УстановитьПараметр("ДатаНачала",   ДатаНачала);
    ЗапросПроверка.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    КолЗаписей = ЗапросПроверка.Выполнить().Выбрать().ПолучитьКолонку("Количество")[0];
    Сообщить("Записей в регистре \"Расчётные данные\": " + КолЗаписей);
    // Аналогично можно проверить «Начисления» и «Удержания»
КонецПроцедуры

/*===================================================================
   Как менять параметры
   -------------------
   • ДатаНачала – задайте нужный месяц (например, Новый Дата(2023, 6, 1)).
   • При необходимости ограничьте список сотрудников: создайте массив
     ссылок на нужных сотрудников и присвойте его свойству Регистратор.Сотрудники.
   • Путь к файлу Excel (переменная ПутьКФайлу) можно изменить на любой
     доступный каталог.
===================================================================*/

content_blocks.explanation:
В примере показано, как из клиентского кода 1С:
1) запустить штатный расчёт заработной платы за выбранный месяц;
2) собрать нужные данные из регистров с помощью запроса;
3) вывести их в табличный документ и сохранить в Excel;
4) выполнить простую проверку количества записей в регистрах.
Все ключевые места, где пользователь может изменить параметры, отмечены комментариями.

assignment.description:
**Цель** – продемонстрировать умение построить корректную «скелетную» структуру конфигурации, настроить параметры расчёта и выполнить полный расчётный цикл, используя ваш собственный проект (конфигурацию 1С, в которой вы разрабатываете учёт персонала).

**Контекст** – вы уже работаете над проектом компании/организации. В рамках этого задания необходимо применить изученный материал к вашему конфигурационному решению.

**Обязательные шаги**:
1. **Заполнение справочников** – создайте (или проверьте) записи в справочниках: «Подразделения», «Должности», «Тарифы», «Надбавки», «Сотрудники». Для каждого справочника приложите скриншот списка или экспорт в табличный вид (CSV/Excel). Обязательно укажите обязательные реквизиты, перечисленные в теории (Код, Наименование, Тариф, Коэффициент, Дата начала и т.д.).
2. **Настройка параметров расчёта** – в справочнике «Налоги и взносы» создайте все удержания, которые будут использоваться. В регистраторе «Параметры расчёта» создайте запись для выбранного расчётного месяца (укажите ставки, базы, коэффициенты, способ расчёта и правила округления). Приложите скриншот формы параметров.
3. **Запуск расчёта** – используя стандартный обработчик «Расчёт заработной платы» (или код из блока 4), выполните расчёт за выбранный месяц. Сохраните лог выполнения (скриншот окна сообщений) и укажите дату/период расчёта.
4. **Формирование отчёта** – экспортируйте табличный документ с колонками: ФИО, Должность, Оклад, Начислено, Удержано, Итого к выплате. Сохраните файл Excel и включите его в отчёт (можно как вложение или ссылка).
5. **Проверка регистров** – откройте регистры накопления «Начисления», «Удержания», «Расчётные данные». Укажите количество записей за период и сравните суммарные значения с итогами из Excel‑отчёта. Приложите скриншоты запросов/результатов.
6. **Документирование** – подготовьте один файл отчёта (Markdown, PDF, DOCX или XLSX), содержащий следующие разделы:
   - Введение (краткое описание проекта и выбранного расчётного периода);
   - Справочники (таблицы/скриншоты);
   - Параметры расчёта (скриншот/таблица);
   - Ход расчёта (лог, код, путь к обработке);
   - Итоги расчёта (Excel‑таблица);
   - Проверка регистров (результаты запросов);
   - Выводы (соответствие ожидаемому результату, замеченные проблемы).

**Формат сдачи** – один файл с расширением .md, .pdf, .docx или .xlsx, размер не более 5 МБ. Файл должен называться `Payroll_Cycle_Report.<ext>`.

