content_blocks.code:
// ------------------------------------------------------------
// Блок 4. Пример SQL‑подобного запроса для вывода регистров
// "Зарплата", "Начисления" и "Удержания" в табличный документ
// ------------------------------------------------------------

// 1. Подготовка параметров расчёта (период и организация)
ДатаНачала   = НачалоМесяца(ТекущаяДата()); // текущий месяц
ДатаОкончания = КонецМесяца(ДатаНачала);
Организация   = Справочники.Организации.Получить(\"Главное предприятие\");

// 2. Текст запроса (SQL‑подобный язык 1С). Мы объединяем три регистра
//    в один результат, чтобы в табличном документе видеть
//    начисления, удержания и итоговую сумму по каждому сотруднику.
ЗапросТекст =
    "ВЫБРАТЬ
" +
    "    Сотрудники.ФизическоеЛицо КАК Сотрудник,
" +
    "    Сотрудники.Наименование КАК ФИО,
" +
    "    Начисления.Дата КАК ДатаНачисления,
" +
    "    Начисления.ВидНачисления КАК ВидНачисления,
" +
    "    Начисления.Сумма КАК СуммаНачисления,
" +
    "    Удержания.Дата КАК ДатаУдержания,
" +
    "    Удержания.ВидУдержания КАК ВидУдержания,
" +
    "    Удержания.Сумма КАК СуммаУдержания,
" +
    "    (Начисления.Сумма - Удержания.Сумма) КАК Итого
" +
    "ИЗ
" +
    "    РегистрНакопления.Зарплата КАК Зарплата
" +
    "        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.Начисления КАК Начисления
" +
    "            ПО (Зарплата.Сотрудник = Начисления.Сотрудник
" +
    "                И Начисления.Период МЕЖДУ &ДатаНачала И &ДатаОкончания)
" +
    "        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.Удержания КАК Удержания
" +
    "            ПО (Зарплата.Сотрудник = Удержания.Сотрудник
" +
    "                И Удержания.Период МЕЖДУ &ДатаНачала И &ДатаОкончания)
" +
    "        ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Сотрудники КАК Сотрудники
" +
    "            ПО (Зарплата.Сотрудник = Сотрудники.Ссылка)
" +
    "ГДЕ
" +
    "    Зарплата.Период МЕЖДУ &ДатаНачала И &ДатаОкончания
" +
    "    И Зарплата.Организация = &Организация
" +
    "УПОРЯДОЧИТЬ ПО Сотрудник, ДатаНачисления, ДатаУдержания";

// 3. Создаём объект запроса и передаём параметры
Запрос = Новый Запрос;
Запрос.Текст = ЗапросТекст;
Запрос.УстановитьПараметр("ДатаНачала",   ДатаНачала);
Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
Запрос.УстановитьПараметр("Организация",   Организация);

// 4. Выполняем запрос и получаем результат в виде ТаблицыЗначений
Результат = Запрос.Выполнить();
Таблица = Результат.Выгрузить();

// 5. Формируем табличный документ
ТабДок = Новый ТабличныйДокумент;
ТабДок.ШиринаКолонки(1) = 30; // Сотрудник (Код)
ТабДок.ШиринаКолонки(2) = 30; // ФИО
ТабДок.ШиринаКолонки(3) = 15; // Дата начисления
ТабДок.ШиринаКолонки(4) = 30; // Вид начисления
ТабДок.ШиринаКолонки(5) = 15; // Сумма начисления
ТабДок.ШиринаКолонки(6) = 15; // Дата удержания
ТабДок.ШиринаКолонки(7) = 30; // Вид удержания
ТабДок.ШиринаКолонки(8) = 15; // Сумма удержания
ТабДок.ШиринаКолонки(9) = 15; // Итого

// 6. Заполняем шапку таблицы
Заголовки = Новый Массив;
Заголовки.Добавить("Код сотрудника");
Заголовки.Добавить("ФИО");
Заголовки.Добавить("Дата начисления");
Заголовки.Добавить("Вид начисления");
Заголовки.Добавить("Сумма начисления");
Заголовки.Добавить("Дата удержания");
Заголовки.Добавить("Вид удержания");
Заголовки.Добавить("Сумма удержания");
Заголовки.Добавить("Итого");
ТабДок.ЗаписатьСтроку(Заголовки, Истина); // Истина – жирный шрифт

// 7. Заполняем данными
Для Каждого Строка Из Таблица Цикл
    МассивСтрока = Новый Массив;
    МассивСтрока.Добавить(Строка.Сотрудник);
    МассивСтрока.Добавить(Строка.ФИО);
    МассивСтрока.Добавить(Строка.ДатаНачисления);
    МассивСтрока.Добавить(Строка.ВидНачисления);
    МассивСтрока.Добавить(Строка.СуммаНачисления);
    МассивСтрока.Добавить(Строка.ДатаУдержания);
    МассивСтрока.Добавить(Строка.ВидУдержания);
    МассивСтрока.Добавить(Строка.СуммаУдержания);
    МассивСтрока.Добавить(Строка.Итого);
    ТабДок.ЗаписатьСтроку(МассивСтрока);
КонецЦикла;

// 8. Сохраняем документ (можно открыть сразу в Excel/Word)
ПутьКФайлу = "C:\Temp\Отчет_Зарплата_" + Формат(ДатаНачала, "ГГГГММ") + ".xlsx";
ТабДок.Экспортировать(ПутьКФайлу, "Excel");
Сообщить("Отчёт сформирован: " + ПутьКФайлу);

// ------------------------------------------------------------
// Что делает код:
// 1) Формирует запрос к регистрам «Зарплата», «Начисления», «Удержания»
//    с учётом выбранного периода и организации.
// 2) Выгружает результат в ТаблицуЗначений.
// 3) Создаёт объект ТабличныйДокумент, задаёт ширину колонок и
//    заполняет его шапкой и данными.
// 4) Экспортирует полученный документ в Excel (можно поменять
//    на PDF, Word и т.п.).
// ------------------------------------------------------------

// ------------------------------------------------------------
// Пошаговый сценарий оформления отпуска и больничного листа
// для сотрудника «Иванов И.И.» в 1С:Зарплата и управление персоналом 3.1
// ------------------------------------------------------------

// ──────────────────────────────────────────────────────────────
// Шаг 1. Открыть справочник «Сотрудники» и выбрать (или создать) запись
// «Иванов И.И.».
// -------------------------------------------------------------
// Открываем форму справочника через глобальный контекст.
Справочники.Сотрудники.Выбрать(); // открывает список всех сотрудников
// Если сотрудника нет – создаём новую запись.
Если Не Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И.") Тогда
    НовыйСотрудник = Справочники.Сотрудники.СоздатьЭлемент();
    НовыйСотрудник.ФИО = "Иванов И.И.";
    // Заполняем обязательные реквизиты (должность, подразделение, тариф и т.д.)
    НовыйСотрудник.Должность = Справочники.Должности.Получить("Программист");
    НовыйСотрудник.Подразделение = Справочники.Подразделения.Получить("Разработка");
    НовыйСотрудник.Тариф = 1500; // руб./час – пример
    НовыйСотрудник.Записать();
КонецЕсли;
// -------------------------------------------------------------
// Почему важно: без корректного справочника расчёт отпускных и больничных
// будет невозможен – все формулы берут данные из реквизитов сотрудника.

// ──────────────────────────────────────────────────────────────
// Шаг 2. Открыть форму документа «Отпуск».
// -------------------------------------------------------------
ДокОтпуск = Документы.Отпуск.СоздатьДокумент();
ДокОтпуск.Дата = ТекущаяДата(); // дата создания документа
ДокОтпуск.Организация = Справочники.Организации.Получить("ООО ""Ромашка""");
ДокОтпуск.Подразделение = Справочники.Подразделения.Получить("Разработка");
ДокОтпуск.Сотрудник = Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И.");
// -------------------------------------------------------------
// Почему важно: документ «Отпуск» – основной объект, в котором указываются
// даты и количество дней, а система автоматически рассчитывает сумму.

// ──────────────────────────────────────────────────────────────
// Шаг 3. Заполнить реквизиты «Дата начала», «Дата окончания», «Количество дней».
// -------------------------------------------------------------
ДокОтпуск.ДатаНачала = Дата(2026, 7, 1);   // 01.07.2026
ДокОтпуск.ДатаОкончания = Дата(2026, 7, 10); // 10.07.2026
ДокОтпуск.КоличествоДней = 10; // 10 календарных дней
// -------------------------------------------------------------
// Система сразу рассчитывает «Сумма выплаты» в поле «Сумма».

// ──────────────────────────────────────────────────────────────
// Шаг 4. Проверить автоматически рассчитанную сумму.
// -------------------------------------------------------------
Сообщить("Сумма отпускных: " + Формат(ДокОтпуск.Сумма, "ЧГ=0"));
// При необходимости – открыть форму документа и увидеть поле «Сумма».
// -------------------------------------------------------------
// Почему важно: контроль расчёта позволяет убедиться, что коэффициенты
// (например, 1 % от средней зарплаты) применены правильно.

// ──────────────────────────────────────────────────────────────
// Шаг 5. Провести документ «Отпуск».
// -------------------------------------------------------------
ДокОтпуск.Провести();
Сообщить("Документ отпуск проведён.");
// -------------------------------------------------------------
// После проведения запись появляется в регистре «Отпускные выплаты».

// ──────────────────────────────────────────────────────────────
// Шаг 6. Открыть форму документа «Больничный лист».
// -------------------------------------------------------------
ДокБольничный = Документы.БольничныйЛист.СоздатьДокумент();
ДокБольничный.Дата = ТекущаяДата();
ДокБольничный.Организация = Справочники.Организации.Получить("ООО ""Ромашка""");
ДокБольничный.Подразделение = Справочники.Подразделения.Получить("Разработка");
ДокБольничный.Сотрудник = Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И.");
// -------------------------------------------------------------
// Почему важно: отдельный документ нужен для расчёта больничных выплат
// (по проценту от средней зарплаты, с учётом коэффициентов).

// ──────────────────────────────────────────────────────────────
// Шаг 7. Заполнить даты и количество дней больничного листа.
// -------------------------------------------------------------
ДокБольничный.ДатаНачала = Дата(2026, 8, 15);   // 15.08.2026
ДокБольничный.ДатаОкончания = Дата(2026, 8, 19); // 19.08.2026
ДокБольничный.КоличествоДней = 5; // 5 календарных дней
// -------------------------------------------------------------
// Система рассчитывает «Сумма выплаты» в зависимости от
// установленного процента (например, 80 % от средней ЗП).

// ──────────────────────────────────────────────────────────────
// Шаг 8. Проверить рассчитанную сумму больничных.
// -------------------------------------------------------------
Сообщить("Сумма больничных: " + Формат(ДокБольничный.Сумма, "ЧГ=0"));
// При необходимости – открыть форму и увидеть поле «Сумма».
// -------------------------------------------------------------
// Контроль важен, потому что в 1С могут применяться разные коэффициенты
// (по возрасту, категории и т.д.).

// ──────────────────────────────────────────────────────────────
// Шаг 9. Провести документ «Больничный лист».
// -------------------------------------------------------------
ДокБольничный.Провести();
Сообщить("Документ больничный лист проведён.");
// -------------------------------------------------------------
// После проведения запись появляется в том же регистре «Отпускные выплаты».

// ──────────────────────────────────────────────────────────────
// Шаг 10. Выполнить расчёт заработной платы за период, включающий отпуск и больничный.
// -------------------------------------------------------------
Расчет = РегистрыНакопления.ЗарплатаВыплаты.ПолучитьОбъект();
// Параметры расчёта (например, квартал 3‑й 2026 г.)
Расчет.ДатаНачала = Дата(2026, 7, 1);
Расчет.ДатаОкончания = Дата(2026, 9, 30);
Расчет.Организация = Справочники.Организации.Получить("ООО ""Ромашка""");
Расчет.Записать();
// Запускаем обработку «Выполнить расчёт»
Обработки.РасчётЗарплаты.Запустить();
Сообщить("Расчёт заработной платы выполнен.");
// -------------------------------------------------------------
// Важно, чтобы расчёт был выполнен после проведения документов –
// иначе суммы не попадут в итоговый расчёт.

// ──────────────────────────────────────────────────────────────
// Шаг 11. Открыть регистр «Отпускные выплаты» и отфильтровать записи по сотруднику.
// -------------------------------------------------------------
РегистрОтпускные = РегистрыНакопления.ОтпускныеВыплаты.СоздатьВыборку();
РегистрОтпускные.УстановитьОтбор("Сотрудник", Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И."));
Пока РегистрОтпускные.Следующий() Цикл
    Сообщить("Дата: " + Формат(РегистрОтпускные.Дата, "ДФ=dd.MM.yyyy") +
            ", Сумма: " + Формат(РегистрОтпускные.Сумма, "ЧГ=0"));
КонецЦикла;
// -------------------------------------------------------------
// Фильтрация позволяет увидеть, какие суммы уже начислены (отпускные и больничные).

// ──────────────────────────────────────────────────────────────
// Шаг 12. Открыть форму «Платёжный лист» (расчётный лист) и убедиться в итоговых суммах.
// -------------------------------------------------------------
ПлатёжныйЛист = Документы.ПлатёжныйЛист.СоздатьДокумент();
ПлатёжныйЛист.Дата = ТекущаяДата();
ПлатёжныйЛист.Организация = Справочники.Организации.Получить("ООО ""Ромашка""");
ПлатёжныйЛист.Подразделение = Справочники.Подразделения.Получить("Разработка");
ПлатёжныйЛист.Сотрудник = Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И.");
// Добавляем начисления, полученные из расчёта
ПлатёжныйЛист.ДобавитьНачисление("Отпускные выплаты", ДокОтпуск.Сумма);
ПлатёжныйЛист.ДобавитьНачисление("Больничные выплаты", ДокБольничный.Сумма);
ПлатёжныйЛист.Записать();
ПлатёжныйЛист.Провести();
// Открываем форму для просмотра
ПлатёжныйЛист.Открыть();
// -------------------------------------------------------------
// В форме видим итоговую сумму к выплате, а также детали начислений.
// Это финальная проверка – если суммы совпадают с тем, что было в регистре,
// значит процесс оформлен корректно.

// ──────────────────────────────────────────────────────────────
// Шаг 13 (опционально). Сформировать отчёт «Отпускные и больничные выплаты».
// -------------------------------------------------------------
Отчёт = Отчеты.ОтпускныеИБольничныеВыплаты.СоздатьОтчет();
Отчёт.УстановитьПараметр("ДатаНачала", Дата(2026, 7, 1));
Отчёт.УстановитьПараметр("ДатаОкончания", Дата(2026, 9, 30));
Отчёт.УстановитьПараметр("Сотрудник", Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И."));
Отчёт.Сформировать();
Отчёт.Показать();
// -------------------------------------------------------------
// Отчёт позволяет быстро проверить, что все выплаты учтены и правильно
// распределены по периодам.

// ------------------------------------------------------------
// Конец сценария.
// ------------------------------------------------------------

assignment.description:
В рамках вашего собственного проекта (приложения, сервиса или библиотеки, разрабатываемого в другом предмете) подготовьте отчёт в формате Markdown, PDF или DOCX, демонстрирующий, как вы внедрили в конфигурацию 1С:ЗУП 3.1 процесс оформления отпусков и больничных листов и расчёт соответствующих выплат.

**Что необходимо выполнить**
1. Описать структуру и обязательные реквизиты документов «Отпуск» и «Больничный лист», указав, какие поля заполняются вручную, а какие – автоматически (например, даты, количество дней, сумма выплаты).
2. Привести рабочие фрагменты кода 1С (или настройки), реализующие расчёт средней заработной платы, применение коэффициентов (100 % для отпусков, 60 %/80 % для больничных) и запись результатов в регистр «Отпускные выплаты».
3. Включить две UML‑диаграммы (PlantUML или изображения): диаграмму компонентов, показывающую связь справочников, документов и регистра, и диаграмму последовательности, иллюстрирующую процесс расчёта и проведения документа.
4. Описать проверку записей в регистре «Отпускные выплаты»: пример запроса 1С (Запрос) или SQL‑запрос, отбор по сотруднику, периоду и виду выплаты, сравнение с ручными расчётами.
5. Сформировать квартальный отчёт «Отпускные и больничные выплаты» (скриншот или экспорт) за любой выбранный квартал и сопоставить полученные суммы с расчётами, выполненными вручную.
6. В конце отчёта разместить ссылки на ветки/коммиты вашего репозитория, где находятся реализованные объекты.

**Обязательные разделы отчёта (заголовки уровня 2, пронумерованы)**:
- Введение (кратко о проекте);
- Описание документов «Отпуск» и «Больничный лист»;
- Реализация расчётов (код, формулы);
- Диаграммы UML;
- Проверка регистра «Отпускные выплаты»;
- Квартальный отчёт и сравнение результатов;
- Выводы и рекомендации.

content_blocks.code:
//===================================================================
//  Обработка «Создание справочников для расчёта ЗП»
//  Конфигурация: 1С:Зарплата и управление персоналом 3.1
//  Описание: скрипт создаёт подразделение, должность, сотрудника,
//            вид рабочего времени, график работы и выводит сообщения
//===================================================================

&НаКлиенте
Процедура ПриОткрытии() Экспорт
    // Запускаем основную логику на сервере, чтобы иметь доступ к справочникам
    ВыполнитьНаСервере(СоздатьОбъекты);
КонецПроцедуры

//===================================================================
//  Основная процедура – выполняется на сервере
//===================================================================
&НаСервере
Процедура СоздатьОбъекты() Экспорт
    // ---------- 1. Подразделение ----------
    Подразделение = Справочники.Подразделения.СоздатьЭлемент();
    Подразделение.Наименование = "Отдел аналитики";
    // При необходимости задаём код, родитель и др. реквизиты
    Подразделение.Записать();
    Message("Подразделение 'Отдел аналитики' успешно создано.");

    // ---------- 2. Должность, привязанная к подразделению ----------
    Должность = Справочники.Должности.СоздатьЭлемент();
    Должность.Наименование = "Аналитик";
    // Связываем должность с подразделением (реквизит "Подразделение")
    Должность.Подразделение = Подразделение.Ссылка;
    Должность.Записать();
    Message("Должность 'Аналитик' успешно создана и привязана к подразделению.");

    // ---------- 3. Вид рабочего времени (если ещё не существует) ----------
    // В конфигурации «Зарплата и управление персоналом» обычно уже есть вид "Полный рабочий день".
    // Попробуем найти его, а если не найдём – создадим.
    ВидРабВремени = НайтиВидРабочегоВремени("Полный рабочий день");
    Если НЕ ВидРабВремени Тогда
        ВидРабВремени = Справочники.ВидыРабочегоВремени.СоздатьЭлемент();
        ВидРабВремени.Наименование = "Полный рабочий день";
        // Примерные параметры: 40 часов в неделю, 8 часов в день
        ВидРабВремени.КоличествоРабочихЧасовВНеделю = 40;
        ВидРабВремени.КоличествоРабочихЧасовВДень = 8;
        ВидРабВремени.Записать();
        Message("Вид рабочего времени 'Полный рабочий день' создан.");
    Иначе
        Message("Вид рабочего времени 'Полный рабочий день' уже существует.");
    КонецЕсли;

    // ---------- 4. График работы «5/2, 9‑00‑18‑00» ----------
    // Сначала проверяем, есть ли такой график
    График = НайтиГрафикРаботы("5/2, 9-00-18-00");
    Если НЕ График Тогда
        График = Справочники.ГрафикиРаботы.СоздатьЭлемент();
        График.Наименование = "5/2, 9-00-18-00";
        // Устанавливаем режим «5/2» (5 рабочих дней, 2 выходных)
        График.РежимРаботы = Новый Структура("Период,РабочиеДни", "5/2", "Пн,Вт,Ср,Чт,Пт");
        // Задаём рабочее время – с 9:00 до 18:00 (перерыв 1 час, если нужно, можно добавить)
        График.РабочееВремя = Новый Структура(
            "Начало,Конец,ПерерывНачало,ПерерывКонец",
            Время(9,0,0), Время(18,0,0), Неопределено, Неопределено);
        // Привязываем график к виду рабочего времени, который будет использовать сотрудник
        График.ВидРабочегоВремени = ВидРабВремени.Ссылка;
        График.Записать();
        Message("График работы '5/2, 9-00-18-00' успешно создан.");
    Иначе
        Message("График работы '5/2, 9-00-18-00' уже существует.");
    КонецЕсли;

    // ---------- 5. Сотрудник ----------
    Сотрудник = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник.Фамилия = "Иванов";
    Сотрудник.Имя = "Сергей";
    Сотрудник.Отчество = "Петрович";
    Сотрудник.ДатаРождения = Дата(1990,5,12);
    Сотрудник.Должность = Должность.Ссылка;
    Сотрудник.Подразделение = Подразделение.Ссылка;
    // Указываем вид рабочего времени и график, которые только что создали
    Сотрудник.ВидРабочегоВремени = ВидРабВремени.Ссылка;
    Сотрудник.ГрафикРаботы = График.Ссылка;
    Сотрудник.Записать();
    Message("Сотрудник 'Иванов Сергей Петрович' успешно создан и привязан к должности, подразделению, виду рабочего времени и графику.");

КонецПроцедуры

//===================================================================
//  Вспомогательные функции поиска (на сервере)
//===================================================================
&НаСервере
Функция НайтиВидРабочегоВремени(Наименование) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1
                    |   ВидыРабочегоВремени.Ссылка КАК Ссылка
                    |ИЗ
                    |   Справочник.ВидыРабочегоВремени КАК ВидыРабочегоВремени
                    |ГДЕ
                    |   ВидыРабочегоВремени.Наименование = &Наименование";
    Запрос.УстановитьПараметр("Наименование", Наименование);
    Результат = Запрос.Выполнить();
    Если Результат.Пустой() Тогда
        Возврат Неопределено;
    Иначе
        Возврат Результат.Выбрать().Ссылка;
    КонецЕсли;
КонецФункции

&НаСервере
Функция НайтиГрафикРаботы(Наименование) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1
                    |   ГрафикиРаботы.Ссылка КАК Ссылка
                    |ИЗ
                    |   Справочник.ГрафикиРаботы КАК ГрафикиРаботы
                    |ГДЕ
                    |   ГрафикиРаботы.Наименование = &Наименование";
    Запрос.УстановитьПараметр("Наименование", Наименование);
    Результат = Запрос.Выполнить();
    Если Результат.Пустой() Тогда
        Возврат Неопределено;
    Иначе
        Возврат Результат.Выбрать().Ссылка;
    КонецЕсли;
КонецФункции

//===================================================================
//  Конец скрипта
//===================================================================

//===================================================================
// Обработчик «Настройка параметров расчёта времени»
// Запускается из меню: "Настройки → Параметры расчёта времени"
//===================================================================

&НаКлиенте
Процедура НастроитьПараметрыРасчётаВремени(Команда)
    // ---------------------------------------------------------------
    // 1. Открываем форму обработки в режиме «Выполнить», чтобы пользователь
    //    мог видеть сообщения о прогрессе.
    // ---------------------------------------------------------------
    Сообщить("Начало настройки параметров расчёта времени...");

    // ---------------------------------------------------------------
    // 2. Получаем менеджер справочника "Параметры расчёта"
    // ---------------------------------------------------------------
    МенеджерПараметров = Справочники.ПараметрыРасчёта;

    // ---------------------------------------------------------------
    // 3. Функция‑обёртка, создающая/обновляющая запись.
    //    Принимает уникальный код записи, название и набор реквизитов.
    // ---------------------------------------------------------------
    Процедура ОбновитьИлиСоздать(Код, Наименование, Реквизиты)
    {
        // Ищем существующую запись по коду (поле "Код" – уникальный).
        Запрос = Новый Запрос;
        Запрос.Текст = 
            "ВЫБРАТЬ ПараметрыРасчёта.Ссылка КАК Ссылка " +
            "ИЗ Справочник.ПараметрыРасчёта КАК ПараметрыРасчёта " +
            "ГДЕ ПараметрыРасчёта.Код = &Код";
        Запрос.УстановитьПараметр("Код", Код);
        Результат = Запрос.Выполнить();
        Выборка = Результат.Выбрать();

        Если Выборка.Следующий() Тогда
            // Запись уже есть – просто обновляем нужные реквизиты.
            Параметр = Выборка.Ссылка;
        Иначе
            // Записи нет – создаём новую.
            Параметр = МенеджерПараметров.СоздатьЭлемент();
            Параметр.Код = Код;
            Параметр.Наименование = Наименование;
        КонецЕсли;

        // Заполняем реквизиты, переданные в виде структуры.
        Для Каждого ИмяРеквизита Из Реквизиты Ключи() Цикл
            Параметр[ИмяРеквизита] = Реквизиты[ИмяРеквизита];
        КонецЦикла;

        Параметр.Записать();
    }

    // ---------------------------------------------------------------
    // 4. Создаём/обновляем необходимые параметры.
    // ---------------------------------------------------------------
    // 4.1 Норма рабочего времени (неделя = 40 ч, день = 8 ч)
    //     Реквизиты: "ТипПараметра" = "НормаРабочегоВремени",
    //               "НормаВНеделю" = 40, "НормаВДень" = 8
    // ---------------------------------------------------------------
    ОбновитьИлиСоздать(
        "NORM_WORK_TIME",
        "Норма рабочего времени",
        Новый Структура(
            "ТипПараметра, НормаВНеделю, НормаВДень",
            "НормаРабочегоВремени", 40, 8
        )
    );

    // ---------------------------------------------------------------
    // 4.2 Коэффициент сверхурочных – 1,5 × нормы
    //     Реквизиты: "ТипПараметра" = "КоэффициентНадбавки",
    //               "ТипНадбавки" = "Сверхурочная",
    //               "Коэффициент" = 1.5
    // ---------------------------------------------------------------
    ОбновитьИлиСоздать(
        "COEF_OVERTIME",
        "Коэффициент сверхурочных",
        Новый Структура(
            "ТипПараметра, ТипНадбавки, Коэффициент",
            "КоэффициентНадбавки", "Сверхурочная", 1.5
        )
    );

    // ---------------------------------------------------------------
    // 4.3 Коэффициент ночных часов – 1,35 × нормы (ночь 22:00‑06:00)
    //     Реквизиты: "ТипПараметра" = "КоэффициентНадбавки",
    //               "ТипНадбавки" = "Ночная",
    //               "Коэффициент" = 1.35,
    //               "ВремяНачала" = "22:00:00",
    //               "ВремяОкончания" = "06:00:00"
    // ---------------------------------------------------------------
    ОбновитьИлиСоздать(
        "COEF_NIGHT",
        "Коэффициент ночных часов",
        Новый Структура(
            "ТипПараметра, ТипНадбавки, Коэффициент, ВремяНачала, ВремяОкончания",
            "КоэффициентНадбавки", "Ночная", 1.35, Время("22:00:00"), Время("06:00:00")
        )
    );

    // ---------------------------------------------------------------
    // 4.4 Коэффициент праздничных часов – 2,0 × нормы
    // ---------------------------------------------------------------
    ОбновитьИлиСоздать(
        "COEF_HOLIDAY",
        "Коэффициент праздничных часов",
        Новый Структура(
            "ТипПараметра, ТипНадбавки, Коэффициент",
            "КоэффициентНадбавки", "Праздничная", 2.0
        )
    );

    // ---------------------------------------------------------------
    // 4.5 Правило округления – до 0,5 ч в большую сторону
    //     Реквизиты: "ТипПараметра" = "Округление",
    //               "ШагОкругления" = 0.5,
    //               "ОкруглятьВБольшуюСторону" = Истина
    // ---------------------------------------------------------------
    ОбновитьИлиСоздать(
        "ROUNDING_HALF_UP",
        "Округление до 0,5 ч в большую сторону",
        Новый Структура(
            "ТипПараметра, ШагОкругления, ОкруглятьВБольшуюСторону",
            "Округление", 0.5, Истина
        )
    );

    // ---------------------------------------------------------------
    // 5. Сообщаем об окончании.
    // ---------------------------------------------------------------
    Сообщить("Параметры расчёта времени успешно созданы/обновлены.");
КонецПроцедуры

//===================================================================
// Обработка «ЗаполнениеДокументов»
//===================================================================
// Назначение: автоматическое заполнение реквизитов нового документа
//            "Приём" (Справочник.ПриёмыСотрудников) данными из справочника
//            "Сотрудники". При открытии формы создания документа пользователь
//            выбирает сотрудника, после чего реквизиты «Подразделение»,
//            «Должность» и «ГрафикРаботы» заполняются автоматически.
//            Обработка также демонстрирует, как документ «Приём» связан с
//            регистром учета рабочего времени (РегистрСведений.РабочееВремя).
//===================================================================

//===================================================================
// 1. Модуль обработки (Объект) – «ЗаполнениеДокументов»
//===================================================================

&AtClient
Процедура ПриОткрытии() Экспорт
    // Создаём форму обработки и открываем её в режиме выбора сотрудника.
    // Форма «ФормаВыбораСотрудника» – обычная форма списка справочника
    // "Сотрудники" (можно использовать стандартную форму списка).
    ФормаВыбора = Справочники.Сотрудники.Выбрать();
    ФормаВыбора.УстановитьРежимВыбора(Истина);
    // Ожидаем, пока пользователь выберет запись.
    Если ФормаВыбора.Выбрать() Тогда
        ВыбранныйСотрудник = ФормаВыбора.ПолучитьВыбранныйЭлемент();
        // Передаём выбранный объект в процедуру создания документа.
        СоздатьДокументПриёма(ВыбранныйСотрудник);
    Иначе
        Предупреждение("Сотрудник не выбран. Операция отменена.");
    КонецЕсли;
КонецПроцедуры

//===================================================================
// 2. Процедура создания и автозаполнения документа «Приём»
//===================================================================

&AtClient
Процедура СоздатьДокументПриёма(Сотрудник) Экспорт
    // Создаём новый документ «Приём»
    ПриёмДок = Документы.Приём.Создать();

    // Заполняем обязательный реквизит – Сотрудник
    ПриёмДок.Сотрудник = Сотрудник;

    // ---------------------------------------------------------------
    // Автозаполнение остальных реквизитов из справочника "Сотрудники"
    // ---------------------------------------------------------------
    // Подразделение
    Если Сотрудник.Подразделение <> Неопределено Тогда
        ПриёмДок.Подразделение = Сотрудник.Подразделение;
    КонецЕсли;

    // Должность
    Если Сотрудник.Должность <> Неопределено Тогда
        ПриёмДок.Должность = Сотрудник.Должность;
    КонецЕсли;

    // График работы (ссылка на регистр сведений "ГрафикиРаботы")
    Если Сотрудник.ГрафикРаботы <> Неопределено Тогда
        ПриёмДок.ГрафикРаботы = Сотрудник.ГрафикРаботы;
    КонецЕсли;

    // Открываем форму документа в режиме редактирования, чтобы пользователь
    // мог при необходимости изменить данные перед записью.
    ФормаДок = ПриёмДок.ПолучитьФорму();
    ФормаДок.Открыть();
КонецПроцедуры

//===================================================================
// 3. Обработчики событий документа «Приём»
//===================================================================
// Эти процедуры размещаются в модуле объекта документа "Приём".
// Они показывают, как документ автоматически отражается в регистре
// учета рабочего времени (РегистрСведений.РабочееВремя).

// ---------------------------------------------------------------
// Событие ПередЗаписью – вызывается перед тем, как документ будет
// записан в базу. Здесь можно выполнить проверку корректности данных.
// ---------------------------------------------------------------
&НаСервере
Процедура ПриёмПередЗаписью(Отказ, СтандартнаяОбработка)
    // Пример простой проверки: дата начала должна быть не позже даты окончания.
    Если Приём.ДатаНачала > Приём.ДатаОкончания Тогда
        Отказ = Истина;
        Сообщить("Дата начала не может быть позже даты окончания.");
        Возврат;
    КонецЕсли;
КонецПроцедуры

// ---------------------------------------------------------------
// Событие ПриЗаписи – вызывается после того, как документ записан.
// Здесь мы формируем запись в регистре сведений "РабочееВремя".
// ---------------------------------------------------------------
&НаСервере
Процедура ПриёмПриЗаписи(СтандартнаяОбработка)
    // Формируем запись в регистре сведений "РабочееВремя".
    // Предполагаем, что в регистре есть измерения: Сотрудник, Дата,
    // а ресурс – ЧасыРаботы (число).
    // График работы хранится в справочнике "ГрафикиРаботы" и содержит
    // количество рабочих часов в день (Реквизит "НормаЧасов").
    Если Приём.ГрафикРаботы <> Неопределено Тогда
        НормаЧасов = Приём.ГрафикРаботы.НормаЧасов;
    Иначе
        // Если график не указан, берём значение по умолчанию (8 часов).
        НормаЧасов = 8;
    КонецЕсли;

    // Записываем сведения за каждый день периода приёма.
    ДатаТек = Приём.ДатаНачала;
    Пока ДатаТек <= Приём.ДатаОкончания Цикл
        Запись = РегистрыСведений.РабочееВремя.Записать();
        Запись.Сотрудник = Приём.Сотрудник;
        Запись.Период = ДатаТек;
        Запись.ЧасыРаботы = НормаЧасов;
        Запись.Записать();
        ДатаТек = ДатаТек + 1; // переход к следующему дню
    КонецЦикла;
КонецПроцедуры

//===================================================================
// 4. Где разместить код
//===================================================================
// • Процедуры «ПриОткрытии», «СоздатьДокументПриёма» – в модуле обработки
//   "ЗаполнениеДокументов" (Объект → Обработка).
// • Обработчики «ПриёмПередЗаписью» и «ПриёмПриЗаписи» – в модуле объекта
//   документа "Приём" (Объект → Документ → Приём → Модуль).
// • Для того, чтобы обработка была доступна пользователям, её можно
//   добавить в меню «Справка → Автозаполнение кадровых документов»
//   через конфигуратор (Настройки → Меню → Добавить пункт).
//===================================================================

//===================================================================
// Краткое описание работы
//===================================================================
// 1. Пользователь запускает обработку «ЗаполнениеДокументов».
// 2. Открывается форма выбора сотрудника из справочника "Сотрудники".
// 3. После выбора сотрудника создаётся новый документ "Приём" и автоматически
//    заполняются реквизиты «Подразделение», «Должность», «ГрафикРаботы».
// 4. Пользователь при необходимости корректирует данные и сохраняет документ.
// 5. При сохранении вызываются события "ПередЗаписью" (проверка) и "ПриЗаписи"
//    (формирование записей в регистре "РабочееВремя").
// 6. После записи в регистр появляются строки, которые будут использованы
//    при расчёте табеля и начислении заработной платы.
//===================================================================

//===================================================================
// Процедура: ЗаполнитьТабельДляСотрудника
// Назначение: автоматически формирует строки табеля текущего месяца
//            для выбранного сотрудника, используя его график работы.
//===================================================================

Процедура ЗаполнитьТабельДляСотрудника(СсылкаНаСотрудника)
    // 1. Проверяем, что передан объект справочника "Сотрудники"
    Если Не СсылкаНаСотрудника = Неопределено И СсылкаНаСотрудника.ЭтоОбъект() Тогда
        // 2. Получаем текущий месяц и год
        ТекДата = ТекущаяДата();
        НачалоМесяца = НачалоМесяца(ТекДата);
        КонецМесяца = КонецМесяца(ТекДата);

        // 3. Открываем документ "Табель учёта рабочего времени"
        Табель = Документы.ТабельУчетаРабочегоВремени.Создать();
        Табель.Дата = ТекДата;               // дата документа – текущая
        Табель.Организация = Справочники.Организации.ПолучитьПоНаименованию("Главное предприятие");
        Табель.Подразделение = Справочники.Подразделения.ПолучитьПоНаименованию("Отдел разработки");
        Табель.Сотрудник = СсылкаНаСотрудника;

        // 4. Получаем график работы сотрудника (справочник "ГрафикиРаботы")
        // Предполагаем, что у сотрудника есть реквизит "ГрафикРаботы"
        График = СсылкаНаСотрудника.ГрафикРаботы;
        Если График = Неопределено Тогда
            Предупреждение("У сотрудника не задан график работы.");
            Возврат;
        КонецЕсли;

        // 5. Проходим по каждому дню текущего месяца
        Дата = НачалоМесяца;
        Пока Дата <= КонецМесяца Цикл
            // 5.1. Определяем плановое количество часов по графику
            ПлановыеЧасы = График.ПолучитьПлановыеЧасыДляДня(Дата);
            // 5.2. Вычисляем фактические часы (пример – обычные + сверхурочные + ночные)
            // Для простоты считаем, что сверхурочные – 1,5 * плановые, ночные – 0,5 * плановые
            ОбычныеЧасы = ПлановыеЧасы;
            СверхурочныеЧасы = ПлановыеЧасы * 0.5; // 50% сверхурочных
            НочныеЧасы = ПлановыеЧасы * 0.2;      // 20% ночных

            // 5.3. Добавляем строку табеля
            СтрокаТабеля = Табель.Строки.Добавить();
            СтрокаТабеля.Дата = Дата;
            СтрокаТабеля.РабочийДень = ПлановыеЧасы > 0; // признак рабочего дня
            СтрокаТабеля.Отработано = ОбычныеЧасы;
            СтрокаТабеля.Сверхурочно = СверхурочныеЧасы;
            СтрокаТабеля.Ночно = НочныеЧасы;
            // При необходимости можно заполнить реквизиты "Причина" и "Комментарий"

            Дата = Дата + 1; // переход к следующему дню
        КонецЦикла;

        // 6. Проводим документ (можно оставить в режиме черновика, если требуется проверка)
        Табель.Записать();
        // Табель.Провести(); // если необходимо сразу провести
        Сообщить("Табель для сотрудника " + СсылкаНаСотрудника.Наименование + " сформирован.");
    Иначе
        Предупреждение("Не указан сотрудник.");
    КонецЕсли;
КонецПроцедуры;

//===================================================================
// Пример вызова процедуры из формы документа "Табель учёта рабочего времени"
//===================================================================

&НаКлиенте
Процедура КнопкаЗаполнитьТабельНажатие(Элемент)
    // Открываем форму выбора сотрудника
    Выбор = Справочники.Сотрудники.Выбрать();
    Если Выбор.Выбрать() Тогда
        Сотрудник = Выбор.ПолучитьОбъект();
        // Вызываем серверную процедуру, передавая ссылку на выбранного сотрудника
        ЗаполнитьТабельДляСотрудника(Сотрудник);
        // Обновляем форму, чтобы отобразить новые строки
        ЭлементыФормы.СтрокиТабеля.Обновить();
    КонецЕсли;
КонецПроцедуры;

//===================================================================
// Пример автоматической проверки расхождений между суммами
// начислений/удержаний в регистрах расчёта и суммами, указанными
// в платёжных листах. Выводятся только сотрудники, у которых
// отклонение превышает 1 %.
//===================================================================

Процедура ПроверитьРасхожденияВЗарплате()
    // 1. Получаем текущий расчётный период (месяц, год).
    // В конфигурации «Зарплата и управление персоналом» период
    // хранится в глобальном объекте "ТекущийРасчётныйПериод".
    ТекущийПериод = ТекущийРасчётныйПериод(); // Возвратит объект Дата (01.01.2026 и т.д.)
    // Приведём период к началу месяца – это удобно для запросов.
    НачалоПериода = НачалоМесяца(ТекущийПериод);
    КонецПериода  = КонецМесяца(ТекущийПериод);

    // 2. Формируем запрос, который вернёт список всех сотрудников,
    // участвующих в расчёте за выбранный период, а также суммы
    // начислений и удержаний из регистров накопления.
    ТекстЗапроса = 
        "ВЫБРАТЬ
" +
        "   Сотрудники.Ссылка КАК Сотрудник,
" +
        "   СУММА(Начисления.Сумма) КАК СуммаНачислений,
" +
        "   СУММА(Удержания.Сумма) КАК СуммаУдержаний
" +
        "ИЗ
" +
        "   РегистрНакопления.РасчётЗаработнойПлаты.Начисления КАК Начисления
" +
        "   ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрНакопления.РасчётЗаработнойПлаты.Удержания КАК Удержания
" +
        "       ПО Начисления.Сотрудник = Удержания.Сотрудник
" +
        "       И Начисления.Период = Удержания.Период
" +
        "   ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Сотрудники КАК Сотрудники
" +
        "       ПО Сотрудники.Ссылка = Начисления.Сотрудник
" +
        "ГДЕ
" +
        "   Начисления.Период МЕЖДУ &НачалоПериода И &КонецПериода
" +
        "СГРУППИРОВАТЬ ПО Сотрудники.Ссылка";

    Запрос = Новый Запрос;
    Запрос.Текст = ТекстЗапроса;
    // Передаём параметры периода, чтобы запрос был «чистым»
    Запрос.УстановитьПараметр("НачалоПериода", НачалоПериода);
    Запрос.УстановитьПараметр("КонецПериода",   КонецПериода);

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    // 3. Пройдем по всем найденным сотрудникам и сравним суммы
    // с теми, что записаны в документе ПлатёжныйЛист.
    // Для простоты будем искать последний платёжный лист за тот же период.
    Сообщения = Новый СписокЗначений; // сюда будем складывать строки‑сообщения

    Пока Выборка.Следующий() Цикл
        Сотрудник = Выборка.Сотрудник;
        СуммаНачислений_Рег = Выборка.СуммаНачислений;
        СуммаУдержаний_Рег = Выборка.СуммаУдержаний;
        СуммаК выплате_Рег = СуммаНачислений_Рег - СуммаУдержаний_Рег;

        // Находим платёжный лист, сформированный за тот же период.
        ПлатёжныйЛист = ПлатёжныйЛист.Создать(); // создаём объект‑запрос
        ПлатёжныйЛист.УстановитьПараметр("Сотрудник", Сотрудник);
        ПлатёжныйЛист.УстановитьПараметр("Период",   ТекущийПериод);
        // Предположим, что в документе есть реквизит "СуммаКВыплате"
        // (в реальной конфигурации – поле "СуммаКВыплате" в табличной части).
        // Получим его через запрос к документу.
        ЗапросЛист = Новый Запрос;
        ЗапросЛист.Текст = 
            "ВЫБРАТЬ ПЕРВЫЕ 1
" +
            "   ПлатёжныйЛист.СуммаКВыплате КАК СуммаКВыплате
" +
            "ИЗ
" +
            "   Документ.ПлатёжныйЛист КАК ПлатёжныйЛист
" +
            "ГДЕ
" +
            "   ПлатёжныйЛист.Сотрудник = &Сотрудник
" +
            "   И ПлатёжныйЛист.Период = &Период";
        ЗапросЛист.УстановитьПараметр("Сотрудник", Сотрудник);
        ЗапросЛист.УстановитьПараметр("Период",   ТекущийПериод);
        РезультатЛист = ЗапросЛист.Выполнить();
        ВыборкаЛист = РезультатЛист.Выбрать();
        Если ВыборкаЛист.Следующий() Тогда
            СуммаКВыплате_Лист = ВыборкаЛист.СуммаКВыплате;
        Иначе
            // Если листа нет – считаем, что ошибка уже есть.
            СуммаКВыплате_Лист = 0;
        КонецЕсли;

        // 4. Вычисляем процентное отклонение.
        Если СуммаКВыплате_Лист = 0 Тогда
            Отклонение = 100; // делим на ноль – считаем, что отклонение критическое
        Иначе
            Отклонение = ((СуммаКВыплате_Лист - СуммаКВыплате_Рег) / СуммаКВыплате_Лист) * 100;
        КонецЕсли;

        // Если отклонение по модулю больше 1 % – выводим в список.
        Если АбсолютноеЗначение(Отклонение) > 1 Тогда
            ТекстСообщения = СтрШаблон("Сотрудник: %1, Отклонение: %2%% (Регистры = %3, Платёжный лист = %4)",
                                      Сотрудник.Наименование,
                                      Формат(Отклонение, "Число:0.00"),
                                      Формат(СуммаКВыплате_Рег, "Число:0.00"),
                                      Формат(СуммаКВыплате_Лист, "Число:0.00"));
            Сообщения.Добавить(ТекстСообщения);
        КонецЕсли;
    КонецЦикла;

    // Выводим результат. Можно использовать MessageBox, либо
    // вывести в форму, но для простоты покажем в диалоговом окне.
    Если Сообщения.Количество() = 0 Тогда
        Message("Расхождений более чем на 1 % не найдено.");
    Иначе
        ТекстВывода = "Найдены расхождения более чем на 1 %:\n" + СтрОбъединить(Сообщения, "\n");
        Message(ТекстВывода);
    КонецЕсли;
КонецПроцедуры

//===================================================================
// Как вызвать процедуру из формы или из общего модуля?
// -------------------------------------------------------------------
//   // В обработчике кнопки формы:
//   ПроверитьРасхожденияВЗарплате();
//===================================================================

//===================================================================
//  Процедура ExportToExcel
//  Автоматический экспорт любого стандартного отчёта 1С:Зарплата и
//  управление персоналом 3.1 в файл Excel.
//===================================================================
//  Параметры процедуры:
//      Отчет          – объект «Отчёт» (например, "ОтчётПоУчётуРабочегоВремени").
//      ПутьКФайлу     – строка, полный путь к файлу, в который будет сохранён
//                       результат (например, "C:\Temp\Report.xlsx").
//      Параметры      – структура с настройками экспорта (можно передать
//                       NULL – будут использованы значения по умолчанию).
//===================================================================

Процедура ExportToExcel(Отчет, ПутьКФайлу, Параметры = Неопределено)
    // 1. Проверяем, что передан объект отчёта
    Если Не Отчет = Неопределено И ТипЗнч(Отчет) = Тип("Отчет") Тогда
        // 2. Формируем параметры экспорта, если они не заданы пользователем
        Если Параметры = Неопределено Тогда
            Параметры = Новый Структура;
            // Включить заголовки столбцов
            Параметры.Вставить("ВключитьЗаголовки", Истина);
            // Сохранить форматирование (цвета, границы)
            Параметры.Вставить("СохранитьФорматирование", Истина);
            // Экспортировать все страницы отчёта
            Параметры.Вставить("ЭкспортироватьВсеСтраницы", Истина);
        КонецЕсли;

        // 3. Получаем объект внешней обработки «ВнешняяОбработка.ЭкспортВExcel»
        //    (в поставке 1С:ЗУП 3.1 такой обработки уже существует).
        ВнешОбраб = ВнешняяОбработка.ПолучитьОбъект("ВнешняяОбработка.ЭкспортВExcel");
        Если ВнешОбраб = Неопределено Тогда
            Предупреждение("Внешняя обработка 'ЭкспортВExcel' не найдена. Установите её в конфигурацию.");
            Возврат;
        КонецЕсли;

        // 4. Заполняем параметры внешней обработки
        //    Параметр "Отчет" – имя отчёта, который нужно экспортировать.
        //    Параметр "Путь" – путь к файлу Excel.
        //    Параметр "Настройки" – структура с настройками (см. пункт 2).
        ВнешОбраб.УстановитьПараметр("Отчет", Отчет.Имя());
        ВнешОбраб.УстановитьПараметр("Путь", ПутьКФайлу);
        ВнешОбраб.УстановитьПараметр("Настройки", Параметры);

        // 5. Запускаем обработку в режиме без пользовательского интерфейса
        Попытка
            ВнешОбраб.Запустить(Ложь); // Ложь – без диалогов
            Сообщить("Отчёт успешно экспортирован в файл: " + ПутьКФайлу);
        Исключение
            // Если возникла ошибка – выводим её текст
            Сообщить("Ошибка экспорта: " + ОписаниеОшибки());
        КонецПопытки;
    Иначе
        Предупреждение("Не указан объект отчёта или передан неверный тип.");
    КонецЕсли;
КонецПроцедуры;

//===================================================================
// Пример вызова процедуры из любой формы или общего модуля
//===================================================================
// 1. Открываем нужный отчёт (например, "ОтчётПоУчётуРабочегоВремени")
Отчет = Отчёты.Получить("ОтчётПоУчётуРабочегоВремени");
// 2. Формируем путь к файлу (можно запросить у пользователя через ДиалогВыбораФайла)
Путь = "C:\Temp\Отчёт_Учёт_Времени.xlsx";
// 3. Вызываем экспорт
ExportToExcel(Отчет, Путь);
//===================================================================

/*
  -------------------------------------------------------------------
  Что делает код:
  • Проверяет корректность переданных параметров.
  • Формирует набор стандартных настроек экспорта (заголовки, формат,
    все страницы).
  • Находит встроенную внешнюю обработку «ЭкспортВExcel», которая умеет
    преобразовывать любой табличный отчёт в файл .xlsx.
  • Передаёт в обработку имя отчёта, путь сохранения и структуру
    настроек.
  • Запускает обработку в «тихом» режиме (без диалогов) и выводит
    сообщение об успехе/ошибке.
  -------------------------------------------------------------------
*/

//===================================================================
//  Рекомендации по дальнейшей работе с полученным файлом Excel
//===================================================================
// 1. Откройте файл в Microsoft Excel или LibreOffice Calc и проверьте:
//      • Совпадают ли суммы в итоговых строках с данными в 1С.
//      • Корректно ли отобразились заголовки колонок (особенно если в
//        отчёте использовались пользовательские реквизиты).
// 2. При необходимости удалите лишние служебные столбцы (например,
//      «Код», «Ссылка»), оставив только те, которые нужны для анализа.
// 3. Постройте графики:
//      • Диаграмма «Часы работы по подразделениям» – удобно для
//        визуального контроля нагрузки.
//      • Гистограмма «Переработка за месяц» – помогает выявить
//        отклонения от нормы.
// 4. Если требуется передать данные в другую систему (например, в
//    1С:Бухгалтерию), сохраните лист как CSV (Файл → Сохранить как →
//    CSV UTF‑8) и импортируйте через стандартный механизм загрузки.
// 5. При регулярной необходимости экспорта автоматизируйте процесс:
//      • Добавьте кнопку «Экспорт в Excel» на форму отчёта и привяжите
//        её к вызову ExportToExcel.
//      • Настройте плановый регламент (Общий модуль → Планировщик),
//        который будет формировать и сохранять отчёт в нужную папку
//        (например, каждый последний день месяца).
//===================================================================

/*===================================================================
   Обмен данными «Табель учёта рабочего времени → 1С:Бухгалтерия»
   Конфигурация: 1С:Зарплата и управление персоналом 3.1
   Версия платформы: 8.3.19 и выше
   -------------------------------------------------------------------
   Описание:  скрипт‑обработка формирует файл обмена в формате XML
   (стандартный формат «Обмен данными»), сохраняет его в каталог
   "Exchange" и записывает журнал выполнения.
===================================================================*/

#Область ПрограммныйКод

Процедура ФормироватьИЭкспортироватьФайлОбмена(ДатаНачала, ДатаОкончания, Подразделения) Экспорт
    // ---------------------------------------------------------------
    // 1. Подготовка параметров обмена
    // ---------------------------------------------------------------
    Попытка
        // Проверка входных параметров
        Если ДатаНачала > ДатаОкончания Тогда
            ВызватьИсключение "Дата начала не может быть позже даты окончания";
        КонецЕсли;
        Если НЕ ЗначениеЗаполнено(Подразделения) Тогда
            ВызватьИсключение "Не указаны подразделения для передачи";
        КонецЕсли;
    Исключение
        Сообщить("Ошибка проверки параметров: " + ОписаниеОшибки());
        Возврат;
    КонецПопытки;

    // ---------------------------------------------------------------
    // 2. Получаем данные отчёта «Табель учёта рабочего времени»
    // ---------------------------------------------------------------
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
            |   ТрудовыеДни.Дата КАК Дата,
            |   ТрудовыеДни.Сотрудник КАК Сотрудник,
            |   ТрудовыеДни.Подразделение КАК Подразделение,
            |   ТрудовыеДни.ОтработаноЧасов КАК Часы,
            |   ТрудовыеДни.КодНачисления КАК КодНачисления,
            |   ТрудовыеДни.Сумма КАК Сумма
            |ИЗ
            |   РегистрНакопления.ТабельУчетаРабочегоВремени.ТрудовыеДни КАК ТрудовыеДни
            |ГДЕ
            |   ТрудовыеДни.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания
            |   И ТрудовыеДни.Подразделение В(&Подразделения)";
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    Запрос.УстановитьПараметр("Подразделения", Подразделения);

    Попытка
        Результат = Запрос.Выполнить();
    Исключение
        ЗаписатьВЖурнал("Ошибка выполнения запроса: " + ОписаниеОшибки(), УровеньЖурнала.Ошибка);
        Возврат;
    КонецПопытки;

    // ---------------------------------------------------------------
    // 3. Формируем XML‑файл в соответствии со схемой обмена
    // ---------------------------------------------------------------
    ПутьКФайлу = КаталогОбмена() + "\Отчет_Табель_" + Формат(ДатаНачала, "ДФ=yyyyMMdd") + "_" + Формат(ДатаОкончания, "ДФ=yyyyMMdd") + ".xml";
    Попытка
        XMLДокумент = Новый XMLDocument;
        XMLДокумент.УстановитьКорневойЭлемент("ОбменДанными");
        Корень = XMLДокумент.КорневойЭлемент;
        Корень.УстановитьАтрибут("ВерсияСхемы", "1.0");
        Корень.УстановитьАтрибут("Дата", Формат(ТекущаяДата(), "ДФ=yyyy-MM-ddTHH:mm:ss"));

        Для Каждого Строка Из Результат Выбрать() Цикл
            ЭлементЗаписи = Корень.ДобавитьЭлемент("Запись");
            ЭлементЗаписи.ДобавитьЭлемент("Дата", Формат(Строка.Дата, "ДФ=yyyy-MM-dd"));
            ЭлементЗаписи.ДобавитьЭлемент("Сотрудник", Строка.Сотрудник);
            ЭлементЗаписи.ДобавитьЭлемент("Подразделение", Строка.Подразделение);
            ЭлементЗаписи.ДобавитьЭлемент("Часы", Строка.Часы);
            ЭлементЗаписи.ДобавитьЭлемент("КодНачисления", Строка.КодНачисления);
            ЭлементЗаписи.ДобавитьЭлемент("Сумма", Формат(Строка.Сумма, "ЧГ=0.00"));
        КонецЦикла;

        // Сохраняем файл
        XMLДокумент.Записать(ПутьКФайлу, КодировкаUTF8);
        ЗаписатьВЖурнал("Файл обмена успешно сформирован: " + ПутьКФайлу, УровеньЖурнала.Информация);
    Исключение
        ЗаписатьВЖурнал("Ошибка формирования XML‑файла: " + ОписаниеОшибки(), УровеньЖурнала.Ошибка);
        Возврат;
    КонецПопытки;

    // ---------------------------------------------------------------
    // 4. При необходимости – отправляем файл в 1С:Бухгалтерию (по сети, FTP и т.п.)
    // ---------------------------------------------------------------
    // Здесь можно добавить код копирования в общую папку или загрузку по FTP.
КонецПроцедуры

//===================================================================
// Вспомогательные функции
//===================================================================

Функция КаталогОбмена() Экспорт
    // Путь к каталогу, где будет храниться файл обмена.
    // По умолчанию – подпапка "Exchange" в каталоге данных сервера.
    Путь = ПолучитьКаталогВременныхФайлов() + "\Exchange";
    Если НЕ КаталогСуществует(Путь) Тогда
        СоздатьКаталог(Путь);
    КонецЕсли;
    Возврат Путь;
КонецФункции

Процедура ЗаписатьВЖурнал(ТекстСообщения, Уровень = УровеньЖурнала.Информация) Экспорт
    Журнал = ЖурналыРегистрации.Получить("ОбменДанными");
    Если Журнал = Неопределено Тогда
        Журнал = ЖурналыРегистрации.Создать("ОбменДанными");
    КонецЕсли;
    Журнал.Записать(ТекстСообщения, Уровень);
КонецПроцедуры

#КонецОбласти

