//===================================================================
//  Тестовый набор данных для справочников «Сотрудники», «Подразделения», «Должности»
//  Преднамерённые ошибки:
//   1) Дублирование записи сотрудника (одинаковые ФИО, ДР, ИНН).
//   2) У одного из сотрудников указан код подразделения, которого нет в справочнике.
//===================================================================

// Процедура, которую можно вызвать из любой формы или обработчика.
Процедура СоздатьТестовыеДанные()
    // ---------------------------------------------------------------
    // 1. Создаём подразделения (справочник "Подразделения")
    // ---------------------------------------------------------------
    // Подразделение 1
    Подразделение1 = Справочники.Подразделения.СоздатьЭлемент();
    Подразделение1.Код = "DEP001";               // Уникальный код
    Подразделение1.Наименование = "Отдел продаж";
    Подразделение1.Записать();

    // Подразделение 2
    Подразделение2 = Справочники.Подразделения.СоздатьЭлемент();
    Подразделение2.Код = "DEP002";
    Подразделение2.Наименование = "Бухгалтерия";
    Подразделение2.Записать();

    // Подразделение 3
    Подразделение3 = Справочники.Подразделения.СоздатьЭлемент();
    Подразделение3.Код = "DEP003";
    Подразделение3.Наименование = "ИТ‑поддержка";
    Подразделение3.Записать();

    // ---------------------------------------------------------------
    // 2. Создаём должности (справочник "Должности")
    // ---------------------------------------------------------------
    // Должность 1
    Должность1 = Справочники.Должности.СоздатьЭлемент();
    Должность1.Код = "POS001";
    Должность1.Наименование = "Менеджер по продажам";
    Должность1.Записать();

    // Должность 2
    Должность2 = Справочники.Должности.СоздатьЭлемент();
    Должность2.Код = "POS002";
    Должность2.Наименование = "Бухгалтер";
    Должность2.Записать();

    // ---------------------------------------------------------------
    // 3. Создаём сотрудников (справочник "Сотрудники")
    // ---------------------------------------------------------------
    // ---------- Сотрудник 1 (корректный) ----------
    Сотрудник1 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник1.ФИО = "Иванов Иван Иванович";
    Сотрудник1.ДатаРождения = Дата(1985,5,12);
    Сотрудник1.ИНН = "770123456789";
    Сотрудник1.Подразделение = Подразделение1;   // Ссылка на существующее подразделение
    Сотрудник1.Должность = Должность1;
    Сотрудник1.Записать();

    // ---------- Сотрудник 2 (корректный) ----------
    Сотрудник2 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник2.ФИО = "Петров Петр Петрович";
    Сотрудник2.ДатаРождения = Дата(1990,3,22);
    Сотрудник2.ИНН = "770987654321";
    Сотрудник2.Подразделение = Подразделение2;
    Сотрудник2.Должность = Должность2;
    Сотрудник2.Записать();

    // ---------- Сотрудник 3 (корректный) ----------
    Сотрудник3 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник3.ФИО = "Сидорова Мария Владимировна";
    Сотрудник3.ДатаРождения = Дата(1988,11,5);
    Сотрудник3.ИНН = "770112233445";
    Сотрудник3.Подразделение = Подразделение3;
    Сотрудник3.Должность = Должность1;
    Сотрудник3.Записать();

    // ---------- Сотрудник 4 (дублирование) ----------
    // Ошибка №1: полностью совпадающие ФИО, ДР и ИНН с сотрудником 1.
    Сотрудник4 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник4.ФИО = "Иванов Иван Иванович";      // Дублируется
    Сотрудник4.ДатаРождения = Дата(1985,5,12);    // Дублируется
    Сотрудник4.ИНН = "770123456789";            // Дублируется
    Сотрудник4.Подразделение = Подразделение2;    // Можно любой, но ссылка корректна
    Сотрудник4.Должность = Должность2;
    Сотрудник4.Записать();

    // ---------- Сотрудник 5 (ошибочный код подразделения) ----------
    // Ошибка №2: указанный код подразделения "DEP999" отсутствует в справочнике.
    Сотрудник5 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник5.ФИО = "Кузнецов Алексей Сергеевич";
    Сотрудник5.ДатаРождения = Дата(1992,7,19);
    Сотрудник5.ИНН = "770556677889";
    // Попытка установить ссылку через код, которого нет.
    // В 1С обычно ссылка задаётся объектом, поэтому имитируем ошибку через поиск.
    Попытка
        Сотрудник5.Подразделение = Справочники.Подразделения.НайтиПоКоду("DEP999"); // НЕ НАЙДЁТ запись
    Исключение
        // Ссылка останется пустой – это и есть ошибка.
        Сообщить("Ошибка: подразделение с кодом DEP999 не найдено. Сотрудник будет записан без ссылки на подразделение.");
    КонецПопытки;
    Сотрудник5.Должность = Должность1;
    Сотрудник5.Записать();

    // ---------- Сотрудник 6 (корректный) ----------
    Сотрудник6 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник6.ФИО = "Новикова Ольга Петровна";
    Сотрудник6.ДатаРождения = Дата(1995,2,28);
    Сотрудник6.ИНН = "770998877665";
    Сотрудник6.Подразделение = Подразделение1;
    Сотрудник6.Должность = Должность2;
    Сотрудник6.Записать();

    // ---------- Сотрудник 7 (корректный) ----------
    Сотрудник7 = Справочники.Сотрудники.СоздатьЭлемент();
    Сотрудник7.ФИО = "Морозов Дмитрий Алексеевич";
    Сотрудник7.ДатаРождения = Дата(1983,9,14);
    Сотрудник7.ИНН = "770443322110";
    Сотрудник7.Подразделение = Подразделение3;
    Сотрудник7.Должность = Должность2;
    Сотрудник7.Записать();

    // ---------------------------------------------------------------
    // Информируем пользователя о завершении создания тестовых данных.
    // ---------------------------------------------------------------
    Сообщить("Тестовые данные созданы. Обратите внимание на ошибки: дублирование сотрудника (Иванов И.И.) и отсутствие подразделения DEP999.");
КонецПроцедуры

//===================================================================
// Как использовать:
// 1. Откройте конфигуратор, перейдите в любой модуль (например, обработку).
// 2. Вставьте приведённый код.
// 3. Вызовите процедуру СоздатьТестовыеДанные() из формы или из окна
//    выполнения кода (Ctrl+F9).
//===================================================================
}   (Note: The outer braces are only for the JSON wrapper; copy the code inside the "code" field.)

questions:
A) Ошибки при импорте данных из внешних систем без проверки уникальности ФИО и табельного номера; 
B) Неправильные настройки прав доступа к справочнику; 
C) Автоматическое создание записей при каждом входе в систему; 
D) Использование регистров накопления вместо справочников для хранения персонала.

A) Сравнение значений полей «ФИО» и «Табельный номер» через обработку «Найти дубликаты» в режиме списка; 
B) Просмотр журнала регистрации изменений; 
C) Сортировка справочника по полю «Дата создания»; 
D) Проверка связей с регистром «Зарплата».

A) Зарплатные начисления будут распределены в неверное подразделение, что приведёт к ошибкам в аналитических отчетах и возможному неверному начислению надбавок; 
B) Система полностью отменит расчёт зарплаты для этого сотрудника; 
C) Никак, код подразделения используется только для отображения в справочнике; 
D) Ошибка будет автоматически исправлена при запуске обработки «Перерасчёт зарплаты».

A) Регистры накопления позволяют проследить, какие записи использовались в расчётах (например, начисления по должностям), и выявить «мёртвые» ссылки или несоответствия; 
B) Они хранят только исторические данные о зарплате и не влияют на проверку связей; 
C) Регистры накопления автоматически удаляют все некорректные ссылки; 
D) Их использование ограничено только финансовыми отчётами и не относится к справочникам.

A) 1) Выявить ошибку (дубликат/неверный код); 2) Отключить автоматические расчёты; 3) Удалить/объединить дублирующие записи; 4) Обновить ссылки в регистрах накопления; 5) Включить расчёты и проверить результаты; 
B) 1) Сразу удалить все подозрительные записи; 2) Перезапустить систему; 3) Проверить журнал; 4) Оставить всё как есть; 
C) 1) Изменить код подразделения вручную без проверки; 2) Пересчитать зарплату; 3) Не проверять регистры; 
D) 1) Создать новые справочники; 2) Перенести данные; 3) Удалить старые справочники.

content_blocks.code:
// ---------------------------------------------------------------
//  Сценарий исправления устаревших ставок в конфигурации
//  «1С:Зарплата и управление персоналом 3.1»
//  Выполняется в режиме Конфигуратора через COM‑интерфейс.
//  ---------------------------------------------------------------

// 1. Подключаем COM‑коннектор к Конфигуратору.
//    Для работы скрипта требуется установленный клиент 1С:Предприятие 8.3
//    и права администратора конфигурации.

var connector = new COMObject("V83.COMConnector"); // объект‑коннектор

// Путь к файлу конфигурации (можно заменить на "File=…" если используется файл .cf)
var connectionString = "Srvr=MyServer;Ref=ZUP_3_1;Usr=admin;Pwd=admin";

// Открываем сеанс в режиме конфигуратора (Mode=Config)
var session = connector.Connect(connectionString + ";Mode=Config");

// 2. Открываем конфигурацию и получаем объект метаданных.
var config = session.Configuration;

// ---------------------------------------------------------------
// 2.1. Находим справочник "СтавкиНалогов" и ищем запись с кодом "НДФЛ_2025"
// ---------------------------------------------------------------
var catalogTaxes = config.Catalogs.Find("СтавкиНалогов");
if (catalogTaxes == undefined) {
    throw new Error("Справочник СтавкиНалогов не найден в конфигурации!");
}

// Открываем форму редактирования справочника в режиме конфигуратора.
var taxesManager = session.GetObject("Справочник.СтавкиНалогов");
var taxes = taxesManager.Select(); // получаем набор записей

var taxRecord = null;
while (taxes.Next()) {
    if (taxes.Код == "НДФЛ_2025") {
        taxRecord = taxes;
        break;
    }
}

if (taxRecord == null) {
    throw new Error("Запись с кодом НДФЛ_2025 не найдена в справочнике СтавкиНалогов!");
}

// 3. Меняем значение поля "Ставка" на 13,5 % и сохраняем.
//    В 1С процент хранится как число (например, 13,5), а не как строка.

taxRecord.Ставка = 13.5;
// Добавляем комментарий к записи – поле "Комментарий" обычно присутствует в справочниках.
if (taxRecord.ЕстьПоле("Комментарий")) {
    taxRecord.Комментарий = "Обновлено согласно ФЗ‑2026‑...";
}

taxRecord.Write(); // сохраняем изменения

// ---------------------------------------------------------------
// 4. Корректируем коэффициенты страховых взносов (ПФР, ФОМС, ФСС)
// ---------------------------------------------------------------
var catalogInsurance = config.Catalogs.Find("СтавкиСтраховыхВзносов");
if (catalogInsurance == undefined) {
    throw new Error("Справочник СтавкиСтраховыхВзносов не найден!");
}

var insuranceManager = session.GetObject("Справочник.СтавкиСтраховыхВзносов");
var insurance = insuranceManager.Select();

while (insurance.Next()) {
    // Предполагаем, что в справочнике есть поле "Код" (например, "ПФР", "ФОМС", "ФСС")
    switch (insurance.Код) {
        case "ПФР":
            insurance.Коэффициент = 22.0; // актуальная ставка 2026‑г.
            break;
        case "ФОМС":
            insurance.Коэффициент = 5.1;
            break;
        case "ФСС":
            insurance.Коэффициент = 2.9;
            break;
        default:
            // остальные записи оставляем без изменений
            continue;
    }
    // Добавляем комментарий
    if (insurance.ЕстьПоле("Комментарий")) {
        insurance.Комментарий = "Обновлено согласно ФЗ‑2026‑...";
    }
    insurance.Write(); // сохраняем запись
}

// ---------------------------------------------------------------
// 5. Сохраняем конфигурацию и закрываем сеанс.
// ---------------------------------------------------------------
session.SaveConfiguration(); // фиксируем изменения в файле .cf/.dt
session.Disconnect();

// ---------------------------------------------------------------
// Как проверить, что изменения успешно сохранены?
// ---------------------------------------------------------------
// 1) Откройте 1С:Предприятие в режиме «Конфигуратор» → «Справочники» →
//    «СтавкиНалогов». Найдите запись с кодом «НДФЛ_2025». Поле «Ставка»
//    должно показывать 13,5, а в поле «Комментарий» – «Обновлено согласно ФЗ‑2026‑…».
// 2) Аналогично откройте справочник «СтавкиСтраховыхВзносов» и проверьте
//    коэффициенты для ПФР, ФОМС и ФСС. Комментарий также должен быть заполнен.
// 3) При необходимости выполните «Обновить конфигурацию» в пользовательском
//    режиме и убедитесь, что расчёт заработной платы использует новые ставки.
// ---------------------------------------------------------------

// ────────────────────────────────────────────────────────────────────────
// 1. Подготовка временной таблицы «ТТекущиеСтавки» (данные из блока 2)
// ────────────────────────────────────────────────────────────────────────
ТТекущиеСтавки = Новый ТаблицаЗначений;
ТТекущиеСтавки.Колонки.Добавить("КодСтавки",      Новый ОписаниеТипов("Строка"));   // уникальный код ставки
ТТекущиеСтавки.Колонки.Добавить("Ставка",         Новый ОписаниеТипов("Число"));    // %
ТТекущиеСтавки.Колонки.Добавить("Коэффициент",   Новый ОписаниеТипов("Число"));    // коэффициент расчёта
ТТекущиеСтавки.Колонки.Добавить("ДатаИзменения",  Новый ОписаниеТипов("Дата"));

// Пример заполнения (в реальном сценарии – копипаст из Excel/скриншотов блока 2)
ТТекущиеСтавки.Добавить({
    КодСтавки      = "ОСНОВ",    // пример кода
    Ставка         = 13.5,
    Коэффициент    = 1,
    ДатаИзменения  = Дата(2024,01,01)
});
ТТекущиеСтавки.Добавить({
    КодСтавки      = "ДОП_СТРАХ", 
    Ставка         = 2.9,
    Коэффициент    = 1,
    ДатаИзменения  = Дата(2024,01,01)
});
// … добавить остальные строки из таблицы «Ожидаемые ставки»

// ────────────────────────────────────────────────────────────────────────
// 2. Запрос, формирующий список несоответствий
// ────────────────────────────────────────────────────────────────────────
Запрос = Новый Запрос;
Запрос.Текст =
"ВЫБРАТЬ
    Настройки.КодСтавки               КАК КодСтавки,
    Настройки.Ставка                  КАК ТекущаяСтавка,
    ТТекущиеСтавки.Ставка             КАК ОжидаемаяСтавка,
    Настройки.Коэффициент            КАК ТекущийКоэффициент,
    ТТекущиеСтавки.Коэффициент       КАК ОжидаемыйКоэффициент,
    Настройки.ДатаАктуализации       КАК ДатаИзменения
ИЗ
    РегистрСведений.НастройкиРасчета КАК Настройки
        ЛЕВОЕ СОЕДИНЕНИЕ &ТТекущиеСтавки КАК ТТекущиеСтавки
        ПО Настройки.КодСтавки = ТТекущиеСтавки.КодСтавки
ГДЕ
    Настройки.ДатаАктуализации >= &ДатаНачала
    И (Настройки.Ставка <> ТТекущиеСтавки.Ставка
        ИЛИ Настройки.Коэффициент <> ТТекущиеСтавки.Коэффициент)";

// Параметр – с какого момента проверяем актуальность (например, начало текущего года)
Запрос.УстановитьПараметр("ДатаНачала", НачалоГода(ТекущаяДата()));

// ────────────────────────────────────────────────────────────────────────
// 3. Выполнение запроса и формирование табличного документа
// ────────────────────────────────────────────────────────────────────────
Результат = Запрос.Выполнить();
ТаблицаОшибок = Результат.Выгрузить();   // ТаблицаЗначений
КолОшибок = ТаблицаОшибок.Количество();

Если КолОшибок = 0 Тогда
    Сообщить("Настройки расчёта актуальны");
Иначе
    Сообщить("Обнаружены несоответствия: " + КолОшибок);

    // Формируем табличный документ
    ТабДок = Новый ТабличныйДокумент;
    // Добавляем заголовок
    ТабДок.Ячейка(1,1).Текст = "Код ставки";
    ТабДок.Ячейка(1,2).Текст = "Текущая ставка";
    ТабДок.Ячейка(1,3).Текст = "Ожидаемая ставка";
    ТабДок.Ячейка(1,4).Текст = "Текущий коэффициент";
    ТабДок.Ячейка(1,5).Текст = "Ожидаемый коэффициент";
    ТабДок.Ячейка(1,6).Текст = "Дата изменения";
    // Выводим строки‑ошибки, начиная со второй строки
    ТабДок.Вывести(ТаблицаОшибок, 2, 1);

    // Сохраняем в Excel – удобно передать бухгалтерии
    ПутьФайла = "C:\Temp\Несоответствия_НастройкиРасчета.xlsx";
    ТабДок.Записать(ПутьФайла);
    Сообщить("Табличный документ сохранён: " + ПутьФайла);
КонецЕсли;

// ────────────────────────────────────────────────────────────────────────
// 4. Итоги
// ────────────────────────────────────────────────────────────────────────
// После выполнения скрипта пользователь получает:
// • Сообщение «Настройки расчёта актуальны» – если ошибок нет;
// • Сообщение «Обнаружены несоответствия: N» и файл Excel с детализацией,
//   где указаны текущие и ожидаемые значения ставок/коэффициентов и дата их изменения.
// Файл Excel можно открыть, отфильтровать строки, добавить комментарии и
// передать в отдел бухгалтерии/кадров для корректировки справочников.

assignment.description:
Цель задания – применить полученные в уроке знания о налоговых и страховых ставках к вашему текущему проекту по автоматизации расчёта заработной платы в 1С. Вы будете работать в тестовой копии базы, найти устаревшие или ошибочные параметры, привести их в соответствие с официальными ставками 2026 г., проверить влияние изменений на расчёт и оформить результаты в виде отчёта.

Шаги выполнения:
1. Откройте тестовую копию конфигурации «1С:Зарплата и управление персоналом 3.1» в режиме Конфигуратора.
2. В справочнике **«Ставки налогов»** и **«Ставки страховых взносов»** сравните текущие значения с таблицей официальных ставок (НДФЛ 13 %/15 %/30 %, ПФР 23 % + региональный коэффициент 0‑5 %, ФОМС 5,1 %, ФСС 2,9 % и др.).
3. Зафиксируйте все расхождения в таблице «До/После» (код ставки, текущая ставка, требуемая ставка, дата начала действия, комментарий).
4. В Конфигураторе исправьте найденные записи: задайте правильный процент, укажите дату начала действия, добавьте комментарий «Обновлено согласно ФЗ‑2026‑…». При необходимости добавьте региональные коэффициенты в справочник «Региональные коэффициенты».
5. Сохраните конфигурацию, запустите регламент **«Проверка актуальности ставок»** (или выполните запрос из примера кода) и убедитесь, что предупреждений нет.
6. Проведите тестовый расчёт зарплаты для условного сотрудника, принявшего на работу в июле 2026 г., проверьте, что начисления НДФЛ, ПФР, ФОМС, ФСС соответствуют новым ставкам.
7. Подготовьте отчёт в формате Markdown, включив:
   - Краткое введение и цель аудита;
   - Описание методики (какие справочники проверялись, какие запросы использовались);
   - Таблицу сравнения «До/После»;
   - Скриншоты листов справочников до и после изменения;
   - Фрагменты кода/PlantUML, если экспортировали метаданные;
   - Выводы и рекомендации для дальнейшего поддержания актуальности ставок.

Отчёт загрузите как один файл.

content_blocks.code:
/*
  Шаг 1. Задаём налоговые ставки (НДФЛ 13 %, страховые взносы работодателя 30 % и работника 2 %).
  В конфигураторе создаём объект «Справочник.НалоговыеСтавки» и заполняем его.
*/

&НаКлиенте
Процедура УстановитьНалоговыеСтавки()
    // Открываем справочник в режиме редактирования
    Ставки = Справочники.НалоговыеСтавки.Выбрать();
    // НДФЛ
    Запись = Справочники.НалоговыеСтавки.СоздатьЭлемент();
    Запись.Код = "НДФЛ";
    Запись.Наименование = "Налог на доходы физических лиц";
    Запись.Ставка = 13;
    Запись.Записать();
    // Взносы работодателя
    Запись = Справочники.НалоговыеСтавки.СоздатьЭлемент();
    Запись.Код = "ВЗР";
    Запись.Наименование = "Страховые взносы работодателя";
    Запись.Ставка = 30;
    Запись.Записать();
    // Взносы работника
    Запись = Справочники.НалоговыеСтавки.СоздатьЭлемент();
    Запись.Код = "ВЗРБ";
    Запись.Наименование = "Страховые взносы работника";
    Запись.Ставка = 2;
    Запись.Записать();
КонецПроцедуры

/*
  Шаг 2. Параметры округления – в пользу работника, 2 знака после запятой.
  Пишем запись в регистр «НастройкиРасчета».
*/

&НаКлиенте
Процедура УстановитьОкругление()
    Запись = РегистрыСведений.НастройкиРасчета.Выбрать();
    // Если запись уже существует – обновляем, иначе создаём новую
    Если Не Запись.Следующий() Тогда
        Запись = РегистрыСведений.НастройкиРасчета.СоздатьЭлемент();
    КонецЕсли;
    Запись.Параметр = "Округление";
    Запись.Значение = "ВПОЛЬЗОВАТЕЛЯ"; // В пользу работника
    Запись.Знаков = 2;
    Запись.Записать();
КонецПроцедуры

/*
  Шаг 3. Правила расчёта надбавок.
  Создаём два типа надбавок: процент от оклада (10 %) и фиксированную сумму (1500 ₽).
*/

&НаКлиенте
Процедура УстановитьНадбавки()
    // Надбавка‑процент
    Надбавка = Справочники.Надбавки.СоздатьЭлемент();
    Надбавка.Код = "ПРОЦЕНТ_ОКЛАД";
    Надбавка.Наименование = "Процент от оклада";
    Надбавка.ТипРасчёта = "Процент";
    Надбавка.Значение = 10; // 10 %
    Надбавка.Записать();
    // Надбавка‑фикс
    Надбавка = Справочники.Надбавки.СоздатьЭлемент();
    Надбавка.Код = "ФИКС_СУММА";
    Надбавка.Наименование = "Фиксированная надбавка";
    Надбавка.ТипРасчёта = "Фикс";
    Надбавка.Сумма = 1500;
    Надбавка.Записать();
КонецПроцедуры

/*
  Шаг 4. Проверка актуальности настроек через регистр «НастройкиРасчета».
  Выводим в консоль текущие значения.
*/

&НаКлиенте
Процедура ПроверитьНастройки()
    Выборка = РегистрыСведений.НастройкиРасчета.Выбрать();
    Пока Выборка.Следующий() Цикл
        Сообщить("Параметр: " + Выборка.Параметр + ", Значение: " + Выборка.Значение + ", Знаков: " + Выборка.Знаков);
    КонецЦикла;
КонецПроцедуры

/*
  После выполнения всех процедур нажмите кнопку «Выполнить»,
  и в журнале сообщений появятся текущие настройки расчёта.
*/

assignment.description:
**Цель задания** – закрепить навыки настройки налоговых ставок, страховых взносов и правил округления в 1С:ЗУП 3.1, выполнить расчёт за выбранный месяц и задокументировать изменения в рамках вашего проекта.

**Контекст** – у вас уже есть тестовая база 1С, в которой созданы справочники сотрудников, начислений и пр. Все действия выполняются в этой базе.

**Обязательные шаги**:
1. **Сбор актуальных данных** – найдите в официальных источниках (ФНС, ПФР, ФСС) текущие ставки НДФЛ, страховых взносов и правила округления. Сохраните ссылки и даты.
2. **Обновление параметров** – в справочнике/регистре «Параметры расчёта» измените:
   - ставку НДФЛ;
   - ставки страховых взносов работодателя и работника;
   - правило округления (например, «В пользу работника», 2 знака). Добавьте комментарий с указанием источника.
3. **Запуск расчёта** – проведите расчёт зарплаты за любой полностью заполненный месяц (например, текущий). Сохраните журнал выполнения.
4. **Проверка результатов**:
   - откройте регистры «Начисления» и «Удержания», убедитесь, что суммы соответствуют новым ставкам;
   - сформируйте стандартный отчёт «Выплаты» и экспортируйте его в Excel (CSV/XLSX).
5. **Документирование** – подготовьте отчёт, включив:
   - титульный лист с названием проекта и датой сдачи;
   - раздел «Источники данных» (список нормативных актов, ссылки);
   - таблицу «Параметры до/после» со старыми и новыми значениями;
   - скриншоты (или PlantUML‑коды) формы редактирования параметров;
   - фрагменты кода процедур обновления (можно взять из примеров урока);
   - выводы о влиянии изменений (например, изменение чистой зарплаты на X %).
6. **Файл сдачи** – один файл отчёта (Markdown, PDF или DOCX) со всеми перечисленными разделами.

**Что должно быть в итоговом файле** – титульный лист, источники, таблица «Параметры до/после», скриншоты/PlantUML, код процедур, выводы, приложение – экспортированный отчёт «Выплаты».

content_blocks.code:
// ------------------------------------------------------------
//  Пример запроса к регистру «Расчёт зарплаты»
//  Цель – вывести все записи, где поле "Сумма" < 0
//  за выбранный расчётный период (параметр Период)
// ------------------------------------------------------------

// 1. Описание запроса (SQL‑подобный язык 1С)
Запрос = Новый Запрос;
Запрос.Текст =
"""
// SELECT – список полей, которые будем получать в результате
SELECT
    // Идентификатор сотрудника (ссылка на справочник "Сотрудники")
    РасчетЗарплаты.Сотрудник КАК Сотрудник,
    // Дата расчёта (поле "Дата")
    РасчетЗарплаты.Дата КАК Дата,
    // Сумма начисления/удержания (поле "Сумма")
    РасчетЗарплаты.Сумма КАК Сумма,
    // Причина отрицательной суммы (поле "ВидНачисления" – справочник "ВидыНачислений")
    РасчетЗарплаты.ВидНачисления КАК ВидНачисления

// FROM – из какого регистра берём данные
FROM
    РегистрРасчётЗарплаты.РасчетЗарплаты КАК РасчетЗарплаты

// WHERE – условия фильтрации
WHERE
    // Выбираем только записи за указанный период
    РасчетЗарплаты.Период МЕЖДУ &ДатаНачала И &ДатаОкончания
    // И только те, у которых сумма отрицательная
    И РасчетЗарплаты.Сумма < 0

// GROUP BY – группируем, если хотим агрегировать (в данном случае не требуется,
// но оставляем для наглядности, чтобы показать синтаксис)
GROUP BY
    РасчетЗарплаты.Сотрудник,
    РасчетЗарплаты.Дата,
    РасчетЗарплаты.Сумма,
    РасчетЗарплаты.ВидНачисления
""";

// 2. Параметры запроса – задаём диапазон дат расчётного периода
//   (можно взять из формы, диалогового окна или задать вручную)
ДатаНачала   = НачалоМесяца(ТекущаяДата()); // пример: первый день текущего месяца
ДатаОкончания = КонецМесяца(ТекущаяДата());   // пример: последний день текущего месяца
Запрос.УстановитьПараметр("ДатаНачала",   ДатаНачала);
Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

// 3. Выполняем запрос
Результат = Запрос.Выполнить();
Выборка = Результат.Выбрать();

// 4. Обрабатываем полученные строки
Пока Выборка.Следующий() Цикл
    // Ссылка на сотрудника – можно вывести ФИО через .Получить()
    Сотрудник = Выборка.Сотрудник;
    ФИО = Сотрудник.Получить(); // если справочник "Сотрудники" имеет реквизит "Наименование"
    Сообщить("Сотрудник: " + ФИО + ", Дата: " + Формат(Выборка.Дата, "ДФ=dd.MM.yyyy") +
            ", Сумма: " + Формат(Выборка.Сумма, "ЧГ=0.00") +
            ", Вид начисления: " + Выборка.ВидНачисления.Наименование);
КонецЦикла;

// ------------------------------------------------------------
// Как выполнить запрос в конфигураторе:
// 1. Откройте конфигуратор → меню «Отчёты» → «Новый запрос».
// 2. В появившемся окне вставьте весь текст из свойства "Текст" объекта Запрос
//    (начиная с SELECT и заканчивая GROUP BY).
// 3. Нажмите кнопку «Параметры», добавьте два параметра:
//      - ДатаНачала   (Тип – Дата)
//      - ДатаОкончания (Тип – Дата)
//    Установите их значения (например, текущий месяц).
// 4. Нажмите «Выполнить». В окне результатов будет таблица с колонками:
//      Сотрудник | Дата | Сумма | ВидНачисления
//    Каждая строка – запись, где сумма отрицательная.
//    Идентификатор сотрудника – ссылка, её можно открыть двойным щелчком,
//    чтобы увидеть карточку сотрудника.
// 5. При необходимости экспортируйте результат в Excel (кнопка «Экспорт»).
// ------------------------------------------------------------
}

//===================================================================
//  Общая обработка «Запуск расчёта зарплаты и вывод итогов»
//  Конфигурация: 1С:Зарплата и управление персоналом 3.1
//===================================================================
//  Описание задачи
//  1. Программно запустить расчёт заработной платы за указанный месяц.
//  2. С помощью запросов получить суммарные значения из регистров
//     «РегистраторЗарплаты», «РегистраторНалогов» и «РегистраторВзносов».
//  3. Вывести полученные итоги в окно «Сообщения» (Message).
//===================================================================

&НаСервере
Процедура ЗапуститьРасчётИВывестиИтоги()
    // ---------------------------------------------------------------
    // 1. Формируем период расчёта – в примере май 2024 года.
    // ---------------------------------------------------------------
    ДатаНачала = Дата(2024, 5, 1);
    ДатаОкончания = Дата(2024, 5, 31);
    ПериодРасчёта = Новый Период(ДатаНачала, ДатаОкончания);

    // ---------------------------------------------------------------
    // 2. Получаем объект‑менеджер «РасчётЗарплаты». В конфигурации
    //    3.1 он объявлен как глобальный объект, поэтому можно создать
    //    его через конструктор.
    // ---------------------------------------------------------------
    Расчёт = Новый РасчётЗарплаты();

    // ---------------------------------------------------------------
    // 3. Запускаем расчёт. Метод ВыполнитьРасчёт() принимает объект
    //    Период и (опционально) набор параметров расчёта. Параметры
    //    оставляем пустыми – будут использованы текущие настройки
    //    конфигурации (налоги, страховые взносы, правила округления).
    // ---------------------------------------------------------------
    Попытка
        Расчёт.ВыполнитьРасчёт(ПериодРасчёта);
    Исключение
        // Если расчёт завершился с ошибкой – выводим её и прерываем.
        Сообщить("Ошибка при выполнении расчёта: " + ОписаниеОшибки());
        Возврат;
    КонецПопытки;

    // ---------------------------------------------------------------
    // 4. Формируем запросы к регистрационным накопительным регистрам.
    //    В каждом запросе суммируем нужный реквизит за выбранный период.
    // ---------------------------------------------------------------
    // ---- РегистраторЗарплаты ------------------------------------------------
    ЗапросЗарплата = Новый Запрос;
    ЗапросЗарплата.Текст = 
        "ВЫБРАТЬ" +
        "   СУММА(РегистраторЗарплаты.СуммаНачисления) КАК СуммаНачисления" +
        "ИЗ" +
        "   РегистраторЗарплаты" +
        "ГДЕ" +
        "   РегистраторЗарплаты.Период МЕЖДУ &ДатаНачала И &ДатаОкончания";
    ЗапросЗарплата.УстановитьПараметр("ДатаНачала", ДатаНачала);
    ЗапросЗарплата.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    РезультатЗарплата = ЗапросЗарплата.Выполнить();
    ВыборкаЗарплата = РезультатЗарплата.Выбрать();
    Если ВыборкаЗарплата.Следующий() Тогда
        СуммаНачисления = ВыборкаЗарплата.СуммаНачисления;
    Иначе
        СуммаНачисления = 0;
    КонецЕсли;

    // ---- РегистраторНалогов -------------------------------------------------
    ЗапросНалоги = Новый Запрос;
    ЗапросНалоги.Текст = 
        "ВЫБРАТЬ" +
        "   СУММА(РегистраторНалогов.СуммаНалога) КАК СуммаНалога" +
        "ИЗ" +
        "   РегистраторНалогов" +
        "ГДЕ" +
        "   РегистраторНалогов.Период МЕЖДУ &ДатаНачала И &ДатаОкончания";
    ЗапросНалоги.УстановитьПараметр("ДатаНачала", ДатаНачала);
    ЗапросНалоги.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    РезультатНалоги = ЗапросНалоги.Выполнить();
    ВыборкаНалоги = РезультатНалоги.Выбрать();
    Если ВыборкаНалоги.Следующий() Тогда
        СуммаНалога = ВыборкаНалоги.СуммаНалога;
    Иначе
        СуммаНалога = 0;
    КонецЕсли;

    // ---- РегистраторВзносов -------------------------------------------------
    ЗапросВзносы = Новый Запрос;
    ЗапросВзносы.Текст = 
        "ВЫБРАТЬ" +
        "   СУММА(РегистраторВзносов.СуммаВзноса) КАК СуммаВзноса" +
        "ИЗ" +
        "   РегистраторВзносов" +
        "ГДЕ" +
        "   РегистраторВзносов.Период МЕЖДУ &ДатаНачала И &ДатаОкончания";
    ЗапросВзносы.УстановитьПараметр("ДатаНачала", ДатаНачала);
    ЗапросВзносы.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    РезультатВзносы = ЗапросВзносы.Выполнить();
    ВыборкаВзносы = РезультатВзносы.Выбрать();
    Если ВыборкаВзносы.Следующий() Тогда
        СуммаВзноса = ВыборкаВзносы.СуммаВзноса;
    Иначе
        СуммаВзноса = 0;
    КонецЕсли;

    // ---------------------------------------------------------------
    // 5. Формируем итоговое сообщение и выводим его пользователю.
    // ---------------------------------------------------------------
    ТекстСообщения = "Итоги расчёта за " + Формат(ДатаНачала, "ДФ=ММММ ГГГГ") + ":\n" +
                     "  Сумма начислений (РегистраторЗарплаты) = " + Формат(СуммаНачисления, "ЧГ=Число;ЧД=2") + "\n" +
                     "  Сумма налогов (РегистраторНалогов)      = " + Формат(СуммаНалога, "ЧГ=Число;ЧД=2") + "\n" +
                     "  Сумма страховых взносов (РегистраторВзносов) = " + Формат(СуммаВзноса, "ЧГ=Число;ЧД=2");
    Сообщить(ТекстСообщения);
КонецПроцедуры

