```1C
// ------------------------------------------------------------
// Проверка табеля учёта рабочего времени за выбранный период
// ------------------------------------------------------------
// Типичные ошибки, которые обнаруживает скрипт:
// 1) Дата строки находится вне границ расчётного периода –
//    исправление: в форме табеля выбрать правильный период или
//    скорректировать даты в строках.
// 2) Сумма отработанных часов за неделю отличается от нормы >5% –
//    исправление: проверить корректность ввода часов, учесть
//    выходные/отпуска, скорректировать записи.
// 3) Указана надбавка, но не заполнено поле "Основание надбавки" –
//    исправление: в строке табеля заполнить основание (документ,
//    приказ и т.п.).
// ------------------------------------------------------------

Функция ПроверитьТабель(ДатаНачала, ДатаОкончания) Экспорт
    // Параметры:
    //   ДатаНачала, ДатаОкончания – границы проверяемого расчётного периода.
    // Возвращаемое значение – массив объектов ОшибкаТабеля.

    // --------------------------------------------------------
    // 1. Получаем набор строк табеля за указанный период.
    // --------------------------------------------------------
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |   ТТ.Дата КАК Дата,
        |   ТТ.ОтработаноЧасов КАК Часы,
        |   ТТ.Надбавка КАК Надбавка,
        |   ТТ.ОснованиеНадбавки КАК ОснованиеНадбавки,
        |   ТТ.Работник КАК Работник
        |ИЗ
        |   Документ.ТабельУчетаРабочегоВремени.ТабличнаяЧасть ТТ
        |ГДЕ
        |   ТТ.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания";
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    // --------------------------------------------------------
    // 2. Инициализируем вспомогательные структуры.
    // --------------------------------------------------------
    Ошибки = Новый Массив();
    // Словарь: Ключ = Номер недели (Год-Неделя), Значение = Сумма часов.
    ЧасыПоНеделям = Новый Соответствие();
    НормаЧасовВНеделю = 40; // нормативный показатель
    ПорогОтклонения = 0.05; // 5 %

    Пока Выборка.Следующий() Цикл
        // 2.1. Проверка диапазона даты.
        Если Выборка.Дата < ДатаНачала ИЛИ Выборка.Дата > ДатаОкончания Тогда
            Ошибка = Новый Структура(
                "Дата, Ошибка, Описание",
                Выборка.Дата,
                "ДатаВнеПериода",
                "Дата строки находится за пределами выбранного расчётного периода");
            Ошибки.Добавить(Ошибка);
        КонецЕсли;

        // 2.2. Накопление часов по неделям.
        НомерНедели = Формат(Выборка.Дата, "ГГГГ-ww"); // год-номер недели
        Если ЧасыПоНеделям.СодержитКлюч(НомерНедели) Тогда
            ЧасыПоНеделям[НомерНедели] = ЧасыПоНеделям[НомерНедели] + Выборка.Часы;
        Иначе
            ЧасыПоНеделям[НомерНедели] = Выборка.Часы;
        КонецЕсли;

        // 2.3. Проверка наличия основания надбавки.
        Если Выборка.Надбавка <> Неопределено И Выборка.ОснованиеНадбавки = Неопределено Тогда
            Ошибка = Новый Структура(
                "Дата, Ошибка, Описание",
                Выборка.Дата,
                "ОтсутствуетОснованиеНадбавки",
                "Для строки с надбавкой не указано основание надбавки");
            Ошибки.Добавить(Ошибка);
        КонецЕсли;
    КонецЦикла;

    // --------------------------------------------------------
    // 3. Анализ отклонений от нормы по каждой неделе.
    // --------------------------------------------------------
    Для Каждого НомерНедели Из ЧасыПоНеделям Ключи Цикл
        СуммаЧасов = ЧасыПоНеделям[НомерНедели];
        Отклонение = (СуммаЧасов - НормаЧасовВНеделю) / НормаЧасовВНеделю;
        Если АбсолютноеЗначение(Отклонение) > ПорогОтклонения Тогда
            // Формируем произвольную дату – первый день недели, чтобы
            // пользователь видел, к какой неделе относится ошибка.
            ДатаДляОшибки = НачалоНедели(НомерНедели);
            ТекстОшибки = "Отклонение от нормы более 5%";
            Описание = СтрШаблон("Сумма отработанных часов за неделю %1 = %2 ч, норма = %3 ч.",
                                 НомерНедели, СуммаЧасов, НормаЧасовВНеделю);
            Ошибка = Новый Структура(
                "Дата, Ошибка, Описание",
                ДатаДляОшибки,
                "ОтклонениеОтНормы",
                Описание);
            Ошибки.Добавить(Ошибка);
        КонецЕсли;
    КонецЦикла;

    Возврат Ошибки;
КонецФункции

// ------------------------------------------------------------
// Вспомогательная функция: возвращает дату начала недели по коду "ГГГГ-ww".
// ------------------------------------------------------------
Функция НачалоНедели(КодНедели) Экспорт
    // Пример кода: "2023-15" → первая дата 15‑й недели 2023‑го года.
    Год = Число(Лев(КодНедели, 4));
    НомерНедели = Число(Сред(КодНедели, 6, 2));
    // 1‑й день недели – понедельник.
    Дата = Дата(Год, 1, 1);
    // Сдвигаем к нужной неделе.
    Дата = Дата + (НомерНедели - 1) * 7;
    // Корректируем до понедельника.
    Пока ДеньНедели(Дата) <> 1 Цикл
        Дата = Дата - 1;
    КонецЦикла;
    Возврат Дата;
КонецФункции
```

