//===================================================================

&НаКлиенте
Процедура ПриОткрытии() Экспорт
    // Добавляем кнопку «Выполнить» в форму обработки
    КнопкаВыполнить = ЭлементыФормы.ДобавитьКнопку("Выполнить", "Выполнить");
    КнопкаВыполнить.Подсказка = "Создать тестовые записи в справочниках";
КонецПроцедуры

&НаСервере
Процедура Выполнить() Экспорт
    // Отключаем автосохранение, чтобы ускорить запись большого количества данных
    НачатьТранзакцию();
    Попытка
        // 1. Создаём должности
        Должности = Новый Массив();
        Должности.Добавить(Новый Структура("Код,Наименование", "DEV", "Разработчик"));
        Должности.Добавить(Новый Структура("Код,Наименование", "ANL", "Аналитик"));
        Должности.Добавить(Новый Структура("Код,Наименование", "MGR", "Менеджер"));
        Для Каждого Должность Из Должности Цикл
            Если Не Справочники.Должности.НайтиПоКоду(Должность.Код) Тогда
                НовыйЭлемент = Справочники.Должности.СоздатьЭлемент();
                НовыйЭлемент.Код = Должность.Код;
                НовыйЭлемент.Наименование = Должность.Наименование;
                НовыйЭлемент.Записать();
            КонецЕсли;
        КонецЦикла;

        // 2. Создаём подразделения
        Подразделения = Новый Массив();
        Подразделения.Добавить(Новый Структура("Код,Наименование", "IT", "ИТ‑отдел"));
        Подразделения.Добавить(Новый Структура("Код,Наименование", "FIN", "Финансовый отдел"));
        Для Каждого Подразделение Из Подразделения Цикл
            Если Не Справочники.Подразделения.НайтиПоКоду(Подразделение.Код) Тогда
                НовыйЭлемент = Справочники.Подразделения.СоздатьЭлемент();
                НовыйЭлемент.Код = Подразделение.Код;
                НовыйЭлемент.Наименование = Подразделение.Наименование;
                НовыйЭлемент.Записать();
            КонецЕсли;
        КонецЦикла;

        // 3. Создаём ставки (тарифные ставки)
        Ставки = Новый Массив();
        Ставки.Добавить(Новый Структура("Код,Наименование,Тариф", "ST1", "Ставка 1", 1500));
        Ставки.Добавить(Новый Структура("Код,Наименование,Тариф", "ST2", "Ставка 2", 2000));
        Для Каждого Ставка Из Ставки Цикл
            Если Не Справочники.Ставки.НайтиПоКоду(Ставка.Код) Тогда
                НовыйЭлемент = Справочники.Ставки.СоздатьЭлемент();
                НовыйЭлемент.Код = Ставка.Код;
                НовыйЭлемент.Наименование = Ставка.Наименование;
                НовыйЭлемент.Тариф = Ставка.Тариф; // поле «Тариф» – тип Число
                НовыйЭлемент.Записать();
            КонецЕсли;
        КонецЦикла;

        // 4. Создаём надбавки (коэффициенты)
        Надбавки = Новый Массив();
        Надбавки.Добавить(Новый Структура("Код,Наименование,Коэффициент", "ND1", "Надбавка 1", 1.1));
        Надбавки.Добавить(Новый Структура("Код,Наименование,Коэффициент", "ND2", "Надбавка 2", 1.25));
        Для Каждого Надбавка Из Надбавки Цикл
            Если Не Справочники.Надбавки.НайтиПоКоду(Надбавка.Код) Тогда
                НовыйЭлемент = Справочники.Надбавки.СоздатьЭлемент();
                НовыйЭлемент.Код = Надбавка.Код;
                НовыйЭлемент.Наименование = Надбавка.Наименование;
                НовыйЭлемент.Коэффициент = Надбавка.Коэффициент; // тип Число
                НовыйЭлемент.Записать();
            КонецЕсли;
        КонецЦикла;

        // 5. Создаём сотрудников
        Сотрудники = Новый Массив();
        // Примерные данные: ФИО, ТабельныйНомер, ДатаПриёма, Должность, Подразделение, Ставка, Надбавка
        Сотрудники.Добавить(Новый Структура(
            "ФИО,ТабельныйНомер,ДатаПриёма,Должность,Подразделение,Ставка,Надбавка",
            "Иванов Иван Иванович", "001", Дата(2023,01,15), "DEV", "IT", "ST1", "ND1"));
        Сотрудники.Добавить(Новый Структура(
            "ФИО,ТабельныйНомер,ДатаПриёма,Должность,Подразделение,Ставка,Надбавка",
            "Петров Петр Петрович", "002", Дата(2022,07,01), "ANL", "FIN", "ST2", "ND2"));
        Сотрудники.Добавить(Новый Структура(
            "ФИО,ТабельныйНомер,ДатаПриёма,Должность,Подразделение,Ставка,Надбавка",
            "Сидорова Мария Сергеевна", "003", Дата(2024,03,20), "MGR", "IT", "ST2", "ND1"));

        Для Каждого Сотрудник Из Сотрудники Цикл
            // Проверяем, нет ли уже сотрудника с таким табельным номером
            Если Не Справочники.Сотрудники.НайтиПоКоду(Сотрудник.ТабельныйНомер) Тогда
                НовыйЭлемент = Справочники.Сотрудники.СоздатьЭлемент();
                // Обязательные реквизиты
                НовыйЭлемент.Код = Сотрудник.ТабельныйНомер; // Табельный номер – код справочника
                НовыйЭлемент.ФИО = Сотрудник.ФИО;
                НовыйЭлемент.ДатаПриёма = Сотрудник.ДатаПриёма;
                // Ссылка на справочники – ищем по коду
                НовыйЭлемент.Должность = Справочники.Должности.НайтиПоКоду(Сотрудник.Должность);
                НовыйЭлемент.Подразделение = Справочники.Подразделения.НайтиПоКоду(Сотрудник.Подразделение);
                НовыйЭлемент.Ставка = Справочники.Ставки.НайтиПоКоду(Сотрудник.Ставка);
                НовыйЭлемент.Надбавка = Справочники.Надбавки.НайтиПоКоду(Сотрудник.Надбавка);
                // Необязательные реквизиты (можно задать произвольно)
                НовыйЭлемент.ДатаРождения = Дата(1990,01,01);
                НовыйЭлемент.Пол = "М"; // "М" – мужской, "Ж" – женский
                // Сохраняем запись
                НовыйЭлемент.Записать();
            КонецЕсли;
        КонецЦикла;

        ЗафиксироватьТранзакцию();
        Сообщить("Массовое заполнение справочников выполнено успешно.");
    Исключение
        // Откатываем все изменения при любой ошибке
        ОтменитьТранзакцию();
        Сообщить("Ошибка при заполнении справочников: " + ОписаниеОшибки());
    КонецПопытки;
КонецПроцедуры

//===================================================================
//  Пояснение к полям справочников
//===================================================================
//  Сотрудники
//      • Код (ТабельныйНомер) – **обязательное** поле, уникальный идентификатор.
//      • ФИО – **обязательное** строковое поле.
//      • ДатаПриёма – **обязательное** дата.
//      • Должность, Подразделение, Ставка, Надбавка – ссылки на соответствующие справочники, **обязательные**.
//      • ДатаРождения, Пол, Адрес, Телефон и т.п. – **необязательные** (можно оставить пустыми).
//
//  Должности, Подразделения, Ставки, Надбавки
//      • Код – **обязательное** уникальное строковое значение (можно использовать
//        сокращения, например "DEV", "IT").
//      • Наименование – **обязательное** строковое поле, отображаемое пользователю.
//      • Ставки: дополнительный реквизит «Тариф» – числовой, обязательный для расчёта.
//      • Надбавки: дополнительный реквизит «Коэффициент» – числовой, обязательный.
//
//  Если в конфигурации добавлены пользовательские реквизиты, они будут считаться
//  обязательными только в том случае, если в их свойствах указано "Обязательное".
//===================================================================

assignment.description:
**Цель задания** – закрепить знания об основных типах объектов конфигурации 1С:Зарплата и управление персоналом 3.1 и научиться быстро находить их в Конфигураторе, а также понять их взаимосвязи.

**Контекст** – вы разрабатываете собственный проект в 1С и уже знакомы с конфигуратором. В этом задании вы применяете полученные теоретические сведения к своей конфигурации.

**Что нужно сделать**:
1. Открыть Конфигуратор в режиме «Конфигурация».
2. Найти и открыть следующие объекты:
   - Справочник **«Сотрудники»**;
   - Регистры накопления **«Начисления»** и **«Удержания»** (или их аналоги в вашей конфигурации);
   - Документ **«Начисление зарплаты»**;
   - Обработку **«Расчёт зарплаты»**;
   - Отчёт **«Ведомость начислений»**.
3. Для каждого объекта написать короткое описание (2‑3 предложения) его назначения и указать, какие другие объекты он использует (например, какие справочники задействует документ, в какие регистры пишет и т.п.).
4. С помощью интерактивной карты конфигурации отобразить взаимосвязи между найденными объектами (связи «Справочник → Документ», «Документ → Регистры», «Обработка → Документ/Отчёт»). Сделать скриншот карты, где видны все требуемые связи.
5. Сохранить скриншоты и текстовые описания в один документ (Markdown, PDF или DOCX). В конце документа указать ФИО, группу и дату выполнения.

**Обязательные элементы итогового файла**:
- Текстовое описание каждого из пяти объектов (структурированный список);
- Скриншот интерактивной карты с видимыми связями;
- Блок с ФИО, группой и датой;
- Файл не более 2 МБ, название `ФИО_Группа_Урок1.<расширение>`.

