//===================================================================
// 1С:Предприятие 8.3
// Модуль обработки "ИмпортВидовОтпусков"
//===================================================================
// Описание: массовый импорт новых видов отпусков/больничных из Excel.
//           • проверяется уникальность кода в справочнике "Виды отпусков";
//           • при конфликте формируется список ошибок;
//           • после завершения импорта выводится простой отчёт (текстовый файл).
//===================================================================

#Область ПрограммныйИнтерфейс

// ---------------------------------------------------------------
// Основная процедура, вызываемая пользователем.
// Параметр "ПутьКФайлу" – полное имя Excel‑файла.
// ---------------------------------------------------------------
Процедура ИмпортироватьВидыОтпусков(ПутьКФайлу)
    // 1. Открываем Excel и читаем данные
    ДанныеИзExcel = ПрочитатьТаблицуИзExcel(ПутьКФайлу);
    Если ДанныеИзExcel = Неопределено Тогда
        Сообщить("Не удалось открыть файл " + ПутьКФайлу, СтатусСообщения.Важное);
        Возврат;
    КонецЕсли;

    // 2. Подготовим массив для ошибок
    Ошибки = Новый Массив();

    // 3. Обходим строки таблицы
    Для Каждого СтрокаТаблицы Из ДанныеИзExcel Цикл
        // Ожидаем столбцы: Код, Наименование, Периодичность, ПривязкаКДолжностям
        Код          = СтрокаТаблицы["Код"];
        Наименование = СтрокаТаблицы["Наименование"];
        Периодичность = СтрокаТаблицы["Периодичность"];
        ПривязкаКДолжностям = СтрокаТаблицы["ПривязкаКДолжностям"];

        // 3.1 Проверка обязательных полей
        Если ПустаяСтрока(Код) ИЛИ ПустаяСтрока(Наименование) Тогда
            Ошибки.Добавить("Строка " + СтрокаТаблицы.НомерСтроки + ": пустой код или наименование.");
            Продолжить;
        КонецЕсли;

        // 3.2 Проверка уникальности кода в справочнике "Виды отпусков"
        Если СуществуетВидОтпуска(Код) Тогда
            Ошибки.Добавить("Строка " + СтрокаТаблицы.НомерСтроки + ": код '" + Код + "' уже существует.");
            Продолжить;
        КонецЕсли;

        // 3.3 Создаём запись в справочнике
        НовыйВид = Справочники.ВидыОтпусков.СоздатьЭлемент();
        НовыйВид.Код          = Код;
        НовыйВид.Наименование  = Наименование;
        // Параметры настройки (примерные реквизиты, могут отличаться в конфигурации)
        Если Не ПустаяСтрока(Периодичность) Тогда
            НовыйВид.Периодичность = Периодичность; // тип строка/перечисление
        КонецЕсли;
        Если Не ПустаяСтрока(ПривязкаКДолжностям) Тогда
            // Предполагаем, что в справочнике "Должности" есть реквизит "Код"
            Должность = Справочники.Должности.НайтиПоКоду(ПривязкаКДолжностям);
            Если Должность <> Неопределено Тогда
                НовыйВид.ПривязкаКДолжностям = Должность;
            Иначе
                Ошибки.Добавить("Строка " + СтрокаТаблицы.НомерСтроки + ": не найдено должность с кодом '" + ПривязкаКДолжностям + "'.");
            КонецЕсли;
        КонецЕсли;

        // Сохраняем запись
        Попытка
            НовыйВид.Записать();
        Исключение
            Ошибки.Добавить("Строка " + СтрокаТаблицы.НомерСтроки + ": ошибка записи – " + ОписаниеОшибки());
        КонецПопытки;
    КонецЦикла;

    // 4. Формируем отчёт об ошибках
    СформироватьОтчётОбОшибках(Ошибки);

    // 5. Информируем пользователя о результате
    Если Ошибки.Количество() = 0 Тогда
        Сообщить("Импорт завершён успешно. Добавлено " + ДанныеИзExcel.Количество() + " записей.", СтатусСообщения.Информация);
    Иначе
        Сообщить("Импорт завершён с ошибками. Смотрите файл отчёта.", СтатусСообщения.Важное);
    КонецЕсли;
КонецПроцедуры

// ---------------------------------------------------------------
// Чтение данных из Excel через COM‑объект.
// Возвращает массив строк, каждая строка – это Структура с полями
// "Код", "Наименование", "Периодичность", "ПривязкаКДолжностям".
// ---------------------------------------------------------------
Функция ПрочитатьТаблицуИзExcel(ПутьКФайлу) Экспорт
    Попытка
        Excel = Новый COMObject("Excel.Application");
        Книга = Excel.Workbooks.Open(ПутьКФайлу);
        Лист  = Книга.Worksheets(1); // первая таблица
        ПоследняяСтрока = Лист.UsedRange.Rows.Count;
        ПоследнийСтолбец = Лист.UsedRange.Columns.Count;

        // Предполагаем, что первая строка – заголовки
        Заголовки = Новый Соответствие();
        Для i = 1 По ПоследнийСтолбец Цикл
            Заголовок = СтрЗнач(Лист.Cells(1, i).Value2);
            Заголовки[Заголовок] = i;
        КонецЦикла;

        Результат = Новый Массив();
        Для НомерСтроки = 2 По ПоследняяСтрока Цикл
            Строка = Новый Структура();
            Строка.Вставить("НомерСтроки", НомерСтроки);
            // Читаем только интересующие столбцы, если они есть в заголовке
            Если Заголовки.СодержитKey("Код") Тогда
                Строка.Вставить("Код", СтрЗнач(Лист.Cells(НомерСтроки, Заголовки["Код"]).Value2));
            КонецЕсли;
            Если Заголовки.СодержитKey("Наименование") Тогда
                Строка.Вставить("Наименование", СтрЗнач(Лист.Cells(НомерСтроки, Заголовки["Наименование"]).Value2));
            КонецЕсли;
            Если Заголовки.СодержитKey("Периодичность") Тогда
                Строка.Вставить("Периодичность", СтрЗнач(Лист.Cells(НомерСтроки, Заголовки["Периодичность"]).Value2));
            КонецЕсли;
            Если Заголовки.СодержитKey("ПривязкаКДолжностям") Тогда
                Строка.Вставить("ПривязкаКДолжностям", СтрЗнач(Лист.Cells(НомерСтроки, Заголовки["ПривязкаКДолжностям"]).Value2));
            КонецЕсли;
            Результат.Добавить(Строка);
        КонецЦикла;

        // Закрываем Excel без сохранения
        Книга.Close(False);
        Excel.Quit();
        ОсвободитьCOMObject(Excel);
        Возврат Результат;
    Исключение
        // При любой ошибке возвращаем Неопределено и выводим сообщение в журнал
        Сообщить("Ошибка при работе с Excel: " + ОписаниеОшибки(), СтатусСообщения.Важное);
        Возврат Неопределено;
    КонецПопытки;
КонецФункции

// ---------------------------------------------------------------
// Проверка наличия кода в справочнике "Виды отпусков".
// ---------------------------------------------------------------
Функция СуществуетВидОтпуска(Код) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |   ВидыОтпусков.Ссылка
        |ИЗ
        |   Справочник.ВидыОтпусков КАК ВидыОтпусков
        |ГДЕ
        |   ВидыОтпусков.Код = &Код";
    Запрос.УстановитьПараметр("Код", Код);
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Возврат Выборка.Следующий();
КонецФункции

// ---------------------------------------------------------------
// Формирование простого текстового отчёта об ошибках.
// Файл сохраняется в папке "ВременныеФайлы" текущей информационной базы.
// ---------------------------------------------------------------
Процедура СформироватьОтчётОбОшибках(Ошибки) Экспорт
    Если Ошибки = Неопределено ИЛИ Ошибки.Количество() = 0 Тогда
        Возврат;
    КонецЕсли;

    ПутьОтчёта = ПолучитьВременныйФайл("Отчёт_Импорт_ВидыОтпусков_" + Формат(ТекущаяДата(), "ДФ=yyyyMMdd_hhmmss") + ".txt");
    ТекстовыйДокумент = Новый ТекстовыйДокумент;
    ТекстовыйДокумент.ЗаписатьСтроку("Отчёт об ошибках при импорте видов отпусков/больничных");
    ТекстовыйДокумент.ЗаписатьСтроку("Дата: " + Формат(ТекущаяДата(), "ДФ=dd.MM.yyyy hh:nn:ss"));
    ТекстовыйДокумент.ЗаписатьСтроку("------------------------------------------------------------");
    Для Каждого Строка Ошибки Цикл
        ТекстовыйДокумент.ЗаписатьСтроку(Строка);
    КонецЦикла;
    ТекстовыйДокумент.ЗаписатьСтроку("------------------------------------------------------------");
    ТекстовыйДокумент.ЗаписатьСтроку("Всего ошибок: " + Ошибки.Количество());
    ТекстовыйДокумент.Записать(ПутьОтчёта);

    // Открываем файл в блокноте (по желанию)
    Попытка
        ЗапуститьПриложение("notepad.exe", ПутьОтчёта);
    Исключение
        // Если не удалось открыть – просто сообщаем путь
        Сообщить("Отчёт сохранён в " + ПутьОтчёта, СтатусСообщения.Информация);
    КонецПопытки;
КонецПроцедуры

#КонецОбласти

//===================================================================
// Как использовать:
// 1. Сохраните обработку в конфигурации (ОбщиеМодули → Обработки).
// 2. Вызовите из пользовательского интерфейса, передав путь к файлу:
//    ИмпортироватьВидыОтпусков("C:\\Temp\\ВидыОтпусков.xlsx");
//===================================================================

assignment.description:
**Цель задания** – продемонстрировать умение настраивать расчёт отпускных и больничных (ставка отпускного, коэффициент больничного, налоговые/страховые ставки, правила округления, периодичность выплат, период расчёта) в вашем собственном payroll‑модуле (1С:Зарплата и управление персоналом или аналог) и проверить их влияние.

**Контекст** – в рамках проектной деятельности вы разрабатываете/поддерживаете модуль расчёта заработной платы. Все изменения необходимо задокументировать в одном отчёте.

**Обязательные шаги**:
1. Описать текущие параметры расчёта в таблице «Исходные параметры». 
2. Сформулировать новые значения (пример): ставка отпускного = 120 %, коэффициент больничного = 1,25, НДФЛ = 13 %, ПФР = 22 %, ФОМС = 5,1 %, правило округления = «в большую сторону до 0,01», периодичность = «ежемесячно», период расчёта = 2024 г.
3. В системе изменить параметры, создать новую версию настроек с комментариями (например, «Обновлены ставки отпускного и больничного, правило округления»).
4. Сформировать тестовый сценарий: выбрать одного сотрудника, задать базовую зарплату Z, рассчитать отпускные и больничные вручную по формулам из теории и сравнить с результатами регистров «Расчёт зарплаты» и «Выплаты» после изменения.
5. В отчёте включить:
   - скриншоты (или PlantUML‑коды) формы «Настройки расчёта» до и после изменения;
   - таблицы «Исходные параметры» и «Новые параметры»;
   - описание тестового сценария (данные сотрудника, даты, количество дней);
   - расчётные формулы и таблицу сравнения ожидаемой и фактической выплаты;
   - анализ расхождений и выводы о корректности настроек;
   - ссылку на коммит/ветку репозитория, где внесены изменения.
6. Сохранить всё в один файл (Markdown, PDF или DOCX).

content_blocks.code:
// ------------------------------------------------------------
// 1С:Предприятие 8 – запросы для проверки записей,
// сформированных приказами о отпуске и больничном листе.
// ------------------------------------------------------------

// Параметры запроса (заполняются в момент выполнения)
// ------------------------------------------------------------
// Параметр "Сотрудник" – ссылка на справочник "Сотрудники".
// Если параметр не задан, запрос вернёт данные по всем сотрудникам.
// Параметр "ДатаНачалаПериода" – первая дата текущего месяца.
// Параметр "ДатаОкончанияПериода" – последняя дата текущего месяца.

// ------------------------------------------------------------
// 1. Запрос к регистру накопления "Отпускные"
// ------------------------------------------------------------
ЗапросОтпускные = Новый Запрос;
ЗапросОтпускные.Текст = 
"""
ВЫБРАТЬ
    // Ссылка на запись в регистре (можно использовать как СсылкаНаПриказ)
    Отпускные.Ссылка КАК СсылкаНаПриказ,
    // Сотрудник – ссылка на справочник "Сотрудники"
    Отпускные.Сотрудник КАК Сотрудник,
    // Дата начала отпуска (поле регистра)
    Отпускные.ДатаНачала КАК ДатаНачала,
    // Дата окончания отпуска
    Отпускные.ДатаОкончания КАК ДатаОкончания,
    // Количество дней отпуска (рассчитано в регистре)
    Отпускные.КоличествоДней КАК КоличествоДней,
    // Сумма выплаты за отпуск
    Отпускные.СуммаВыплаты КАК СуммаВыплаты
ИЗ
    РегистрНакопления.Отпускные КАК Отпускные
ГДЕ
    // Фильтр по дате создания приказа (поле "Дата" – дата записи в регистре)
    Отпускные.Дата МЕЖДУ &ДатаНачалаПериода И &ДатаОкончанияПериода
    // При необходимости – фильтр по конкретному сотруднику
    И ( &Сотрудник = НЕОПРЕДЕЛЕНО ИЛИ Отпускные.Сотрудник = &Сотрудник )
""";

// Установка параметров (пример – текущий месяц и конкретный сотрудник)
ЗапросОтпускные.УстановитьПараметр("ДатаНачалаПериода", НачалоМесяца(ТекущаяДата()));
ЗапросОтпускные.УстановитьПараметр("ДатаОкончанияПериода", КонецМесяца(ТекущаяДата()));
// Если нужен конкретный сотрудник – передать ссылку, иначе НЕОПРЕДЕЛЕНО
ЗапросОтпускные.УстановитьПараметр("Сотрудник", НЕОПРЕДЕЛЕНО);

// Выполнение запроса (в конфигураторе – через метод Выполнить(),
// в пользовательском режиме – через объект "Запрос" в обработке/отчете)
РезультатОтпускные = ЗапросОтпускные.Выполнить();
ВыборкаОтпускные = РезультатОтпускные.Выбрать();

// ------------------------------------------------------------
// 2. Запрос к регистру накопления "БольничныеЛисты"
// ------------------------------------------------------------
ЗапросБольничные = Новый Запрос;
ЗапросБольничные.Текст = 
"""
ВЫБРАТЬ
    БольничныеЛисты.Ссылка КАК СсылкаНаПриказ,
    БольничныеЛисты.Сотрудник КАК Сотрудник,
    БольничныеЛисты.ДатаНачала КАК ДатаНачала,
    БольничныеЛисты.ДатаОкончания КАК ДатаОкончания,
    БольничныеЛисты.КоличествоДней КАК КоличествоДней,
    БольничныеЛисты.СуммаВыплаты КАК СуммаВыплаты
ИЗ
    РегистрНакопления.БольничныеЛисты КАК БольничныеЛисты
ГДЕ
    БольничныеЛисты.Дата МЕЖДУ &ДатаНачалаПериода И &ДатаОкончанияПериода
    И ( &Сотрудник = НЕОПРЕДЕЛЕНО ИЛИ БольничныеЛисты.Сотрудник = &Сотрудник )
""";

ЗапросБольничные.УстановитьПараметр("ДатаНачалаПериода", НачалоМесяца(ТекущаяДата()));
ЗапросБольничные.УстановитьПараметр("ДатаОкончанияПериода", КонецМесяца(ТекущаяДата()));
ЗапросБольничные.УстановитьПараметр("Сотрудник", НЕОПРЕДЕЛЕНО);

РезультатБольничные = ЗапросБольничные.Выполнить();
ВыборкаБольничные = РезультатБольничные.Выбрать();

// ------------------------------------------------------------
// Пример вывода (таблица) для обоих запросов
// ------------------------------------------------------------
/*
+----------------+----------------+----------------+----------------+----------------+----------------+
| Сотрудник      | ДатаНачала     | ДатаОкончания  | КоличествоДней | СсылкаНаПриказ | СуммаВыплаты   |
+----------------+----------------+----------------+----------------+----------------+----------------+
| Иванов И.И.    | 01.06.2024     | 10.06.2024     | 10             | 0x00123         | 15000          |
| Петров П.П.    | 15.06.2024     | 20.06.2024     | 5              | 0x00124         | 7500           |
+----------------+----------------+----------------+----------------+----------------+----------------+
*/

// ------------------------------------------------------------
// Как интерпретировать результаты
// ------------------------------------------------------------
// • Если запись присутствует – значит, приказ (отпуск/больничный) был
//   успешно проведён и в соответствующий регистр внесена запись.
// • Поле "СсылкаНаПриказ" хранит ссылку на документ‑приказ, по которой
//   можно открыть оригинал (например, через СсылкаНаПриказ.ПолучитьОбъект()).
// • Если запрос вернул пустой набор (нет строк) – возможны причины:
//     1) За выбранный период и/или для указанного сотрудника нет приказов.
//     2) Приказ был создан, но не проведён (тогда запись в регистре не появляется).
//     3) Ошибка в параметрах фильтра (неправильный диапазон дат).
//   В таком случае проверьте журнал регистрации и статус документов.

// ------------------------------------------------------------
// Как выполнить запрос в режиме "Конфигуратор"
// ------------------------------------------------------------
// 1. Откройте конфигуратор и перейдите в нужный объект (Общая обработка,
//    Отчет, Публичный метод модуля и т.п.).
// 2. Вставьте код выше в обработчик (например, ПриНажатииКнопки).
// 3. При необходимости замените параметры (Сотрудник) на конкретную ссылку:
//    ЗапросОтпускные.УстановитьПараметр("Сотрудник", Справочники.Сотрудники.НайтиПоНаименованию("Иванов И.И."));
// 4. Запустите обработку (F5) – результат будет доступен в переменной
//    ВыборкаОтпускные/ВыборкаБольничные. Вы можете вывести его в табличный
//    документ или в окно сообщения.

// ------------------------------------------------------------
// Как выполнить запрос в режиме "Пользователь"
// ------------------------------------------------------------
// 1. Создайте пользовательскую обработку (или форму отчёта) в режиме
//    «Конфигуратор → Открыть в режиме пользователя».
// 2. Добавьте кнопку «Показать записи» и привяжите к ней обработчик.
// 3. В обработчике разместите тот же код (без создания нового объекта
//    Запрос – можно использовать уже объявленный в модуле). Пример:
//
//   Процедура КнопкаПоказатьНажатие(Кнопка)
//   {
//       // Параметры берём из формы (например, поле ввода ФИО)
//       Сотрудник = Справочники.Сотрудники.НайтиПоНаименованию(ЭлементыФормы.ФИО.Значение);
//       ЗапросОтпускные.УстановитьПараметр("Сотрудник", Сотрудник);
//       // … аналогично для больничных …
//       // Выполняем запрос и выводим результат в ТабличныйДокумент
//       ТабДок = Новый ТабличныйДокумент;
//       ТабДок.Вывести(ВыборкаОтпускные);
//       ТабДок.Отобразить();
//   }
//
// 4. Пользователь вводит ФИО (или оставляет поле пустым) и нажимает кнопку –
//    получит таблицу с данными за текущий месяц.

// ------------------------------------------------------------
// Конец примера
// ------------------------------------------------------------

//===================================================================
//  Обработка «Проверка начислений отпускных и больничных»
//  Задача: вывести в табличный документ (ТабличныйДокумент) список всех
//  начислений по коду выплаты «Отпускные» и «Больничные» за выбранный период.
//===================================================================

//===================================================================
//  1. Описание структуры обработки
//===================================================================
//  • Форма обработки содержит два поля ввода даты (ДатаНачала, ДатаКонца)
//    и кнопку «Сформировать». При нажатии на кнопку вызывается процедура
//    СформироватьОтчет().
//  • В процедуре формируется запрос к регистрам «Расчёт зарплаты» и
//    «Выплаты», происходит фильтрация по дате и коду выплаты, суммирование
//    по сотруднику и виду выплаты.
//  • Результат помещается в объект ТабличныйДокумент и открывается
//    пользователю.
//===================================================================

//===================================================================
//  2. Модуль формы обработки (МодульФормы)
//===================================================================

&AtClient
Процедура ПриОткрытии()
    // Устанавливаем текущий месяц как диапазон по умолчанию
    ДатаНачала = НачалоМесяца(ТекущаяДата());
    ДатаКонца = КонецМесяца(ТекущаяДата());
КонецПроцедуры

&AtClient
Процедура СформироватьОтчет(Кнопка)
    // ---------------------------------------------------------------
    // 2.1. Проверка корректности введённых дат
    // ---------------------------------------------------------------
    Если ДатаНачала > ДатаКонца Тогда
        Предупреждение("Дата начала не может быть позже даты конца.");
        Возврат;
    КонецЕсли;

    // ---------------------------------------------------------------
    // 2.2. Формируем запрос к регистрам
    // ---------------------------------------------------------------
    ТекстЗапроса = 
        "ВЫБРАТЬ
" +
        "    Регистратор.Дата КАК Дата,
" +
        "    Регистратор.Сотрудник КАК Сотрудник,
" +
        "    Регистратор.ВидВыплаты КАК ВидВыплаты,
" +
        "    СУММА(Регистратор.Сумма) КАК Сумма
" +
        "ИЗ
" +
        "    РегистрРасчётЗарплаты.Регистратор КАК Регистратор
" +
        "ГДЕ
" +
        "    Регистратор.Дата МЕЖДУ &ДатаНачала И &ДатаКонца
" +
        "    И Регистратор.ВидВыплаты В (&КодыВыплат)
" +
        "СГРУППИРОВАТЬ ПО
" +
        "    Регистратор.Дата,
" +
        "    Регистратор.Сотрудник,
" +
        "    Регистратор.ВидВыплаты";

    Запрос = Новый Запрос(ТекстЗапроса);
    // Параметры даты
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаКонца",   ДатаКонца);
    // Коды выплат, которые интересуют (можно добавить новые коды в массив)
    КодыВыплат = Новый Массив();
    КодыВыплат.Добавить("Отпускные");
    КодыВыплат.Добавить("Больничные");
    Запрос.УстановитьПараметр("КодыВыплат", КодыВыплат);

    // ---------------------------------------------------------------
    // 2.3. Выполняем запрос и получаем результат
    // ---------------------------------------------------------------
    Выборка = Запрос.Выполнить().Выбрать();

    // ---------------------------------------------------------------
    // 2.4. Формируем табличный документ
    // ---------------------------------------------------------------
    ТабДок = Новый ТабличныйДокумент();
    // Шапка таблицы
    ТабДок.Колонки.Добавить("Дата",      Тип("Дата"));
    ТабДок.Колонки.Добавить("Сотрудник", Тип("СправочникСсылка.Сотрудники"));
    ТабДок.Колонки.Добавить("Вид выплаты", Тип("Строка"));
    ТабДок.Колонки.Добавить("Сумма",     Тип("Число"));

    // Заполняем строки
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТабДок.Строки.Добавить();
        НоваяСтрока["Дата"]        = Выборка.Дата;
        НоваяСтрока["Сотрудник"]   = Выборка.Сотрудник;
        НоваяСтрока["Вид выплаты"] = Выборка.ВидВыплаты;
        НоваяСтрока["Сумма"]       = Выборка.Сумма;
    КонецЦикла;

    // ---------------------------------------------------------------
    // 2.5. Открываем табличный документ пользователю
    // ---------------------------------------------------------------
    ТабДок.Отобразить();
КонецПроцедуры

//===================================================================
//  3. Инструкция по запуску обработки в режиме отладки
//===================================================================
/*
1. Откройте конфигуратор 1С:Предприятие 8.
2. В дереве конфигурации выберите пункт «Обработки» → «Создать» →
   «Обработка». Дайте ей имя, например, "ПроверкаНачисленийОтпускных".
3. В открывшемся окне редактора кода замените автоматически
   сгенерированный модуль формы на код, приведённый выше (весь
   блок между //===================================================================).
4. Сохраните объект и выполните команду «Обновить конфигурацию».
5. Перейдите в режим «Тестирование» (или «Отладка»).
6. Запустите обработку через меню «Файл → Открыть обработку…».
7. На форме укажите нужный период (Дата начала и Дата конца) и нажмите
   кнопку «Сформировать». После выполнения откроется табличный документ
   со списком начислений по кодам «Отпускные» и «Больничные».
8. При необходимости можно поставить точку останова в процедуре
   СформироватьОтчет() и пошагово пройти её, наблюдая значения
   переменных в окне «Отладка». 
*/

//===================================================================
//  Конец обработки
//===================================================================

content_blocks.explanation:
Код представляет полностью готовую обработку, которую можно скопировать в конфигуратор, сохранить и запустить. В ней реализовано:
- ввод периода;
- запрос к регистру «Расчёт зарплаты» с фильтрацией по датам и кодам выплат;
- суммирование начислений;
- вывод результата в табличный документ.
Комментарии поясняют каждый логический блок, а в конце приведена пошаговая инструкция по запуску в режиме отладки.

