// ------------------------------------------------------------
// Пример: формирование отчёта «Отчёт по отпускам» и экспорт в Excel
// ------------------------------------------------------------
// Этот скрипт можно разместить, например, в обработке «HR_Отчёты»
// или вызвать из любой процедуры модуля объекта (Меню, Команда и т.п.).
// ------------------------------------------------------------

Процедура СформироватьОтчётПоОтпускамИЭкспорт()
    // 1. Создаём объект отчёта. Имя класса берётся из конфигурации
    //    (в конфигураторе он называется "ОтчётПоОтпускам").
    Отчёт = Новый ОтчётПоОтпускам();

    // ------------------------------------------------------------
    // 2. Задаём параметры фильтрации.
    // ------------------------------------------------------------
    // 2.1 Период – квартал. В 1С параметры периода обычно задаются
    //     через два свойства: ДатаНачала и ДатаОкончания.
    //     Здесь берём текущий год и формируем 1‑й квартал.
    ТекГод = ТекущаяДата().Год();
    ПериодНачало = НачалоГода(ТекГод) + 0;               // 01.01 текущего года
    ПериодОкончание = ПериодНачало + 89;                // 31.03 текущего года
    Отчёт.Параметры.ДатаНачала = ПериодНачало;
    Отчёт.Параметры.ДатаОкончания = ПериодОкончание;

    // 2.2 Подразделение – выбираем, например, отдел "Бухгалтерия".
    //     Предположим, что в справочнике "Подразделения" есть элемент
    //     с кодом "Бухгалтерия".
    Подразделение = Справочники.Подразделения.НайтиПоНаименованию("Бухгалтерия");
    Если Подразделение = Неопределено Тогда
        Предупреждение("Подразделение \"Бухгалтерия\" не найдено. Фильтр не будет применён.");
    Иначе
        Отчёт.Параметры.Подразделение = Подразделение.Ссылка;
    КонецЕсли;

    // ------------------------------------------------------------
    // 3. Добавляем группировку по виду отпуска.
    // ------------------------------------------------------------
    // В объекте отчёта есть коллекция "Группировки". Добавляем в неё
    // нужный реквизит – в данном случае "ВидОтпуска".
    Группировка = Отчёт.Группировки.Добавить();
    Группировка.Реквизит = "ВидОтпуска"; // поле из регистра расчётов
    // При желании можно задать порядок сортировки (по возрастанию/убыванию).
    Группировка.НаправлениеСортировки = НаправлениеСортировки.ПоВозрастанию;

    // ------------------------------------------------------------
    // 4. Формируем отчёт.
    // ------------------------------------------------------------
    // Метод "Сформировать" создаёт временный документ (табличный документ),
    // который далее можно вывести на экран, распечатать или экспортировать.
    Попытка
        Результат = Отчёт.Сформировать();
    Исключение
        // Если возникла ошибка (например, неверные параметры), выводим её.
        Сообщить("Ошибка формирования отчёта: " + ОписаниеОшибки());
        Возврат;
    КонецПопытки;

    // ------------------------------------------------------------
    // 5. Экспортируем полученный табличный документ в Excel.
    // ------------------------------------------------------------
    // Путь к файлу – в пользовательской папке "Документы".
    ПутьКФайлу = ПолучитьИмяФайлаВременногоХранилища("ОтчётПоОтпускам_" + Формат(ТекущаяДата(), "ДФ=yyyyMMdd_hhmmss") + ".xlsx");

    Попытка
        // Метод "ЭкспортВExcel" принимает путь к файлу.
        Результат.ЭкспортВExcel(ПутьКФайлу);
        Сообщить("Отчёт успешно экспортирован в файл: " + ПутьКФайлу);
        // При желании сразу открываем файл в Excel.
        ОткрытьВнешнююПрограмму(ПутьКФайлу);
    Исключение
        Сообщить("Не удалось экспортировать отчёт в Excel: " + ОписаниеОшибки());
    КонецПопытки;

КонецПроцедуры

// ------------------------------------------------------------
// Вспомогательная функция – получение пути к временной папке.
// ------------------------------------------------------------
Функция ПолучитьИмяФайлаВременногоХранилища(ИмяФайла)
    // Папка "Документы" текущего пользователя.
    ПапкаДокументы = ПолучитьКаталогВременныхФайлов(); // системный каталог temp
    Возврат ПапкаДокументы + "\\" + ИмяФайла;
КонецФункции

// ------------------------------------------------------------
// Как вызвать процедуру из пользовательского интерфейса?
// ------------------------------------------------------------
// 1) Добавьте кнопку на форму обработки.
// 2) В обработчике нажатия укажите: СформироватьОтчётПоОтпускамИЭкспорт();
// ------------------------------------------------------------
}

/**
 * Что делает каждый блок?
 * -----------------------
 * 1️⃣ Создаём объект отчёта – это как открыть шаблон отчёта в 1С.
 * 2️⃣ Указываем, за какой период и по какому подразделению нужны данные.
 *    HR‑специалисту обычно интересен квартал и конкретный отдел.
 * 3️⃣ Группируем строки отчёта по виду отпуска (отпуск без сохранения, 
 *    отпуск по уходу за ребёнком и т.д.) – так будет удобнее анализировать.
 * 4️⃣ Формируем отчёт – система собирает данные из регистров.
 * 5️⃣ Сохраняем полученный табличный документ в файл Excel, чтобы дальше
 *    работать в привычных таблицах, отправлять в бухгалтерию или печатать.
 */

/**
 * Примечание для разработчиков
 * ----------------------------
 * • Если в конфигурации названия реквизитов отличаются, замените "ВидОтпуска"
 *   на актуальное имя.
 * • При необходимости можно добавить несколько группировок, фильтры по
 *   сотрудникам, статусу согласования и т.п.
 * • Метод "ЭкспортВExcel" доступен, начиная с версии 8.3.10. Если у вас более
 *   старая платформа – используйте объект "ВнешняяОбработка" или COM‑интерфейс.
 */

//===================================================================
//  Обновление массовой ставки отпускного в справочнике "Виды отпусков"
//===================================================================
//  Описание задачи:
//  • Нужно изменить значение реквизита «Ставка отпускного» для всех
//    записей справочника «Виды отпусков» (или только для выбранных).
//  • Обновление должно выполняться в **Объектном режиме** (Object mode),
//    чтобы гарантировать корректную работу бизнес‑логики (триггеров, обработчиков
//    событий, расчётов).
//  • Перед началом проверяем, что у текущего пользователя есть права
//    «Запись» (Write) на справочник.
//  • Операцию выполняем в транзакции. При любой ошибке – откатываем
//    изменения и выводим информативное сообщение.
//===================================================================

&НаКлиенте
Процедура ОбновитьСтавкуОтпускного_КнопкаНажатие(Кнопка)
    // 1. Запросить у пользователя новое значение ставки.
    НовыйПараметр = ВводЗначения("Введите новую ставку отпускного (в %):", "10");
    Если НЕ НовыйПараметр Тогда
        Предупреждение("Операция отменена пользователем.");
        Возврат;
    КонецЕсли;

    // 2. Привести ввод к числу и проверить диапазон.
    Ставка = Число(НовыйПараметр);
    Если Ставка < 0 Тогда
        Предупреждение("Ставка не может быть отрицательной.");
        Возврат;
    КонецЕсли;

    // 3. Запустить серверный обработчик в режиме «Объектный режим».
    //    Для этого используем вызов метода объекта «Справочник.ВидыОтпусков»
    //    через RemoteProcedureCall (RPC).
    //    Параметры: новое значение ставки.
    Результат = ВыполнитьНаСервере("ОбновитьСтавкуОтпускного_Сервер", Ставка);

    Если Результат.Успех Тогда
        Сообщить("Ставка отпускного успешно обновлена для " + Результат.Кол-воОбновленных + " записей.");
    Иначе
        Предупреждение("Ошибка при обновлении: " + Результат.Сообщение);
    КонецЕсли;
КонецПроцедуры

//===================================================================
//  Серверный модуль (Объектный режим)
//===================================================================
&НаСервере
Функция ОбновитьСтавкуОтпускного_Сервер(НоваяСтавка) Экспорт
    // Возврат структуры с полями: Успех, Сообщение, Кол-воОбновленных
    Результат = Новый Структура("Успех,Сообщение,Кол-воОбновленных", Ложь, "", 0);

    // 1. Проверка прав доступа пользователя.
    //    Метод "Пользователь.ЕстьПрава" проверяет права на запись.
    Если НЕ Пользователь.ЕстьПрава(Справочники.ВидыОтпусков, Доступ.Запись) Тогда
        Результат.Сообщение = "Недостаточно прав для записи в справочник \"Виды отпусков\".";
        Возврат Результат;
    КонецЕсли;

    // 2. Открываем транзакцию.
    НачалоТранзакции();
    Попытка
        // 3. Получаем набор записей справочника.
        Выборка = Справочники.ВидыОтпусков.Выбрать();
        Пока Выборка.Следующий() Цикл
            // 4. Переходим в объектный режим записи.
            //    Для каждой записи вызываем метод "Записать" после изменения.
            ВидОтпуска = Выборка.ПолучитьОбъект();
            //    Если требуется обновлять только определённые виды, можно добавить условие,
            //    например: Если ВидОтпуска.ЭтоОсновной() Тогда … КонецЕсли;
            ВидОтпуска.СтавкаОтпускного = НоваяСтавка;
            ВидОтпуска.Записать(); // запись в объектном режиме
            Результат.Кол-воОбновленных = Результат.Кол-воОбновленных + 1;
        КонецЦикла;

        // 5. Если всё прошло без ошибок – фиксируем транзакцию.
        ЗафиксироватьТранзакцию();
        Результат.Успех = Истина;
    Исключение
        // 6. При любой ошибке откатываем транзакцию и сохраняем сообщение.
        ОткатТранзакции();
        Результат.Сообщение = ОписаниеОшибки();
    КонецПопытки;

    Возврат Результат;
КонецФункции

//===================================================================
//  Пояснения к коду
//===================================================================
/*
1. **Объектный режим** – используется, когда необходимо, чтобы сработали
   обработчики «ПередЗаписью», «ПослеЗаписи», расчётные формулы и т.п.
   В коде это достигается через метод `ПолучитьОбъект()` у строки выбора.

2. **Проверка прав** – без неё пользователь без прав записи получит ошибку
   уровня «Недостаточно прав», но транзакция всё равно будет открыта.
   Поэтому проверяем заранее и сразу возвращаем результат.

3. **Транзакция** – `НачалоТранзакции/ЗафиксироватьТранзакцию/ОткатТранзакции`
   гарантируют атомарность: либо все записи обновятся, либо ни одна.
   Ошибки могут возникнуть, например, при нарушении уникальности реквизита
   или при срабатывании бизнес‑логики в обработчиках.

4. **Обратная связь** – функция возвращает структуру, которую клиент‑часть
   использует для вывода сообщения пользователю.

5. **Оптимизация** – если справочник содержит несколько тысяч записей,
   можно использовать пакетную запись (`Записать(, Ложь)`) или
   `Объект.Записать(, Истина)` для ускорения, но в учебных целях оставляем
   простую построчную запись.
*/

//===================================================================
//  Как использовать
//===================================================================
/*
1. Добавьте форму (или кнопку) в пользовательский интерфейс.
2. Привяжите обработчик `ОбновитьСтавкуОтпускного_КнопкаНажатие`
   к событию `Нажатие` этой кнопки.
3. При нажатии система запросит новое значение ставки и выполнит
   массовое обновление.
4. При необходимости ограничьте набор записей (например, только
   виды отпусков с кодом > 100) – добавьте условие внутри цикла `Пока`.
*/

//===================================================================
//  Обработка «Кейс_Отпуск_Больничный»
//  Полный сценарий выполнения кейса «Оформление отпусков и больничных»
//  для конфигурации «1С:Зарплата и управление персоналом 3.1»
//===================================================================

//===================================================================
//  1. Создание / обновление справочников
//===================================================================

Процедура СоздатьИОбновитьСправочники() Экспорт
    // ---------------------------------------------------------------
    // 1.1. Виды отпусков
    // ---------------------------------------------------------------
    ВидыОтпусков = Справочники.ВидыОтпусков.Выбрать();
    // Если нужного вида нет – создаём, иначе обновляем (например, меняем код)
    Если Не ВидыОтпусков.Следующий() Тогда
        НовыйВид = Справочники.ВидыОтпусков.СоздатьЭлемент();
        НовыйВид.Наименование = "Основной отпуск";
        НовыйВид.Код = "OT001";
        НовыйВид.Записать();
    КонецЕсли;

    // ---------------------------------------------------------------
    // 1.2. Виды больничных листов
    // ---------------------------------------------------------------
    ВидыБольничных = Справочники.ВидыБольничныхЛистов.Выбрать();
    Если Не ВидыБольничных.Следующий() Тогда
        НовыйВид = Справочники.ВидыБольничныхЛистов.СоздатьЭлемент();
        НовыйВид.Наименование = "Больничный лист (стандартный)";
        НовыйВид.Код = "BL001";
        НовыйВид.Записать();
    КонецЕсли;

    // ---------------------------------------------------------------
    // 1.3. Коды выплат (для расчёта отпускных и больничных)
    // ---------------------------------------------------------------
    КодыВыплат = Справочники.КодыВыплат.Выбрать();
    // Пример: код «Отпускные»
    Если Не НайтиЭлемент(КодыВыплат, "Отпускные") Тогда
        НовыйКод = Справочники.КодыВыплат.СоздатьЭлемент();
        НовыйКод.Наименование = "Отпускные";
        НовыйКод.Код = "V_OT";
        НовыйКод.Записать();
    КонецЕсли;
    // Пример: код «Больничные выплаты»
    Если Не НайтиЭлемент(КодыВыплат, "Больничные выплаты") Тогда
        НовыйКод = Справочники.КодыВыплат.СоздатьЭлемент();
        НовыйКод.Наименование = "Больничные выплаты";
        НовыйКод.Код = "V_BL";
        НовыйКод.Записать();
    КонецЕсли;

    // ---------------------------------------------------------------
    // 1.4. Справочник «Отпуска» (документ‑справочник, в котором хранятся
    //      сведения о конкретных отпусках сотрудников)
    // ---------------------------------------------------------------
    // В 1С:ЗУП отпуска оформляются документом «ПриказОбОтпуске»,
    // но для демонстрации создадим вспомогательный справочник «Отпуска».
    // Если элемент уже существует – обновляем даты.
    Сотрудники = Справочники.Сотрудники.Выбрать();
    Пока Сотрудники.Следующий() Цикл
        // Пример: создаём отпуск на 2024‑07‑01 – 2024‑07‑14
        ДатаНач = Дата(2024, 7, 1);
        ДатаКон = Дата(2024, 7, 14);
        // Ищем уже существующий отпуск для данного сотрудника и периода
        Запрос = Новый Запрос;
        Запрос.Текст = 
            "ВЫБРАТЬ ПЕРВЫЕ 1
            |   Отпуска.Ссылка КАК Ссылка
            |ИЗ
            |   Справочник.Отпуска КАК Отпуска
            |ГДЕ
            |   Отпуска.Сотрудник = &Сотрудник
            |   И Отпуска.ДатаНачала = &ДатаНач
            |   И Отпуска.ДатаОкончания = &ДатаКон";
        Запрос.УстановитьПараметр("Сотрудник", Сотрудники.Ссылка);
        Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
        Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
        Результат = Запрос.Выполнить();
        Выборка = Результат.Выбрать();
        Если Не Выборка.Следующий() Тогда
            НовыйОтпуск = Справочники.Отпуска.СоздатьЭлемент();
            НовыйОтпуск.Сотрудник = Сотрудники.Ссылка;
            НовыйОтпуск.ДатаНачала = ДатаНач;
            НовыйОтпуск.ДатаОкончания = ДатаКон;
            НовыйОтпуск.ВидОтпуска = Справочники.ВидыОтпусков.НайтиПоКоду("OT001");
            НовыйОтпуск.Записать();
        КонецЕсли;
    КонецЦикла;

    Сообщить("Справочники созданы/обновлены.");
КонецПроцедуры;

//===================================================================
//  Вспомогательная функция – поиск элемента справочника по Наименованию
//===================================================================
Функция НайтиЭлемент(Выборка, Наименование) Экспорт
    Пока Выборка.Следующий() Цикл
        Если Выборка.Наименование = Наименование Тогда
            Возврат Истина;
        КонецЕсли;
    КонецЦикла;
    Возврат Ложь;
КонецФункции;

//===================================================================
//  2. Оформление приказов «О предоставлении отпуска» и «О больничном»
//===================================================================

Процедура ОформитьПриказОбОтпуске() Экспорт
    // ---------------------------------------------------------------
    // 2.1. Выбираем сотрудника, которому оформляем отпуск
    // ---------------------------------------------------------------
    Сотрудник = Справочники.Сотрудники.НайтиПоНаименованию("Иванов Иван Иванович");
    Если Сотрудник = Неопределено Тогда
        Предупреждение("Сотрудник Иванов И.И. не найден в справочнике Сотрудники.");
        Возврат;
    КонецЕсли;

    // ---------------------------------------------------------------
    // 2.2. Создаём документ «ПриказОбОтпуске»
    // ---------------------------------------------------------------
    Приказ = Документы.ПриказОбОтпуске.СоздатьДокумент();
    Приказ.Дата = ТекущаяДата();
    Приказ.Номер = "ОТ-" + Формат(ТекущаяДата(), "ДФ=yyyyMMdd");
    Приказ.Сотрудник = Сотрудник.Ссылка;
    Приказ.ДатаНачала = Дата(2024, 7, 1);
    Приказ.ДатаОкончания = Дата(2024, 7, 14);
    Приказ.ВидОтпуска = Справочники.ВидыОтпусков.НайтиПоКоду("OT001");
    // Бизнес‑правило: отпуск может быть оформлен только если в период
    // отсутствия отпуска нет открытых больничных листов.
    Если ЕстьОткрытыйБольничный(Сотрудник) Тогда
        Предупреждение("У сотрудника есть открытый больничный лист. Оформление отпуска невозможно.");
        Возврат;
    КонецЕсли;
    Приказ.Записать();
    Приказ.Провести();
    // Печать приказа (шаблон «ПриказОбОтпуске_Печать»)
    Приказ.ПоказатьПечать();
    Сообщить("Приказ об отпуске оформлен и проведён.");
КонецПроцедуры;

Процедура ОформитьПриказОБольничном() Экспорт
    // ---------------------------------------------------------------
    // 2.1. Выбираем сотрудника
    // ---------------------------------------------------------------
    Сотрудник = Справочники.Сотрудники.НайтиПоНаименованию("Петров Петр Петрович");
    Если Сотрудник = Неопределено Тогда
        Предупреждение("Сотрудник Петров П.П. не найден.");
        Возврат;
    КонецЕсли;

    // ---------------------------------------------------------------
    // 2.2. Создаём документ «ПриказОБольничномЛисте»
    // ---------------------------------------------------------------
    ПриказБ = Документы.ПриказОБольничномЛисте.СоздатьДокумент();
    ПриказБ.Дата = ТекущаяДата();
    ПриказБ.Номер = "BL-" + Формат(ТекущаяДата(), "ДФ=yyyyMMdd");
    ПриказБ.Сотрудник = Сотрудник.Ссылка;
    ПриказБ.ДатаНачала = Дата(2024, 8, 5);
    ПриказБ.ДатаОкончания = Дата(2024, 8, 12);
    ПриказБ.ВидБольничного = Справочники.ВидыБольничныхЛистов.НайтиПоКоду("BL001");
    // Бизнес‑правило: нельзя оформить больничный, если в этот период уже
    // оформлен отпуск (перекрытие отпуск‑больничный запрещено).
    Если ЕстьОтпускВПериод(Сотрудник, ПриказБ.ДатаНачала, ПриказБ.ДатаОкончания) Тогда
        Предупреждение("В указанный период уже оформлен отпуск. Оформление больничного невозможно.");
        Возврат;
    КонецЕсли;
    ПриказБ.Записать();
    ПриказБ.Провести();
    ПриказБ.ПоказатьПечать();
    Сообщить("Приказ о больничном листе оформлен и проведён.");
КонецПроцедуры;

//===================================================================
//  Вспомогательные проверки
//===================================================================

Функция ЕстьОткрытыйБольничный(Сотрудник) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ ПЕРВЫЕ 1
        |   БольничныеЛисты.Ссылка КАК Ссылка
        |ИЗ
        |   Документ.БольничныйЛист КАК БольничныеЛисты
        |ГДЕ
        |   БольничныеЛисты.Сотрудник = &Сотрудник
        |   И БольничныеЛисты.ДатаОкончания >= &ТекДата";
    Запрос.УстановитьПараметр("Сотрудник", Сотрудник.Ссылка);
    Запрос.УстановитьПараметр("ТекДата", ТекущаяДата());
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Возврат Выборка.Следующий();
КонецФункции;

Функция ЕстьОтпускВПериод(Сотрудник, ДатаНач, ДатаКон) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ ПЕРВЫЕ 1
        |   ПриказыОбОтпуске.Ссылка КАК Ссылка
        |ИЗ
        |   Документ.ПриказОбОтпуске КАК ПриказыОбОтпуске
        |ГДЕ
        |   ПриказыОбОтпуске.Сотрудник = &Сотрудник
        |   И (ПриказыОбОтпуске.ДатаНачала <= &ДатаКон И ПриказыОбОтпуске.ДатаОкончания >= &ДатаНач)";
    Запрос.УстановитьПараметр("Сотрудник", Сотрудник.Ссылка);
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Возврат Выборка.Следующий();
КонецФункции;

//===================================================================
//  3. Проведение расчёта зарплаты за период (включая отпускные и больничные)
//===================================================================

Процедура ПровестиРасчётЗарплаты() Экспорт
    // Параметры расчёта – период, для которого будет выполнен расчёт.
    ПериодНач = Дата(2024, 7, 1);
    ПериодКон = Дата(2024, 8, 31);

    // Встроенный обработчик «РасчётЗарплаты» (модуль «ОбщегоНазначения»)
    // В 1С:ЗУП расчёт вызывается через метод "ВыполнитьРасчёт".
    // Для демонстрации используем стандартный обработчик.
    Обработчик = Обработки.РасчётЗарплаты;
    Обработчик.УстановитьПараметр("ДатаНачала", ПериодНач);
    Обработчик.УстановитьПараметр("ДатаОкончания", ПериодКон);
    // Включаем расчёт отпускных и больничных (в конфигурации они включены по умолчанию).
    Обработчик.УстановитьПараметр("ВключатьОтпускные", Истина);
    Обработчик.УстановитьПараметр("ВключатьБольничные", Истина);
    // Запускаем расчёт
    Обработчик.Выполнить();
    Сообщить("Расчёт зарплаты за период " + Формат(ПериодНач, "ДФ=dd.MM.yyyy") + " - " + Формат(ПериодКон, "ДФ=dd.MM.yyyy") + " завершён.");
КонецПроцедуры;

//===================================================================
//  4. Проверка результатов в регистрах «Расчёт зарплаты» и «Выплаты»
//===================================================================

Процедура ПроверитьРезультаты() Экспорт
    // ---------------------------------------------------------------
    // 4.1. Регистратор расчёта зарплаты (РегистрыНакопления.РасчётЗарплаты)
    // ---------------------------------------------------------------
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |   РасчётЗарплаты.Сотрудник,
        |   РасчётЗарплаты.Дата,
        |   РасчётЗарплаты.Сумма,
        |   РасчётЗарплаты.ВидРасчёта
        |ИЗ
        |   РегистрыНакопления.РасчётЗарплаты КАК РасчётЗарплаты
        |ГДЕ
        |   РасчётЗарплаты.Дата МЕЖДУ &ДатаНач И &ДатаКон";
    Запрос.УстановитьПараметр("ДатаНач", Дата(2024, 7, 1));
    Запрос.УстановитьПараметр("ДатаКон", Дата(2024, 8, 31));
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Сообщить("--- Регистратор расчёта зарплаты ---");
    Пока Выборка.Следующий() Цикл
        Сообщить(Выборка.Сотрудник + ": " + Формат(Выборка.Сумма, "ЧГ=0.00") + " (" + Выборка.ВидРасчёта + ")");
    КонецЦикла;

    // ---------------------------------------------------------------
    // 4.2. Регистратор выплат (РегистрыНакопления.Выплаты)
    // ---------------------------------------------------------------
    ЗапросТекст = 
        "ВЫБРАТЬ
        |   Выплаты.Сотрудник,
        |   Выплаты.Дата,
        |   Выплаты.Сумма,
        |   Выплаты.КодВыплаты
        |ИЗ
        |   РегистрыНакопления.Выплаты КАК Выплаты
        |ГДЕ
        |   Выплаты.Дата МЕЖДУ &ДатаНач И &ДатаКон";
    Запрос = Новый Запрос(ЗапросТекст);
    Запрос.УстановитьПараметр("ДатаНач", Дата(2024, 7, 1));
    Запрос.УстановитьПараметр("ДатаКон", Дата(2024, 8, 31));
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Сообщить("--- Регистратор выплат ---");
    Пока Выборка.Следующий() Цикл
        Сообщить(Выборка.Сотрудник + ": " + Формат(Выборка.Сумма, "ЧГ=0.00") + " (Код " + Выборка.КодВыплаты + ")");
    КонецЦикла;
КонецПроцедуры;

//===================================================================
//  5. Формирование стандартных отчётов и экспорт в Excel
//===================================================================

Процедура СформироватьОтчёты() Экспорт
    // ---------------------------------------------------------------
    // 5.1. Отчёт по отпускам
    // ---------------------------------------------------------------
    ОтчОтпуск = Отчёты.ОтчётПоОтпускам;
    // Параметры отчёта – период
    ОтчОтпуск.УстановитьПараметр("ДатаНач", Дата(2024, 1, 1));
    ОтчОтпуск.УстановитьПараметр("ДатаКон", Дата(2024, 12, 31));
    // Получаем форму отчёта
    ФормаОтчОтпуск = ОтчОтпуск.ПолучитьФорму();
    ФормаОтчОтпуск.Открыть();
    // Экспорт в Excel (встроенный метод "ЭкспортВExcel")
    ПутьExcel = "C:\Temp\Отчёт_Отпуска.xlsx";
    ФормаОтчОтпуск.ЭкспортВExcel(ПутьExcel);
    Сообщить("Отчёт по отпускам экспортирован в " + ПутьExcel);

    // ---------------------------------------------------------------
    // 5.2. Отчёт по больничным
    // ---------------------------------------------------------------
    ОтчБольничный = Отчёты.ОтчётПоБольничным;
    ОтчБольничный.УстановитьПараметр("ДатаНач", Дата(2024, 1, 1));
    ОтчБольничный.УстановитьПараметр("ДатаКон", Дата(2024, 12, 31));
    ФормаБольничный = ОтчБольничный.ПолучитьФорму();
    ФормаБольничный.Открыть();
    ПутьExcelБ = "C:\Temp\Отчёт_Больничные.xlsx";
    ФормаБольничный.ЭкспортВExcel(ПутьExcelБ);
    Сообщить("Отчёт по больничным экспортирован в " + ПутьExcelБ);

    // ---------------------------------------------------------------
    // 5.3. Выплаты по видам (отпускные, больничные)
    // ---------------------------------------------------------------
    ОтчВыплаты = Отчёты.ВыплатыПоВидам;
    ОтчВыплаты.УстановитьПараметр("ДатаНач", Дата(2024, 1, 1));
    ОтчВыплаты.УстановитьПараметр("ДатаКон", Дата(2024, 12, 31));
    ФормаВыплаты = ОтчВыплаты.ПолучитьФорму();
    ФормаВыплаты.Открыть();
    ПутьExcelВ = "C:\Temp\Выплаты_По_Видам.xlsx";
    ФормаВыплаты.ЭкспортВExcel(ПутьExcelВ);
    Сообщить("Отчёт «Выплаты по видам» экспортирован в " + ПутьExcelВ);
КонецПроцедуры;

//===================================================================
//  6. Подготовка выгрузки данных в 1С:Бухгалтерию
//===================================================================

Процедура ВыгрузитьВБухгалтерию() Экспорт
    // В 1С:ЗУП обычно используется регистр‑накопитель «ВыгрузкаВБухгалтерию».
    // Создадим (если ещё не существует) регистр‑накопитель и заполним его.
    // Для простоты будем выгружать только выплаты по коду «V_OT» и «V_BL».

    // ---------------------------------------------------------------
    // 6.1. Очистка предыдущих записей (чтобы выгрузка была «чистой»)
    // ---------------------------------------------------------------
    РегВыгрузка = РегистрыНакопления.ВыгрузкаВБухгалтерию;
    РегВыгрузка.Очистить();

    // ---------------------------------------------------------------
    // 6.2. Заполнение регистра‑накопителя
    // ---------------------------------------------------------------
    ЗапросТекст = 
        "ВЫБРАТЬ
        |   Выплаты.Сотрудник,
        |   Выплаты.Дата,
        |   Выплаты.Сумма,
        |   Выплаты.КодВыплаты
        |ИЗ
        |   РегистрыНакопления.Выплаты КАК Выплаты
        |ГДЕ
        |   Выплаты.КодВыплаты В (&Коды)";
    Запрос = Новый Запрос(ЗапросТекст);
    Запрос.УстановитьПараметр("Коды", Новый Массив("V_OT", "V_BL"));
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = РегВыгрузка.Записать();
        Строка.Сотрудник = Выборка.Сотрудник;
        Строка.Дата = Выборка.Дата;
        Строка.Сумма = Выборка.Сумма;
        Строка.КодВыплаты = Выборка.КодВыплаты;
        // Поля, обязательные для интеграции с 1С:Бухгалтерия
        // (например, Дебет/Кредит, Субконто) – заполняются в соответствии
        // с настройками аналитики бухгалтерии.
        Строка.Дебет = "62.01"; // пример – расчётный счёт
        Строка.Контрагент = Выборка.Сотрудник; // в бухгалтерии – контрагент = сотрудник
        Строка.Записать();
    КонецЦикла;

    // ---------------------------------------------------------------
    // 6.3. Формируем файл выгрузки (XML) – типовой шаблон «ВыгрузкаВБух.xml»
    // ---------------------------------------------------------------
    ПутьФайла = "C:\Temp\Выгрузка_ЗП_2024.xml";
    // Встроенный механизм выгрузки: РегистрыНакопления.ВыгрузкаВБухгалтерию.ЭкспортироватьВФайл()
    РегВыгрузка.ЭкспортироватьВФайл(ПутьФайла);
    Сообщить("Выгрузка в 1С:Бухгалтерию завершена. Файл: " + ПутьФайла);
КонецПроцедуры;

//===================================================================
//  7. Главный метод – последовательный запуск всех шагов
//===================================================================

Процедура ЗапуститьКейс() Экспорт
    // 1. Справочники
    СоздатьИОбновитьСправочники();

    // 2. Приказы
    ОформитьПриказОбОтпуске();
    ОформитьПриказОБольничном();

    // 3. Расчёт зарплаты
    ПровестиРасчётЗарплаты();

    // 4. Проверка результатов
    ПроверитьРезультаты();

    // 5. Отчёты + экспорт в Excel
    СформироватьОтчёты();

    // 6. Выгрузка в бухгалтерию
    ВыгрузитьВБухгалтерию();

    Сообщить("=== Кейс «Отпуск и больничный» выполнен полностью ===");
КонецПроцедуры;

//===================================================================
//  8. Инструкция по запуску обработки из пользовательского интерфейса
//===================================================================
/*
   1. Откройте конфигуратор и загрузите текущую конфигурацию «1С:Зарплата и управление персоналом 3.1».
   2. В дереве конфигурации выберите пункт «Обработки» → «Новая обработка».
   3. Дайте обработке имя «Кейс_Отпуск_Больничный» и нажмите «ОК».
   4. В открывшемся модуле обработки замените содержимое модуля «Общий модуль» на код,
      представленный выше (вставьте полностью).
   5. Сохраните обработку (Ctrl+S) и выполните её компиляцию (Кнопка «Проверить»).
   6. Перейдите в режим «1С:Предприятие» (кнопка «Запустить»).
   7. В меню «Открыть» → «Обработки» найдите обработку «Кейс_Отпуск_Больничный» и откройте её.
   8. На форме обработки появится кнопка «ЗапуститьКейс». Нажмите её – последовательно
      выполнится весь сценарий: создание справочников, оформление приказов, расчёт,
      проверка, формирование отчётов и выгрузка в бухгалтерию.
   9. После завершения в окне сообщений будет выведено сообщение о полном выполнении.
   10. Проверьте созданные файлы в каталоге C:\Temp (Excel‑отчёты и XML‑выгрузка).
*/

