// ---------------------------------------------------------------
// Обработчик формирования стандартного отчёта «Начисления и выплаты за месяц»
// ---------------------------------------------------------------

Процедура ФормироватьОтчет(Отчет, ПараметрыОтчета) Экспорт
    // 1. Получаем объект «Таблица» – место, куда будем добавлять колонки и строки.
    Таблица = Отчет.Таблица;

    // ---------------------------------------------------------------
    // 2. Добавляем вычисляемую колонку «Сумма начислений»
    // ---------------------------------------------------------------
    //   a) Создаём объект колонки.
    КолонкаСуммаНачислений = Таблица.Колонки.Добавить();

    //   b) Устанавливаем заголовок, который будет виден пользователю.
    КолонкаСуммаНачислений.Заголовок = "Сумма начислений";

    //   c) Указываем тип данных колонки – Число.
    //      ОписаниеТипов(Тип("Число")) – стандартный способ задать тип в 1С.
    КолонкаСуммаНачислений.ТипДанных = Новый ОписаниеТипов(Тип("Число"));

    //   d) Задаём формулу расчёта.
    //      Формула записывается как строка, в которой имена полей берутся из
    //      набора данных, передаваемого в отчёт (в данном случае – "СуммаБазовойСтавки" и "Надбавки").
    //      Формула будет вычисляться для каждой строки таблицы.
    КолонкаСуммаНачислений.Формула = "СуммаБазовойСтавки + Надбавки";

    //   e) Формат отображения – два знака после запятой и разделитель тысяч.
    КолонкаСуммаНачислений.Формат = "ЧГ=2"; // ЧГ – числовой формат, 2 знака после запятой.

    // ---------------------------------------------------------------
    // 3. Условное форматирование – выделять отрицательные суммы красным цветом
    // ---------------------------------------------------------------
    //   a) Создаём правило условного форматирования.
    Условие = КолонкаСуммаНачислений.УсловноеФорматирование.Добавить();

    //   b) Условие задаётся как строка‑выражение, которое возвращает Истина/Ложь.
    //      Здесь проверяем, что значение колонки меньше нуля.
    Условие.Условие = "Значение < 0"; // "Значение" – специальный идентификатор текущего значения ячейки.

    //   c) Описываем, как будет выглядеть ячейка, если условие выполнено.
    //      Цвет текста – Красный, фон – без изменения.
    Условие.ЦветТекста = Цвета.Красный();
    // Условие.ЦветФона = Цвета.Желтый(); // (по желанию можно задать фон)

    // ---------------------------------------------------------------
    // 4. (Опционально) Добавляем колонку в список «Отображаемые колонки» отчёта.
    //    Это необходимо, если в шаблоне отчёта используется набор «ОтображаемыеКолонки».
    // ---------------------------------------------------------------
    // Отчет.ОтображаемыеКолонки.Добавить(КолонкаСуммаНачислений);

    // ---------------------------------------------------------------
    // 5. Завершаем формирование отчёта – остальные колонки (дата, сотрудник, …)
    //    добавляются аналогичным образом или задаются в шаблоне.
    // ---------------------------------------------------------------
КонецПроцедуры

/* -------------------------------------------------------------------
   Как проверить корректность формулы
   -------------------------------------------------------------------
   1. Откройте «Мастер отчётов» (в конфигураторе – пункт меню
      «Отчёты → Мастер создания отчётов»).
   2. Выберите нужный отчёт и перейдите к шагу «Колонки». В списке
      колонок найдите только что добавленную «Сумма начислений».
   3. Нажмите кнопку «Проверить» (обычно расположена в правом нижнем
      углу окна мастера). Платформа выполнит проверку синтаксиса
      формулы и отобразит сообщение об ошибке, если в ней есть
      недочёты (например, опечатка в имени поля).
   4. После успешной проверки нажмите «ОК» и запустите отчёт – в
      таблице вы увидите рассчитанные значения. Для уверенности
      сравните несколько строк с расчётом в «Бухгалтерском регистре
      начислений».
   ------------------------------------------------------------------- */

//===================================================================
//  Пример: запрос для сводного расчёта налогов по подразделениям
//===================================================================
//  Параметры запроса (устанавливаются в обработчике формы)
//      ДатаНач – начало периода расчёта
//      ДатаКон – конец периода расчёта
//===================================================================

//--------------------------- Текст запроса ---------------------------
ЗапросТекст =
"""
ВЫБРАТЬ
    // Подразделение, по которому будет группировка
    Налог.Подразделение КАК Подразделение,
    // Вид налога (например, НДФЛ, Страховые взносы и т.д.)
    Налог.ВидНалога КАК ВидНалога,
    // Сумма налога за период – агрегатная функция СУММА
    СУММА(Налог.Сумма) КАК СуммаНалога,
    // Пример расчёта «чистой» суммы по разным ставкам через ВЫБОР (CASE)
    // Если ставка = 13% – берём 13% от суммы, иначе – 15%
    СУММА(ВЫБОР
            КОГДА Налог.Ставка = 13 ТОДА  Налог.Сумма * 0.13
            ИНАЧЕ               Налог.Сумма * 0.15
          КОНЕЦ) КАК СуммаПоСтавке
ИЗ
    РегистрНакопления.РасчётНалогов КАК Налог
ГДЕ
    // Оставляем только записи, попадающие в выбранный период
    Налог.Период МЕЖДУ &ДатаНач И &ДатаКон
ГРУППИРОВАТЬ ПО
    // Группируем сначала по подразделению, затем по виду налога
    Налог.Подразделение,
    Налог.ВидНалога
""";

//--------------------------- Создание и настройка запроса ---------------------------
Запрос = Новый Запрос;
Запрос.Текст = ЗапросТекст;
// Параметры передаются из формы (см. ниже)
Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

// Выполняем запрос и получаем результат
Результат = Запрос.Выполнить();
Выборка = Результат.Выбрать();

// Пример обхода результата (можно передать в макет отчёта)
Пока Выборка.Следующий() Цикл
    Сообщить("Подразделение: " + Выборка.Подразделение + ", Вид налога: " + Выборка.ВидНалога +
            ", Сумма: " + Формат(Выборка.СуммаНалога, "ЧГ=0.00") +
            ", Сумма по ставке: " + Формат(Выборка.СуммаПоСтавке, "ЧГ=0.00"));
КонецЦикла;

//===================================================================
//  Как объявить параметры в модуле обработки (Bsl) и передать их из формы
//===================================================================
//  Предположим, у вас есть форма отчёта с двумя полями DatePicker: "ДатаНач" и "ДатаКон".
//  В обработчике формы (например, ПриОткрытии) задаём начальные значения.
//===================================================================

Процедура ПриОткрытии(Отказ, СтандартнаяОбработка)
    // Устанавливаем значения по умолчанию (текущий месяц)
    ФормаЭлементы.ДатаНач.Значение = НачалоМесяца(ТекущаяДата());
    ФормаЭлементы.ДатаКон.Значение = КонецМесяца(ТекущаяДата());
КонецПроцедуры

//===================================================================
//  Кнопка «Сформировать» – формируем запрос, передаём параметры и открываем отчёт
//===================================================================

Процедура СформироватьНажатие(Кнопка)
    // 1. Считываем параметры из формы
    ДатаНач = ФормаЭлементы.ДатаНач.Значение;
    ДатаКон = ФормаЭлементы.ДатаКон.Значение;

    // 2. Проверяем корректность диапазона
    Если ДатаНач > ДатаКон Тогда
        Предупреждение("Дата начала не может быть позже даты окончания.");
        Возврат;
    КонецЕсли;

    // 3. Создаём запрос (текст берём из константы или ресурса – здесь inline)
    Запрос = Новый Запрос;
    Запрос.Текст = ЗапросТекст; // переменная, объявленная выше в модуле
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // 4. Формируем отчёт (макет "СводныйРасчётНалогов" должен быть создан в конфиге)
    Отчет = Новый Отчет;
    Отчет.ИмяМакета = "СводныйРасчётНалогов";
    Отчет.Запрос = Запрос;
    // При необходимости передаём дополнительные параметры в макет
    // Отчет.УстановитьПараметр("ДатаНач", ДатаНач);
    // Отчет.УстановитьПараметр("ДатаКон", ДатаКон);

    // 5. Открываем форму отчёта
    ФормаОтчета = Отчет.ПолучитьФорму();
    ФормаОтчета.Открыть();
КонецПроцедуры

//===================================================================
//  Важно: макет отчёта «СводныйРасчётНалогов» должен содержать поля
//  Подразделение, ВидНалога, СуммаНалога, СуммаПоСтавке – имена совпадают
//  с колонками SELECT. При построении табличного макета просто разместите
//  соответствующие поля в нужных колонках.
//===================================================================
}

/*
=== Краткое пояснение к запросу ===
* SELECT
  - Подразделение – группируем данные по организационным единицам.
  - ВидНалога – тип налога (НДФЛ, страховые взносы и т.д.).
  - СуммаНалога – общая сумма налога за выбранный период.
  - СуммаПоСтавке – демонстрация использования функции ВЫБОР (CASE) для
    расчёта суммы по разным ставкам (13% и 15%).
* WHERE
  - Оставляем только записи, где Период находится между параметрами
    ДатаНач и ДатаКон.
* GROUP BY
  - Группируем сначала по Подразделению, затем по ВидНалога – это
    обеспечивает «сводный» вид отчёта, где в каждой строке указана
    сумма налога по конкретному подразделению и виду налога.
*/

/**
 * Как использовать в 1С:
 * 1. Скопировать весь блок кода в модуль обработки (или в модуль формы).
 * 2. Создать макет отчёта "СводныйРасчётНалогов" с полями, указанными в SELECT.
 * 3. На форме добавить два DatePicker (ДатаНач, ДатаКон) и кнопку "Сформировать".
 * 4. Привязать обработчики ПриОткрытии и СформироватьНажатие к соответствующим
 *    процедурам из примера.
 * После этого пользователь сможет выбрать диапазон дат и получить сводный
 * расчёт налогов по подразделениям.
 */

//===================================================================
// 1С:Зарплата и управление персоналом 3.1
// Практический пример: экспорт «Ведомости начислений» в Excel
// и последующий импорт в 1С:Бухгалтерию
//===================================================================

//===================================================================
// 1. Экспорт в Excel
//===================================================================

/**
 * Экспортировать ведомость начислений за указанный период в файл Excel.
 *
 * @Параметры
 *   ДатаНач   – Дата начала периода (Дата);
 *   ДатаКон   – Дата окончания периода (Дата);
 *   ПутьФайла – Полный путь к файлу, в который будет записан результат (Строка).
 *
 * @Возврат
 *   Истина – если экспорт выполнен успешно, иначе Ложь.
 */
Функция ЭкспортВедомостиВExcel(ДатаНач, ДатаКон, ПутьФайла) Экспорт
    Попытка
        // ------------------------------------------------------------
        // 1. Формируем запрос к базе данных
        // ------------------------------------------------------------
        ТекстЗапроса = 
            "ВЫБРАТЬ" +
            "   Начисления.Дата КАК Дата," +
            "   Сотрудники.Наименование КАК Сотрудник," +
            "   Начисления.СтатьяНачисления КАК Статья," +
            "   Начисления.Сумма КАК Сумма" +
            " ИЗ" +
            "   РегистрНакопления.Начисления КАК Начисления" +
            "   ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Сотрудники КАК Сотрудники" +
            "       ПО Начисления.Сотрудник = Сотрудники.Ссылка" +
            "ГДЕ" +
            "   Начисления.Дата МЕЖДУ &ДатаНач И &ДатаКон" +
            "УПОРЯДОЧИТЬ ПО Дата, Сотрудник";

        Запрос = Новый Запрос(ТекстЗапроса);
        Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
        Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
        Результат = Запрос.Выполнить();
        Выборка = Результат.Выбрать();

        // ------------------------------------------------------------
        // 2. Создаём объект Excel через COM‑интерфейс
        // ------------------------------------------------------------
        Excel = Новый COMОбъект("Excel.Application");
        Excel.Visible = Ложь; // скрыть окно Excel
        Книга = Excel.Workbooks.Add();
        Лист = Книга.Worksheets(1);
        Лист.Name = "Ведомость начислений";

        // ------------------------------------------------------------
        // 3. Заполняем заголовки столбцов
        // ------------------------------------------------------------
        Заголовки = Новый Массив();
        Заголовки.Добавить("Дата");
        Заголовки.Добавить("Сотрудник");
        Заголовки.Добавить("Статья начисления");
        Заголовки.Добавить("Сумма");

        Для i = 0 По Заголовки.Количество() - 1 Цикл
            Ячейка = Лист.Cells(1, i + 1);
            Ячейка.Value = Заголовки[i];
            Ячейка.Font.Bold = Истина;
            Ячейка.Interior.ColorIndex = 15; // светло‑серый фон
        КонецЦикла;

        // ------------------------------------------------------------
        // 4. Заполняем данными
        // ------------------------------------------------------------
        НомерСтроки = 2;
        Пока Выборка.Следующий() Цикл
            Лист.Cells(НомерСтроки, 1).Value = Выборка.Дата;
            Лист.Cells(НомерСтроки, 2).Value = Выборка.Сотрудник;
            Лист.Cells(НомерСтроки, 3).Value = Выборка.Статья;
            Лист.Cells(НомерСтроки, 4).Value = Выборка.Сумма;
            НомерСтроки = НомерСтроки + 1;
        КонецЦикла;

        // ------------------------------------------------------------
        // 5. Форматируем столбцы (даты, числа, ширина)
        // ------------------------------------------------------------
        Лист.Columns(1).NumberFormat = "dd.mm.yyyy";
        Лист.Columns(4).NumberFormat = "#,##0.00";
        Лист.Columns.AutoFit();

        // ------------------------------------------------------------
        // 6. Сохраняем файл и освобождаем COM‑объекты
        // ------------------------------------------------------------
        Книга.SaveAs(ПутьФайла);
        Книга.Close();
        Excel.Quit();
        // Освобождаем ссылки (важно для избежания «зависания» Excel)
        ОсвободитьОбъект(Книга);
        ОсвободитьОбъект(Excel);

        Возврат Истина;
    Исключение
        // Логируем ошибку в журнале регистрации
        Сообщить("Ошибка экспорта в Excel: " + ОписаниеОшибки());
        Возврат Ложь;
    КонецПопытки;
КонецФункции

//===================================================================
// 2. Импорт из Excel в 1С:Бухгалтерию
//===================================================================
/**
 * Импортировать начисления из подготовленного Excel‑файла в регистр
 * "БухгалтерскиеНачисления" конфигурации 1С:Бухгалтерия.
 *
 * @Параметры
 *   ПутьФайла – Полный путь к файлу Excel (Строка).
 *   ДатаПериода – Дата, к которой будет привязан регистр (Дата).
 */
Процедура ИмпортВедомостиИзExcel(ПутьФайла, ДатаПериода) Экспорт
    Попытка
        // ------------------------------------------------------------
        // 1. Открываем файл Excel
        // ------------------------------------------------------------
        Excel = Новый COMОбъект("Excel.Application");
        Excel.Visible = Ложь;
        Книга = Excel.Workbooks.Open(ПутьФайла);
        Лист = Книга.Worksheets(1);

        // ------------------------------------------------------------
        // 2. Находим последнюю заполненную строку
        // ------------------------------------------------------------
        ПоследняяСтрока = Лист.Cells(Лист.Rows.Count, 1).End(-4162).Row; // xlUp = -4162

        // ------------------------------------------------------------
        // 3. Проходим по строкам и записываем в регистр
        // ------------------------------------------------------------
        Для НомерСтроки = 2 По ПоследняяСтрока Цикл
            ДатаНачисления = Лист.Cells(НомерСтроки, 1).Value;
            Сотрудник      = Лист.Cells(НомерСтроки, 2).Value;
            Статья         = Лист.Cells(НомерСтроки, 3).Value;
            Сумма          = Лист.Cells(НомерСтроки, 4).Value;

            // Поиск сотрудника в справочнике "Сотрудники"
            ЗапросСотрудник = Новый Запрос;
            ЗапросСотрудник.Текст =
                "ВЫБРАТЬ Ссылка" +
                " ИЗ Справочник.Сотрудники" +
                " ГДЕ Наименование = &ФИО";
            ЗапросСотрудник.УстановитьПараметр("ФИО", Сотрудник);
            РезультатСотрудник = ЗапросСотрудник.Выполнить();
            ВыборкаСотрудник = РезультатСотрудник.Выбрать();
            Если ВыборкаСотрудник.Следующий() Тогда
                СсылкаСотрудник = ВыборкаСотрудник.Ссылка;
            Иначе
                // Если сотрудник не найден – создаём запись в журнале и пропускаем
                Сообщить("Сотрудник не найден: " + Сотрудник);
                Продолжить;
            КонецЕсли;

            // Поиск статьи начисления в справочнике "СтатьиНачислений"
            ЗапросСтатья = Новый Запрос;
            ЗапросСтатья.Текст =
                "ВЫБРАТЬ Ссылка" +
                " ИЗ Справочник.СтатьиНачислений" +
                " ГДЕ Наименование = &Статья";
            ЗапросСтатья.УстановитьПараметр("Статья", Статья);
            РезультатСтатья = ЗапросСтатья.Выполнить();
            ВыборкаСтатья = РезультатСтатья.Выбрать();
            Если ВыборкаСтатья.Следующий() Тогда
                СсылкаСтатья = ВыборкаСтатья.Ссылка;
            Иначе
                Сообщить("Статья начисления не найдена: " + Статья);
                Продолжить;
            КонецЕсли;

            // Записываем в регистр "БухгалтерскиеНачисления"
            Запись = РегистрыБухгалтерии.БухгалтерскиеНачисления.Записать();
            Запись.Период = ДатаПериода;
            Запись.Сотрудник = СсылкаСотрудник;
            Запись.СтатьяНачисления = СсылкаСтатья;
            Запись.Сумма = Сумма;
            Запись.Записать();
        КонецЦикла;

        // ------------------------------------------------------------
        // 4. Закрываем Excel и освобождаем ресурсы
        // ------------------------------------------------------------
        Книга.Close(Ложь);
        Excel.Quit();
        ОсвободитьОбъект(Книга);
        ОсвободитьОбъект(Excel);

        Сообщить("Импорт завершён успешно.");
    Исключение
        Сообщить("Ошибка импорта из Excel: " + ОписаниеОшибки());
    КонецПопытки;
КонецПроцедуры

//===================================================================
// Вспомогательная процедура освобождения COM‑объекта
//===================================================================
Процедура ОсвободитьОбъект(Объект)
    Если Не ПустаяСтрока(ТипЗначения(Объект)) Тогда
        Попытка
            Объект = Неопределено;
        Исключение
        КонецПопытки;
    КонецЕсли;
КонецПроцедуры

//===================================================================
// Пример вызова (можно разместить в обработке формы)
//===================================================================
// Экспорт за март 2024
// ЭкспортВедомостиВExcel(Дата(2024,3,1), Дата(2024,3,31), "C:\Temp\Vedomost_March2024.xlsx");
// Импорт в бухгалтерию (период – 01.03.2024)
// ИмпортВедомостиИзExcel("C:\Temp\Vedomost_March2024.xlsx", Дата(2024,3,1));

