// ---------------------------------------------------------------
// Пример автоматической настройки обмена «Начисления‑Зарплата → Бухгалтерия»
// в конфигураторе 1С:ЗУП 3.1 через объектный API (COM‑интерфейс).
// ---------------------------------------------------------------

// 1. Подключаемся к конфигуратору.  Внешний скрипт (например, .vbs, .js или .cs)
//    может использовать COM‑объект "V83.COMConnector".  Ниже показан
//    вариант на встроенном языке 1С – в обработке «Конфигуратор».

&НаКлиенте
Процедура НастроитьОбменДанными() Экспорт
    // Открываем конфигуратор в режиме редактирования
    Коннектор = Новый COMОбъект("V83.COMConnector");
    // Путь к файлу .1cd (конфигурация ЗУП) – укажите свой
    ПутьККонфигу = "C:\1C\Configurations\ZUP_3_1.1cd";
    // Параметры подключения (пользователь‑администратор без пароля)
    Параметры = Новый Структура("File", ПутьККонфигу, "User", "Administrator", "Password", "");
    // Открываем конфигуратор в режиме редактирования
    Конфигуратор = Коннектор.ПолучитьКонфигуратор(Параметры);

    // -----------------------------------------------------------
    // 2. Создаём новый объект «Обмен данными»
    // -----------------------------------------------------------
    Обмен = Конфигуратор.Объекты.ОбменДанными.Добавить();
    Обмен.Имя = "Обмен_ЗУП_Бухгалтерия";
    Обмен.Описание = "Передача начислений и выплат из ЗУП в бухгалтерию";

    // -----------------------------------------------------------
    // 3. Указываем источник – объекты ЗУП, которые будем экспортировать
    // -----------------------------------------------------------
    // 3.1. Регистры накопления
    ИсточникРегистры = Обмен.Источник.РегистрыНакопления;
    // Добавляем регистр «Начисления»
    РегНачисления = ИсточникРегистры.Добавить();
    РегНачисления.Имя = "Начисления"; // точное имя регистра в конфигурации ЗУП
    // Добавляем регистр «Выплаты»
    РегВыплаты = ИсточникРегистры.Добавить();
    РегВыплаты.Имя = "Выплаты";

    // 3.2. Документы
    ИсточникДокументы = Обмен.Источник.Документы;
    // Документ «Начисление»
    ДокНачисление = ИсточникДокументы.Добавить();
    ДокНачисление.Имя = "Начисление";
    // Документ «Выплата»
    ДокВыплата = ИсточникДокументы.Добавить();
    ДокВыплата.Имя = "Выплата";

    // -----------------------------------------------------------
    // 4. Указываем назначение – объекты бухгалтерии, куда будет импорт
    // -----------------------------------------------------------
    // 4.1. Регистры бухгалтерского учёта (например, «РегистрыБухгалтерии.РегОбороты»)
    НазначениеРегистры = Обмен.Назначение.РегистрыНакопления;
    // Пример: регистр «Обороты»
    РегОбороты = НазначениеРегистры.Добавить();
    РегОбороты.Имя = "Обороты"; // имя регистра в конфигурации Бухгалтерии

    // 4.2. Документы бухгалтерии – «Платёжная ведомость»
    НазначениеДокументы = Обмен.Назначение.Документы;
    ПлатёжнаяВедомость = НазначениеДокументы.Добавить();
    ПлатёжнаяВедомость.Имя = "ПлатёжнаяВедомость";

    // -----------------------------------------------------------
    // 5. Настраиваем параметры периодичности (планировщик)
    // -----------------------------------------------------------
    Планировщик = Обмен.Планировщик;
    Планировщик.Тип = ПланировщикТипы.Ежедневно; // ежедневный запуск
    Планировщик.Время = Время(2,0,0); // 02:00
    // При необходимости можно задать «Начало» и «Окончание» периода
    // Планировщик.ДатаНачала = ТекущаяДата();
    // Планировщик.ДатаОкончания = Неопределено();

    // -----------------------------------------------------------
    // 6. Правила сопоставления полей (Mapping)
    // -----------------------------------------------------------
    // 6.1. Сопоставление справочников «Сотрудник» → «Контрагент»
    СопоставлениеСправочники = Обмен.ПравилаСопоставления.Справочники;
    СопСотрудник = СопоставлениеСправочники.Добавить();
    СопСотрудник.Источник = "Справочник.Сотрудники"; // в ЗУП
    СопСотрудник.Назначение = "Справочник.Контрагенты"; // в Бухгалтерии
    // При необходимости задаём условие поиска (например, по ИНН)
    СопСотрудник.Условие = "ИНН"; // поле, по которому будет найден контрагент

    // 6.2. Сопоставление полей «СуммаНачисления» → «Сумма»
    СопПолей = Обмен.ПравилаСопоставления.Поля;
    СопСумма = СопПолей.Добавить();
    СопСумма.Источник = "СуммаНачисления"; // поле в регистре/документе ЗУП
    СопСумма.Назначение = "Сумма";          // поле в регистре/документе Бух.
    // При необходимости задаём тип преобразования (например, округление)
    СопСумма.ТипПреобразования = ТипПреобразования.Округление;
    СопСумма.Точность = 2;

    // -----------------------------------------------------------
    // 7. Сохраняем и активируем обмен
    // -----------------------------------------------------------
    // Сохраняем изменения конфигурации
    Конфигуратор.Записать();
    // Компилируем конфигурацию (обязательно после изменения метаданных)
    Конфигуратор.Компилировать();

    // Активируем обмен – в 1С это делается через объект «ОбменДанными.Активировать»
    Обмен.Активировать();

    // -----------------------------------------------------------
    // 8. Проверка корректности настроек
    // -----------------------------------------------------------
    // Метод ПроверитьНастройки() возвращает объект «РезультатПроверки»
    // с полями: Успешно (Булево) и Сообщения (Строка[])
    Результат = Обмен.ПроверитьНастройки();
    Если Результат.Успешно Тогда
        Сообщить("Настройки обмена успешно проверены.");
    Иначе
        Для Каждого Сообщение Из Результат.Сообщения Цикл
            Сообщить("Ошибка проверки: " + Сообщение);
        КонецЦикла;
        // При ошибках рекомендуется откатить изменения
        // Конфигуратор.Отменить();
    КонецЕсли;

    // Закрываем конфигуратор
    Конфигуратор.Закрыть();
КонецПроцедуры

