// ------------------------------------------------------------
//  Вывод записей из Журнала обмена за текущий месяц
//  с фильтрацией по типу документа и статусу выполнения.
//  Скопируйте код в обработку (или модуль формы) и запустите в
//  режиме отладки.
// ------------------------------------------------------------

&НаКлиенте // или &НаСервере – в зависимости от места размещения
Процедура ВывестиЗаписиЖурналаОбмена()
    // ==================== Параметры запроса ====================
    // -----------------------------------------------------------------
    // 1. Период – текущий месяц. При необходимости замените на любой
    //    произвольный диапазон дат.
    // -----------------------------------------------------------------
    ДатаНачала = НачалоМесяца(ТекущаяДата()); // <-- изменить при необходимости
    ДатаОкончания = КонецМесяца(ТекущаяДата()); // <-- изменить при необходимости

    // -----------------------------------------------------------------
    // 2. Типы документов, которые нужно отобрать. Можно добавить/удалить
    //    элементы массива.
    // -----------------------------------------------------------------
    ТипыДокументов = Новый Массив();
    ТипыДокументов.Добавить("Начисление"); // <-- добавить/удалить типы
    ТипыДокументов.Добавить("Выплата");

    // -----------------------------------------------------------------
    // 3. Статусы выполнения. Возможные значения: "Успешно", "Ошибка",
    //    "Предупреждение" и т.п. Добавляйте нужные варианты.
    // -----------------------------------------------------------------
    Статусы = Новый Массив();
    Статусы.Добавить("Успешно"); // <-- изменить/добавить статусы
    Статусы.Добавить("Ошибка");

    // ==================== Текст запроса ====================
    ТекстЗапроса = 
        "ВЫБРАТЬ" +
        "   ЖурналыОбмена.Дата            КАК Дата," +
        "   ЖурналыОбмена.ВидДокумента    КАК ВидДокумента," +
        "   ЖурналыОбмена.Статус          КАК Статус," +
        "   ЖурналыОбмена.Описание        КАК Описание," +
        "   ЖурналыОбмена.Объект          КАК Объект" +
        " ИЗ ЖурналОбмена КАК ЖурналыОбмена" +
        " ГДЕ ЖурналыОбмена.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания" +
        "   И ЖурналыОбмена.ВидДокумента   В (&ТипДокумента)" +
        "   И ЖурналыОбмена.Статус         В (&Статус)" +
        " УПОРЯДОЧИТЬ ПО ЖурналыОбмена.Дата УБЫВ";

    // ==================== Создание и выполнение запроса ====================
    Запрос = Новый Запрос;
    Запрос.Текст = ТекстЗапроса;

    // Передаём параметры в запрос
    Запрос.УстановитьПараметр("ДатаНачала",   ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    Запрос.УстановитьПараметр("ТипДокумента",  ТипыДокументов);
    Запрос.УстановитьПараметр("Статус",        Статусы);

    // Выполняем запрос и получаем результат
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    // ==================== Вывод результата ====================
    Сообщить("=== Записи Журнала обмена за " + Формат(ДатаНачала, "ДФ=dd.MM.yyyy") + " - " + Формат(ДатаОкончания, "ДФ=dd.MM.yyyy") + " ===");
    Пока Выборка.Следующий() Цикл
        Строка = "Дата: " + Формат(Выборка.Дата, "ДФ=dd.MM.yyyy HH:nn:ss") +
                 ", Вид: " + Выборка.ВидДокумента +
                 ", Статус: " + Выборка.Статус +
                 ", Описание: " + Выборка.Описание;
        Сообщить(Строка);
    КонецЦикла;

    Если НЕ Выборка.Количество() > 0 Тогда
        Сообщить("Записей не найдено.");
    КонецЕсли;
КонецПроцедуры

