//   • ДатаНачала / ДатаОкончания – задайте любой диапазон дат.
//   • ТипыДокументов – массив строк, соответствующих полю ВидДокумента.
//   • Статусы – массив строк, соответствующих полю Статус.
// ------------------------------------------------------------

//===================================================================
//  Скрипт‑отладчик для поиска и устранения дублей в регистре
//  "НакопленияЗарплаты" после обмена 1С:Зарплата ↔ 1С:Бухгалтерия.
//===================================================================
//  Параметры вызова (можно задать в диалоге или передать из внешнего кода):
//      ДатаНачала – начало проверяемого периода (Дата);
//      ДатаКонца  – конец проверяемого периода (Дата);
//      АвтоУдаление – логическое значение, если = Истина – дубли удаляются
//                     автоматически, иначе только выводится список.
//===================================================================

Процедура НайтиИУстранитьДублиНакопленияЗарплаты(ДатаНачала, ДатаКонца, АвтоУдаление = Ложь)
    // ---------------------------------------------------------------
    // 1. Проверка прав доступа. Скрипт должен запускаться от имени
    //    пользователя, имеющего право «Запись» в регистре "НакопленияЗарплаты".
    // ---------------------------------------------------------------
    Если НЕ Пользователь.ЕстьПрава(РегистрыНакопления.НакопленияЗарплаты, ПраваЗаписи) Тогда
        ВызватьИсключение "У пользователя нет прав на запись в регистр НакопленияЗарплаты";
    КонецЕсли;

    // ---------------------------------------------------------------
    // 2. Формируем запрос, который группирует записи по ключевым полям:
    //    Сотрудник, Дата, КодНачисления. Для каждой группы считаем количество
    //    записей (КолЗаписей). Если КолЗаписей > 1 – это дубли.
    // ---------------------------------------------------------------
    ТекстЗапроса = 
        "ВЫБРАТЬ" +
        "   Сотрудник," +
        "   Дата," +
        "   КодНачисления," +
        "   СУММА(Сумма) КАК Сумма," +
        "   СЧЁТ(*) КАК КолЗаписей" +
        "ИЗ" +
        "   РегистрНакопления.НакопленияЗарплаты" +
        "ГДЕ" +
        "   Дата МЕЖДУ &ДатаНачала И &ДатаКонца" +
        "СГРУППИРОВАТЬ ПО" +
        "   Сотрудник," +
        "   Дата," +
        "   КодНачисления" +
        "ИМЕЮЩИЕ" +
        "   СЧЁТ(*) > 1"; // оставляем только группы‑дубли

    Запрос = Новый Запрос;
    Запрос.Текст = ТекстЗапроса;
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаКонца",  ДатаКонца);

    Выборка = Запрос.Выполнить().Выбрать();

    // ---------------------------------------------------------------
    // 3. Если дублей нет – завершаем работу.
    // ---------------------------------------------------------------
    Если Выборка.Количество() = 0 Тогда
        Сообщить("Дубликаты в регистре НакопленияЗарплаты за указанный период не найдены.");
        Возврат;
    КонецЕсли;

    // ---------------------------------------------------------------
    // 4. Выводим найденные группы‑дубли в журнал регистрации.
    // ---------------------------------------------------------------
    Сообщить("=== Список дублей в регистре НакопленияЗарплаты ===");
    Пока Выборка.Следующий() Цикл
        Сообщить(СтрШаблон(
            "Сотрудник: %1, Дата: %2, КодНачисления: %3, Кол-во записей: %4, Сумма (общая): %5",

//===================================================================
//  Запрос‑отчёт «Расчёт по страховым взносам» за выбранный квартал
//===================================================================
//  Цель: получить суммарные начисления и суммы страховых взносов
//        (ПФР, ФОМС, ФСС) по каждому виду страхования за указанный
//        период (по умолчанию – текущий квартал).  Результат выводится
//        в табличный документ (ТабличныйДокумент), который затем можно
//        распечатать, подписать и загрузить в ЭДО.
//===================================================================

//===================================================================
//  1. Список используемых регистров
//===================================================================
//   • РегистрыНакопления.ЗарплатаИНалоги – хранит начисления и удержания
//     (в том числе страховые взносы) по сотрудникам.
//   • РегистрыСведений.СтраховыеВзносы – регистр сведений, в котором
//     фиксируются суммы взносов, распределённые по видам страхования.
//===================================================================

Процедура СформироватьОтчётПоСтраховымВзносам()
    // ---------------------------------------------------------------
    // 2. Параметры отчёта (можно изменить в пользовательском интерфейсе)
    // ---------------------------------------------------------------
    // Период расчёта – любой диапазон дат. По умолчанию берём квартал,
    // в котором находится текущая дата.
    ДатаНачала = НачалоКвартала(ТекущаяДата());
    ДатаОкончания = КонецКвартала(ТекущаяДата());

    // Если требуется задать произвольный период, замените две строки
    // выше, например:
    // ДатаНачала = Дата(2026,01,01);
    // ДатаОкончания = Дата(2026,03,31);

    // ---------------------------------------------------------------
    // 3. Текст запроса
    // ---------------------------------------------------------------
    ТекстЗапроса = 
        "ВЫБРАТЬ
" +
        "    СтраховыеВзносы.ВидСтрахования КАК ВидСтрахования,
" +
        "    СУММА(СтраховыеВзносы.Сумма) КАК СуммаВзноса,
" +
        "    СУММА(ЗарплатаИНалоги.РасчетныйНачисление) КАК СуммаНачисления,
" +
        "    СтраховыеВзносы.КодСтрахователя КАК КодСтрахователя // пользовательский реквизит
" +
        "ИЗ
" +
        "    РегистрыНакопления.ЗарплатаИНалоги КАК ЗарплатаИНалоги
" +
        "        ЛЕВОЕ СОЕДИНЕНИЕ РегистрыСведений.СтраховыеВзносы КАК СтраховыеВзносы
" +
        "        ПО ЗарплатаИНалоги.Период = СтраховыеВзносы.Период
" +
        "            И ЗарплатаИНалоги.Сотрудник = СтраховыеВзносы.Сотрудник
" +
        "ГДЕ
" +
        "    СтраховыеВзносы.Период МЕЖДУ &ДатаНачала И &ДатаОкончания
" +
        "СГРУППИРОВАТЬ ПО
" +
        "    СтраховыеВзносы.ВидСтрахования,
" +
        "    СтраховыеВзносы.КодСтрахователя;";

    // ---------------------------------------------------------------
    // 4. Создаём объект Запрос и передаём параметры периода
    // ---------------------------------------------------------------
    Запрос = Новый Запрос;
    Запрос.Текст = ТекстЗапроса;
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    // ---------------------------------------------------------------
    // 5. Выполняем запрос и получаем результат в виде ТаблицаЗначений
    // ---------------------------------------------------------------
    Результат = Запрос.Выполнить();
    Таблица = Результат.Выгрузить();

    // ---------------------------------------------------------------
    // 6. Формируем табличный документ (ТабличныйДокумент)
    // ---------------------------------------------------------------
    ТД = Новый ТабличныйДокумент;
    ТД.ШиринаКолонки(1) = 30; // Вид страхования
    ТД.ШиринаКолонки(2) = 20; // Сумма взноса
    ТД.ШиринаКолонки(3) = 20; // Сумма начисления
    ТД.ШиринаКолонки(4) = 20; // Код страхователя (доп. реквизит)

    // Шапка отчёта
    ТД.Ячейка(1, 1).Текст = "Вид страхования";
    ТД.Ячейка(1, 2).Текст = "Сумма взноса";
    ТД.Ячейка(1, 3).Текст = "Сумма начисления";
    ТД.Ячейка(1, 4).Текст = "Код страхователя";
    ТД.Ячейка(1, 1).ПолужирныйШрифт = Истина;
    ТД.Ячейка(1, 2).ПолужирныйШрифт = Истина;
    ТД.Ячейка(1, 3).ПолужирныйШрифт = Истина;
    ТД.Ячейка(1, 4).ПолужирныйШрифт = Истина;

    // Заполняем данными
    НомерСтроки = 2;
    Для Каждого Строка Из Таблица Цикл
        ТД.Ячейка(НомерСтроки, 1).Текст = Строка.ВидСтрахования;
        ТД.Ячейка(НомерСтроки, 2).Текст = Формат(Строка.СуммаВзноса, "ЧГ=2");
        ТД.Ячейка(НомерСтроки, 3).Текст = Формат(Строка.СуммаНачисления, "ЧГ=2");
        ТД.Ячейка(НомерСтроки, 4).Текст = Строка.КодСтрахователя;
        НомерСтроки = НомерСтроки + 1;
    КонецЦикла;

    // ---------------------------------------------------------------
    // 7. Выводим документ пользователю (можно сохранить в файл)
    // ---------------------------------------------------------------
    ТД.Показать(); // откроет табличный документ в окне 1С
    // Если нужно сохранить в файл Excel:
    // ТД.Экспортировать( "C:\Temp\РасчетСтраховыхВзносов.xlsx" );

КонецПроцедуры

//===================================================================
//  Как изменить период расчёта?
//===================================================================
//  • В строках 23‑24 задаётся период автоматически – текущий квартал.
//    Замените их на любые даты, например:
//        ДатаНачала = Дата(2025,10,01);
//        ДатаОкончания = Дата(2025,12,31);
//  • Можно добавить диалоговое окно для ввода дат пользователем:
//        Диалог = Новый ДиалогВыбораДаты();
//        Диалог.Заголовок = "Выберите период отчёта";
//        Если Диалог.Выбрать() Тогда
//            ДатаНачала = Диалог.ДатаНачала;
//            ДатаОкончания = Диалог.ДатаОкончания;
//        КонецЕсли;

//===================================================================
//  Как добавить пользовательский реквизит «КодСтрахователя»?
//===================================================================
//  1) В конфигурации откройте регистр сведений «СтраховыеВзносы».
//     Добавьте реквизит «КодСтрахователя» (Тип – Строка, Длина 10).
//  2) В запросе (см. строка 13) уже указано поле СтраховыеВзносы.КодСтрахователя.
//  3) В табличном документе добавлена 4‑я колонка – её ширина и заголовок
//     заданы в пунктах 6‑7 кода.
//  После изменения конфигурации необходимо выполнить «Обновить структуру
//  регистров», чтобы новые реквизиты стали доступны в запросе.
//===================================================================

//===================================================================
//  Запрос‑отчёт «Отчёт по налогу на доходы физических лиц (НДФЛ)»
//  Цель: расчёт удержаний НДФЛ за выбранный квартал, их распределение
//        по ставкам и сотрудникам, вывод сведений о налоговых вычетах.
//===================================================================

//===================================================================
//  Параметры запроса (заполняются в макете отчёта перед запуском)
//===================================================================
ПараметрыЗапроса = Новый Структура;
ПараметрыЗапроса.Вставить("ДатаНачала",   Дата(2023,01,01)); // начало квартала
ПараметрыЗапроса.Вставить("ДатаКонца",    Дата(2023,03,31)); // конец квартала
ПараметрыЗапроса.Вставить("СтатусПодлежитУдержанию", "Подлежит удержанию");

//===================================================================
//  Текст запроса (язык запросов 1С)
//===================================================================
ТекстЗапроса = 
"ВЫБРАТЬ
" +
"    РегистрыНакопления.ЗарплатаИНалоги.Сотрудник КАК Сотрудник,
" +
"    РегистрыНакопления.ЗарплатаИНалоги.ИНН КАК ИНН,
" +
"    РегистрыНакопления.ЗарплатаИНалоги.СтавкаНДФЛ КАК Ставка,
" +
"    СУММА(РегистрыНакопления.ЗарплатаИНалоги.СуммаУдержания) КАК СуммаУдержания,
" +
"    МАКСИМУМ(РегистрыНакопления.ЗарплатаИНалоги.ДатаВыплаты) КАК ДатаВыплаты,
" +
"    СУММА(РегистрыНакопления.ЗарплатаИНалоги.СуммаВычета) КАК СуммаВычета
" +
"ИЗ
" +
"    РегистрыНакопления.ЗарплатаИНалоги КАК РегистрыНакопления.ЗарплатаИНалоги
" +
"ГДЕ
" +
"    РегистрыНакопления.ЗарплатаИНалоги.Статус = &СтатусПодлежитУдержанию
" +
"    И РегистрыНакопления.ЗарплатаИНалоги.Период МЕЖДУ &ДатаНачала И &ДатаКонца
" +
"СГРУППИРОВАТЬ ПО
" +
"    Сотрудник,
" +
"    ИНН,
" +
"    Ставка;";

Запрос = Новый Запрос;
Запрос.Текст = ТекстЗапроса;
Запрос.УстановитьПараметр("ДатаНачала", ПараметрыЗапроса.ДатаНачала);
Запрос.УстановитьПараметр("ДатаКонца", ПараметрыЗапроса.ДатаКонца);
Запрос.УстановитьПараметр("СтатусПодлежитУдержанию", ПараметрыЗапроса.СтатусПодлежитУдержанию);

Результат = Запрос.Выполнить();

//===================================================================
//  Формирование печатной формы (Отчет)
//===================================================================
Отчет = Новый Отчет;
Отчет.Имя = "ОтчетПоНДФЛ";
Отчет.Заголовок = "Отчёт по налогу на доходы физических лиц (НДФЛ)";
Отчет.ДатаПериода = Строка(ПараметрыЗапроса.ДатаНачала) + " – " + Строка(ПараметрыЗапроса.ДатаКонца);

// Добавляем колонку «ИНН»
Отчет.Колонки.Добавить("ИНН", "ИНН", Новый ОписаниеТипов("Строка",,255));
// Добавляем колонку «Сотрудник» (ФИО)
Отчет.Колонки.Добавить("Сотрудник", "Сотрудник", Новый ОписаниеТипов("Строка",,255));
// Добавляем колонку «Ставка»
Отчет.Колонки.Добавить("Ставка", "Ставка НДФЛ, %", Новый ОписаниеТипов("Число",,5,2));
// Добавляем колонку «Сумма удержания»
Отчет.Колонки.Добавить("СуммаУдержания", "Сумма удержания", Новый ОписаниеТипов("Число",,15,2));
// Добавляем колонку «Дата выплаты»
Отчет.Колонки.Добавить("ДатаВыплаты", "Дата выплаты", Новый ОписаниеТипов("Дата"));
// Добавляем колонку «Сумма вычета» (если есть налоговые вычеты)
Отчет.Колонки.Добавить("СуммаВычета", "Сумма налогового вычета", Новый ОписаниеТипов("Число",,15,2));

// Заполняем строки отчёта данными из результата запроса
Для Каждого Строка Из Результат Выбрать() Цикл
    НоваяСтрока = Отчет.Строки.Добавить();
    НоваяСтрока.ИНН = Строка.ИНН;
    НоваяСтрока.Сотрудник = Строка.Сотрудник;
    НоваяСтрока.Ставка = Строка.Ставка;
    НоваяСтрока.СуммаУдержания = Строка.СуммаУдержания;
    НоваяСтрока.ДатаВыплаты = Строка.ДатаВыплаты;
    НоваяСтрока.СуммаВычета = Строка.СуммаВычета;
КонецЦикла;

//===================================================================
//  Добавление подписи ответственного лица и печати
//===================================================================
// В макете отчёта (XML‑шаблоне) необходимо разместить два поля:
//   • Поле "ПодписьОтветственного" – тип "Текст"; в коде заполняем:
Отчет.ПодписьОтветственного = "Иванов И.И. / Главный бухгалтер";
//   • Поле "Печать" – тип "Изображение"; в коде указываем путь к файлу печати:
Отчет.Печать = "C:\\Шаблоны\\Печать_Организации.png";
// В шаблоне эти поля привязываются к соответствующим элементам отчёта
// (например, через <Field Name="ПодписьОтветственного"/>).

//===================================================================
//  Вывод отчёта пользователю
//===================================================================
Отчет.Вывести();

//===================================================================
//  Сохранение отчёта в XML для последующего импорта в 1С:Бухгалтерия
//===================================================================
// 1. Формируем структуру, совместимую с форматом "XML‑Отчёт".
