XMLТекст = Отчет.ЗаписатьВXML(); // метод, реализованный в шаблоне отчёта

// 3. Сохраняем файл на диск.
ПутьКФайлу = "C:\\Отчёты\\ОтчетПоНДФЛ_" + Формат(ПараметрыЗапроса.ДатаНачала, "ГГГГММДД") + "_" + Формат(ПараметрыЗапроса.ДатаКонца, "ГГГГММДД") + ".xml";
ЗаписатьТекстВФайл(ПутьКФайлу, XMLТекст, КодировкаUTF8);

// 4. Инструкция для 1С:Бухгалтерия:
//    • Открыть обработку "ИмпортОтчётовXML" (в разделе "Администрирование → Обработки").
//    • Выбрать созданный файл *.xml и нажать "Импортировать".
