//===================================================================
//  Автоматическое заполнение табеля учёта рабочего времени за месяц
//===================================================================
// Параметры функции:
//   Сотрудник   – ссылка на объект Справочник.Сотрудники
//   НомерМесяца – целое число (1..12) – номер месяца текущего года
//===================================================================

/**
 * Заполняет табель рабочего времени для указанного сотрудника и месяца.
 *
 * @param Сотрудник   Справочник.Сотрудники   Ссылка на сотрудника
 * @param НомерМесяца Integer                 Номер месяца (1‑12)
 */
Процедура ЗаполнитьТабельРабочегоВремени(Сотрудник, НомерМесяца)
    // ---------------------------------------------------------------
    // 1. Формируем даты начала и конца месяца
    // ---------------------------------------------------------------
    ТекГод = ТекущаяДата().Год();
    ДатаНачала = НачалоМесяца(Дата(ТекГод, НомерМесяца, 1));
    ДатаКонца  = КонецМесяца(Дата(ТекГод, НомерМесяца, 1));

    // ---------------------------------------------------------------
    // 2. Ищем уже существующий документ «Табель учёта рабочего времени»
    //    для данного сотрудника и периода. Если не найден – создаём.
    // ---------------------------------------------------------------
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ ПЕРВЫЕ 1 Табель" +
        " ИЗ Документ.ТабельУчетаРабочегоВремени КАК Табель" +
        " ГДЕ Табель.Сотрудник = &Сотрудник" +
        "   И Табель.Период = &Период";
    Запрос.УстановитьПараметр("Сотрудник", Сотрудник);
    Запрос.УстановитьПараметр("Период", Дата(ТекГод, НомерМесяца, 1)); // период – любой день месяца, 1‑е число достаточно

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    Если Выборка.Следующий() Тогда
        Табель = Выборка.Табель; // уже существует
    Иначе
        Табель = Документы.ТабельУчетаРабочегоВремени.СоздатьДокумент();
        Табель.Сотрудник = Сотрудник;
        Табель.Период    = Дата(ТекГод, НомерМесяца, 1); // месяц, к которому относится табель
    КонецЕсли;

    // ---------------------------------------------------------------
    // 3. Очищаем табель от прежних строк (если документ уже был заполнен)
    // ---------------------------------------------------------------
    Табель.Строки.Очистить();

    // ---------------------------------------------------------------
    // 4. Получаем список рабочих дней (исключаем субботу и воскресенье)
    //    из регистра сведений "РабочиеДни". Предполагается, что в регистре
    //    хранятся даты, помеченные как рабочие (поле "Дата" и реквизит
    //    "Рабочий" = Истина).
    // ---------------------------------------------------------------
    ЗапросРабочиеДни = Новый Запрос;
    ЗапросРабочиеДни.Текст =
        "ВЫБРАТЬ Дата" +
        " ИЗ РегистрСведений.РабочиеДни КАК РабДн" +
        " ГДЕ РабДн.Дата МЕЖДУ &ДатаНачала И &ДатаКонца" +
        "   И РабДн.Рабочий = ИСТИНА";
    ЗапросРабочиеДни.УстановитьПараметр("ДатаНачала", ДатаНачала);
    ЗапросРабочиеДни.УстановитьПараметр("ДатаКонца",  ДатаКонца);

    РезультатРабочиеДни = ЗапросРабочиеДни.Выполнить();
    ВыборкаРабочиеДни = РезультатРабочиеДни.Выбрать();

    // ---------------------------------------------------------------
    // 5. Заполняем табель: для каждой рабочей даты добавляем строку
    //    с 8 рабочими часами.
    // ---------------------------------------------------------------
    Пока ВыборкаРабочиеДни.Следующий() Цикл
        НоваяСтрока = Табель.Строки.Добавить();
        НоваяСтрока.Дата          = ВыборкаРабочиеДни.Дата;
        НоваяСтрока.РабочиеЧасы   = 8; // 8 часов в день
        // При необходимости можно заполнить дополнительные реквизиты,
        // например, ВидРаботы, Ставка и т.п.
    КонецЦикла;

    // ---------------------------------------------------------------
    // 6. Проводим документ. Если документ уже был проведён – отменяем
    //    проведение и проводим заново (чтобы отразить новые строки).
    // ---------------------------------------------------------------
    Если Табель.Проведен Тогда
        Табель.ОтменитьПроведение();
    КонецЕсли;
    Табель.Записать(); // сохраняем изменения
    Табель.Провести(); // проводим

    // ---------------------------------------------------------------
    // 7. Информируем пользователя о результате
    // ---------------------------------------------------------------
    Сообщить("Табель " + Табель.Номер + " за " + Формат(ДатаНачала, "ММГГГГ") + " заполнен и проведён.");
КонецПроцедуры;

//===================================================================
// Метаданные, использованные в примере:
//   Документ.ТабельУчетаРабочегоВремени – документ, в котором хранится табель.
//   РегистрСведений.РабочиеДни – регистр сведений, содержащий даты, отмеченные
//                                 как рабочие (поле "Рабочий" = Истина).
//   Справочник.Сотрудники – справочник, откуда берётся объект Сотрудник.
//===================================================================

// Пример настройки параметров расчёта в конфигурации «1С:Зарплата и управление персоналом 3.1»
Процедура УстановитьПараметрыРасчета()
    // Объект настроек расчёта
    Настройки = Новый НастройкиРасчёта();
    // Ставка НДФЛ 13 %
    Настройки.СтавкаНДФЛ = 13;
    // Ставка страховых взносов в фонд ОПС 22 %
    Настройки.СтавкаСтраховыхВзносов = 22;
    // Ставка страховых взносов в фонд ОТ 2.9 %
    Настройки.СтавкаСтраховыхВзносовОТ = 2.9;
    // Округление начислений – в большую сторону до копеек
    Настройки.ОкруглениеНачислений = Перечисления.ТипыОкругления.ВБольшуюСторону;
    Настройки.КоличествоРазрядовОкругления = 2; // 2 разряда = копейки
    // Применить настройки к текущему расчёту
    Настройки.Применить();
    // Вывести сообщение о завершении
    Сообщить("Параметры расчёта успешно установлены.");
КонецПроцедуры

//===================================================================
//  Скрипт создания документов «Отпуск» и «Больничный лист»
//  через механизм обработки в 1С:Зарплата и управление персоналом 3.1
//===================================================================

&НаСервере
Процедура СоздатьОтпускИБольничныйЛист()
    // ---------------------------------------------------------------
    // 1. Поиск сотрудника по коду «EMP001»
    // ---------------------------------------------------------------
    Сотрудник = Справочники.Сотрудники.НайтиПоКоду("EMP001");
    Если Сотрудник = Неопределено Тогда
        Предупреждение("Сотрудник с кодом EMP001 не найден.");
        Возврат;
    КонецЕсли;

    // ---------------------------------------------------------------
    // 2. Создание и заполнение документа «Отпуск»
    // ---------------------------------------------------------------
    Отпуск = Документы.Отпуск.СоздатьДокумент();
    // Заполняем обязательные реквизиты
    Отпуск.Сотрудник      = Сотрудник;                     // ссылка на справочник Сотрудники
    Отпуск.ДатаНачала    = ТекущаяДата();                 // сегодня – условная дата начала отпуска
    Отпуск.ДатаОкончания = ТекущаяДата() + 9; // 10 календарных дней (включительно)
    // Тип отпуска – обычно берётся из перечисления «ТипОтпуска»
    // (в конфигурации может называться иначе – подставьте своё значение)
    Отпуск.ТипОтпуска    = Перечисления.ТипОтпуска.Основной;
    Отпуск.КоличествоДней = 10; // количество календарных дней отпуска

    // Сохраняем документ в базе
    Попытка
        Отпуск.Записать();
        Сообщить("Документ 'Отпуск' успешно записан.");
    Исключение
        Предупреждение("Ошибка при записи документа 'Отпуск': " + ОписаниеОшибки());
        Возврат;
    КонецПопытки;

    // ---------------------------------------------------------------
    // 3. Запуск расчёта зарплаты после создания отпуска
    // ---------------------------------------------------------------
    Попытка
        // Вызов обработки «РасчетЗарплаты». В конфигурации обычно есть обработка
        // с именем "РасчетЗарплаты". Если обработка имеет другой объект – замените.
        Обработки.РасчетЗарплаты.Выполнить(Отпуск);
        Сообщить("Расчёт зарплаты после отпуска выполнен успешно.");
    Исключение
        Предупреждение("Ошибка при расчёте зарплаты после отпуска: " + ОписаниеОшибки());
    КонецПопытки;

    // ---------------------------------------------------------------
    // 4. Создание и заполнение документа «Больничный лист»
    // ---------------------------------------------------------------
    БольничныйЛист = Документы.БольничныйЛист.СоздатьДокумент();
    БольничныйЛист.Сотрудник      = Сотрудник;
    БольничныйЛист.ДатаНачала    = ТекущаяДата();                 // сегодня – условная дата начала больничного
    БольничныйЛист.ДатаОкончания = ТекущаяДата() + 4; // 5 календарных дней (включительно)
    // Тип больничного – берём из перечисления «ТипБольничного»
    БольничныйЛист.ТипБольничного = Перечисления.ТипБольничного.Обычный;
    БольничныйЛист.КоличествоДней = 5;

    Попытка
        БольничныйЛист.Записать();
        Сообщить("Документ 'Больничный лист' успешно записан.");
    Исключение
        Предупреждение("Ошибка при записи документа 'Больничный лист': " + ОписаниеОшибки());
        Возврат;
    КонецПопытки;

    // ---------------------------------------------------------------
    // 5. Запуск расчёта зарплаты после создания больничного листа
    // ---------------------------------------------------------------
    Попытка
        Обработки.РасчетЗарплаты.Выполнить(БольничныйЛист);
        Сообщить("Расчёт зарплаты после больничного листа выполнен успешно.");
    Исключение
        Предупреждение("Ошибка при расчёте зарплаты после больничного листа: " + ОписаниеОшибки());
    КонецПопытки;

КонецПроцедуры

//===================================================================
// Как запустить:
// 1. Откройте конфигуратор, создайте обычный модуль (например, "МодульТестов").
// 2. Вставьте в него код выше.
// 3. В режиме отладки выполните вызов процедуры:
